/// Convert logical plan ReferentialAction to constraints module ReferentialAction
fn convert_logical_referential_action(
    action: &sql::logical_plan::ReferentialAction,
) -> sql::constraints::ReferentialAction {
    match action {
        sql::logical_plan::ReferentialAction::NoAction => sql::constraints::ReferentialAction::NoAction,
        sql::logical_plan::ReferentialAction::Restrict => sql::constraints::ReferentialAction::Restrict,
        sql::logical_plan::ReferentialAction::Cascade => sql::constraints::ReferentialAction::Cascade,
        sql::logical_plan::ReferentialAction::SetNull => sql::constraints::ReferentialAction::SetNull,
        sql::logical_plan::ReferentialAction::SetDefault => sql::constraints::ReferentialAction::SetDefault,
    }
}

/// Embedded database instance
///
/// Provides a simple API for embedded database usage (like SQLite).
///
/// # Examples
///
/// ```rust,no_run
/// use heliosdb_nano::EmbeddedDatabase;
///
/// # fn main() -> Result<(), Box<dyn std::error::Error>> {
/// let db = EmbeddedDatabase::new("./mydb.helio")?;
/// db.execute("CREATE TABLE test (id INT, name TEXT)")?;
/// # Ok(())
/// # }
/// ```
/// Slot holding one session's open transaction (R1.3-p2 deadlock fix).
///
/// The `session_transactions` DashMap used to store `Transaction` values
/// directly, and statements held the shard READ guard for their whole
/// execution — including row-lock waits (60s sleep-retry). COMMIT/ROLLBACK
/// need the shard WRITE lock (`remove`), so a committer holding row locks
/// could park behind executors of *other* sessions that hash to the same
/// shard while those executors waited on the committer's row locks: a
/// cross-session deadlock the row-lock wait-graph cannot see (observed as
/// a multi-minute livelock in `run_conflict_bench`'s contended_counter,
/// ~30% of runs; pre-existing on v3.50.0, exposed deterministically by the
/// R1.3-p2 gates). Wrapping the transaction in its own slot means shard
/// guards are held only for the map operation itself; statements borrow
/// through the slot's RwLock, which only same-session work ever contends.
type SessionTxnSlot = std::sync::Arc<parking_lot::RwLock<Option<storage::Transaction>>>;

/// Number of slots in the R-A1 cache-admission filter (`cache_admits`). Power
/// of two so the slot index is a mask, not a modulo. 1024 slots track enough
/// distinct hot query shapes that a real working set admits promptly while a
/// stream of unique-literal one-shots keeps overwriting a bounded footprint.
const CACHE_ADMISSION_SLOTS: usize = 1024;

/// Build a zeroed R-A1 admission slot table behind an `Arc`.
fn new_cache_admission() -> std::sync::Arc<[std::sync::atomic::AtomicU64; CACHE_ADMISSION_SLOTS]> {
    std::sync::Arc::new(std::array::from_fn(|_| std::sync::atomic::AtomicU64::new(0)))
}

pub struct EmbeddedDatabase {
    /// Storage engine (public for REPL access)
    pub storage: std::sync::Arc<storage::StorageEngine>,
    config: Config,
    /// Current active transaction (if any). parking_lot: non-poisonable — a
    /// panic mid-statement (e.g. from a COPY row routed through the global
    /// execute() path) must not wedge every later statement on this handle
    /// with a PoisonError.
    current_transaction: std::sync::Arc<parking_lot::Mutex<Option<storage::Transaction>>>,
    /// "Global transaction open" fast-out (R2.1). Mirrors
    /// `current_transaction.is_some()` and is updated *only* while holding
    /// the `current_transaction` mutex (begin/commit/rollback internals are
    /// the sole `Some`/`None` transition points). Lets the per-statement
    /// query/execute entry skip the mutex entirely in autocommit mode —
    /// the same pattern as `result_cache_nonempty`.
    global_txn_active: std::sync::Arc<std::sync::atomic::AtomicBool>,
    /// Tenant manager for multi-tenancy and RLS (optional)
    pub tenant_manager: std::sync::Arc<crate::tenant::TenantManager>,
    /// Trigger registry for trigger management and execution
    pub trigger_registry: std::sync::Arc<sql::TriggerRegistry>,
    /// Function registry for stored functions and procedures
    pub function_registry: std::sync::Arc<sql::FunctionRegistry>,
    /// MV scheduler for CPU-aware refresh scheduling
    mv_scheduler: std::sync::Arc<storage::MVScheduler>,
    /// Auto-refresh worker for background MV refresh (optional, requires async)
    auto_refresh_worker: std::sync::Arc<parking_lot::RwLock<Option<storage::AutoRefreshWorker>>>,
    /// Dump manager for database persistence
    pub dump_manager: std::sync::Arc<storage::DumpManager>,
    /// Session manager for multi-user support
    pub session_manager: std::sync::Arc<crate::session::SessionManager>,
    /// Lock manager for concurrency control
    pub lock_manager: std::sync::Arc<storage::LockManager>,
    /// Dirty tracker for tracking uncommitted changes
    pub dirty_tracker: std::sync::Arc<storage::DirtyTracker>,
    /// Active transactions per session. See [`SessionTxnSlot`] for why the
    /// transaction lives behind a per-session slot lock.
    session_transactions: std::sync::Arc<dashmap::DashMap<crate::session::SessionId, SessionTxnSlot>>,
    /// Prepared statements storage (name -> plan)
    prepared_statements: std::sync::Arc<parking_lot::RwLock<std::collections::HashMap<String, sql::LogicalPlan>>>,
    /// Original SQL for embedded prepared statements when available.
    prepared_statement_sql: std::sync::Arc<parking_lot::RwLock<std::collections::HashMap<String, String>>>,
    /// Fast embedded PREPARE metadata for simple PK lookups.
    prepared_fast_selects:
        std::sync::Arc<parking_lot::RwLock<std::collections::HashMap<String, PreparedFastSelectSpec>>>,
    /// Database-level settings for embedded SQL entry points.
    session_settings: sql::SessionSettings,
    /// Active savepoints stack (name -> transaction state)
    savepoints: std::sync::Arc<parking_lot::RwLock<Vec<SavepointState>>>,
    /// Plan cache: SQL string → `Arc<LogicalPlan>` (sharded LRU, skips parse+plan for repeated queries)
    plan_cache: std::sync::Arc<sharded_lru::ShardedLruCache<String, std::sync::Arc<sql::LogicalPlan>>>,
    /// Parse cache: SQL string → AST Statement (sharded LRU, skips SQL parsing for repeated queries)
    parse_cache: std::sync::Arc<sharded_lru::ShardedLruCache<String, sqlparser::ast::Statement>>,
    /// Query result cache: SQL string → cached results (invalidated on DML per-table)
    result_cache: std::sync::Arc<sharded_lru::ShardedLruCache<String, std::sync::Arc<Vec<Tuple>>>>,
    /// Fast DML invalidation gate; avoids taking the result-cache mutex when
    /// no query has populated it since the last invalidation.
    result_cache_nonempty: std::sync::Arc<std::sync::atomic::AtomicBool>,
    /// Last result-cache entry served. Hot repeated SELECTs avoid touching the
    /// sharded LRU on every call; cleared by the same invalidation gate.
    hot_result_cache_entry: std::sync::Arc<parking_lot::RwLock<Option<(String, std::sync::Arc<Vec<Tuple>>)>>>,
    /// Fingerprint of the most recent literal fast PK lookup. Used to avoid
    /// filling the result cache with one-off point lookups while still caching
    /// repeated hot-key queries after the second consecutive hit.
    last_fast_select_fingerprint: std::sync::Arc<std::sync::atomic::AtomicU64>,
    /// R-A1 cache-admission slot table (see `cache_admits`): fixed array of
    /// last-seen SQL fingerprints; a query is admitted to the cold-path caches
    /// only on a repeat sighting, so unique-literal queries stop churning them.
    cache_admission: std::sync::Arc<[std::sync::atomic::AtomicU64; CACHE_ADMISSION_SLOTS]>,
    /// Repeated parameterized INSERT metadata cache. Invalidated with the plan cache on DDL.
    fast_param_insert_cache: std::sync::Arc<sharded_lru::ShardedLruCache<String, std::sync::Arc<FastParamInsertSpec>>>,
    /// Repeated literal INSERT shape cache. Literal values differ per statement,
    /// but table/column metadata is stable until DDL.
    fast_literal_insert_cache:
        std::sync::Arc<sharded_lru::ShardedLruCache<String, std::sync::Arc<FastLiteralInsertSpec>>>,
    /// Repeated parameterized UPDATE metadata cache. Invalidated with the plan cache on DDL.
    fast_param_update_cache: std::sync::Arc<sharded_lru::ShardedLruCache<String, std::sync::Arc<FastParamUpdateSpec>>>,
    /// Last repeated parameterized UPDATE fast spec. Avoids the LRU mutex for hot prepared-style loops.
    hot_fast_param_update_spec:
        std::sync::Arc<parking_lot::RwLock<Option<(String, std::sync::Arc<FastParamUpdateSpec>)>>>,
    /// Repeated literal UPDATE shape cache. Literal values differ per statement,
    /// but table/column metadata is stable until DDL.
    fast_literal_update_cache:
        std::sync::Arc<sharded_lru::ShardedLruCache<String, std::sync::Arc<FastLiteralUpdateSpec>>>,
    /// Repeated parameterized DELETE metadata cache. Invalidated with the plan cache on DDL.
    fast_param_delete_cache: std::sync::Arc<sharded_lru::ShardedLruCache<String, std::sync::Arc<FastParamDeleteSpec>>>,
    /// Last repeated parameterized DELETE fast spec. Key includes FK validation mode/source.
    hot_fast_param_delete_spec:
        std::sync::Arc<parking_lot::RwLock<Option<(String, std::sync::Arc<FastParamDeleteSpec>)>>>,
    /// Repeated literal DELETE shape cache. Literal PK values differ per statement.
    fast_literal_delete_cache:
        std::sync::Arc<sharded_lru::ShardedLruCache<String, std::sync::Arc<FastLiteralDeleteSpec>>>,
    /// Repeated simple PK SELECT metadata cache. Literal/parameter values differ
    /// per statement, but table/PK metadata is stable until DDL.
    fast_select_cache: std::sync::Arc<sharded_lru::ShardedLruCache<String, std::sync::Arc<FastSelectSpec>>>,
    /// Last fast SELECT spec served (R2.1). Hot point-lookup workloads hit one
    /// (table, pk) spec on every statement; a read-mostly slot in front of the
    /// sharded LRU keeps that lookup off any mutex (mirrors
    /// `hot_fast_param_update_spec`). Cleared with the plan cache on DDL.
    hot_fast_select_spec: std::sync::Arc<parking_lot::RwLock<Option<std::sync::Arc<FastSelectSpec>>>>,
    /// Lightweight SQL-visible query profiler, disabled by default.
    query_profiler: std::sync::Arc<query_trace::QueryProfiler>,
    /// ART index undo log for transaction rollback: (table, row_id, col_values)
    /// Cleared on commit, replayed as on_delete on rollback
    art_undo_log: std::sync::Arc<parking_lot::RwLock<Vec<ArtUndoOp>>>,
    /// Per-session ART undo logs (R0.1). Session transactions mutate the ART
    /// indexes eagerly just like the global transaction path; their undo
    /// entries must be keyed by session so a session ROLLBACK replays exactly
    /// its own entries and a session COMMIT clears them — routing them into
    /// the global `art_undo_log` would let an unrelated global ROLLBACK
    /// un-index committed session rows (latent pre-R0.1 bug).
    session_art_undo: std::sync::Arc<dashmap::DashMap<crate::session::SessionId, Vec<ArtUndoOp>>>,
    /// Count of open session transactions. `DashMap::is_empty()` sweeps every
    /// shard lock (~128 on a 32-core host, ~1-2us) and sits on the per-statement
    /// fast-path gates; this atomic keeps those gates to one load.
    session_txn_count: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    /// Session-level FK validation mode used by embedded and protocol paths.
    fk_validation_mode: std::sync::Arc<parking_lot::RwLock<FkValidationMode>>,
    /// Source trusted for FK validation hints. Engine remains default.
    fk_validation_source: std::sync::Arc<parking_lot::RwLock<FkValidationSource>>,
    /// Deferred FK checks queued until COMMIT.
    deferred_fk_checks: std::sync::Arc<parking_lot::Mutex<Vec<PendingFkCheck>>>,
    /// Lazily-constructed, shared read-only optimizer for the cold (cache-miss)
    /// planning path. Every cache-miss query previously rebuilt a fresh
    /// `StatsCatalog` + 5 boxed rules + `Optimizer`; the rules are stateless
    /// `Send + Sync`, `StatsCatalog` is empty/constant, and `optimize*`/cost
    /// paths take `&self`, so a single instance is safely shareable with no
    /// lock. `OnceLock<Arc<_>>` clones cheaply (just an `Arc` bump) and avoids
    /// threading the field through the three constructors.
    cold_optimizer: std::sync::OnceLock<std::sync::Arc<optimizer::Optimizer>>,
}

impl Drop for EmbeddedDatabase {
    fn drop(&mut self) {
        // R4.2: checkpoint ART/HNSW index snapshots at clean shutdown so the
        // next open loads them instead of re-scanning every table. Skipped
        // when any transaction is still open — its eagerly-applied index
        // entries are not committed data and must not be snapshotted (the
        // next open rebuilds from rows instead, which is always correct).
        let txn_open = self.global_txn_active.load(std::sync::atomic::Ordering::Acquire)
            || self.session_txn_count.load(std::sync::atomic::Ordering::Acquire) > 0;
        if !txn_open && self.storage.index_snapshots_on_close() {
            if let Err(e) = self.storage.persist_index_snapshots() {
                tracing::warn!("index snapshot checkpoint at close failed: {}", e);
            }
        } else if txn_open {
            tracing::debug!("skipping index snapshot checkpoint: transaction still open at drop");
        }

        // Signal the auto-refresh worker to stop (non-blocking)
        if let Some(ref worker) = *self.auto_refresh_worker.read() {
            worker.request_stop();
        }

        // Clear session transactions
        self.session_transactions.clear();
        self.session_txn_count.store(0, std::sync::atomic::Ordering::Release);

        // Clear prepared statements
        self.prepared_statements.write().clear();
        self.prepared_statement_sql.write().clear();
        self.prepared_fast_selects.write().clear();

        // Clear plan cache
        self.plan_cache.clear();

        // Clear parse cache
        self.parse_cache.clear();

        // Clear savepoints
        self.savepoints.write().clear();

        tracing::debug!("EmbeddedDatabase dropped, resources cleaned up");
    }
}

/// Savepoint state for nested transaction support
#[derive(Clone)]
struct SavepointState {
    /// Savepoint name
    name: String,
    /// Snapshot of transaction staged writes at savepoint creation time.
    /// Used by ROLLBACK TO SAVEPOINT to undo data changes made after the savepoint.
    write_set_snapshot: storage::TransactionSavepointSnapshot,
    /// Length of the transaction's ART/vector-index undo log at savepoint
    /// creation time. Eager index maintenance (INSERT/UPDATE/DELETE) appends
    /// undo ops to this log; ROLLBACK TO SAVEPOINT replays and drops exactly
    /// the ops staged after the savepoint so the in-memory indexes match the
    /// rolled-back write set (without it, a post-savepoint INSERT leaves a
    /// ghost index entry that survives COMMIT — see the savepoint regression
    /// tests).
    art_undo_len: usize,
}

#[derive(Clone)]
enum ArtUndoOp {
    RemoveInserted {
        table_name: String,
        row_id: u64,
        col_values: std::collections::HashMap<String, Value>,
    },
    RestoreDeleted {
        table_name: String,
        row_id: u64,
        col_values: std::collections::HashMap<String, Value>,
    },
    RestoreUpdated {
        table_name: String,
        row_id: u64,
        old_col_values: std::collections::HashMap<String, Value>,
        new_col_values: std::collections::HashMap<String, Value>,
    },
    /// R5.V1: HNSW vector-index undo entries. Vector indexes are maintained
    /// eagerly at statement time exactly like ART, so their undo ops ride the
    /// same per-transaction (and per-session) log and are replayed by the
    /// same ROLLBACK paths.
    VectorUndo(Vec<storage::VectorIndexUndoOp>),
}

