    /// Flush buffered in-memory writes (the RocksDB memtable) to disk (SST files).
    ///
    /// Forces the memtable→SST split so reads, aggregates, and materialized-view
    /// (re)materialization can be exercised against data that spans both the
    /// memtable and flushed SSTs — i.e. the full LSM tree. Useful for tests that
    /// must reproduce scan-completeness behaviour without a large data set.
    pub fn flush(&self) -> Result<()> {
        self.storage.flush()
    }

    pub fn execute(&self, sql: &str) -> Result<u64> {

        // SQLite-compat: PRAGMA without a result-set (assignments / no-op
        // tunables) — `execute()` callers don't expect rows back.
        if let Some((_, _)) = crate::sql::sqlite_compat::parse_pragma(sql) {
            tracing::debug!("PRAGMA stubbed via execute(): {}", sql.trim());
            return Ok(0);
        }

        // Code-graph: intercept `CREATE AST INDEX …`, `hdb_code.pause`,
        // `hdb_code.resume` before the regular parser sees them.
        #[cfg(feature = "code-graph")]
        if let Some(ddl) = code_graph::detect_create_ast_index(sql) {
            return self.handle_create_ast_index(ddl);
        }
        #[cfg(feature = "code-graph")]
        if let Some(pr) = code_graph::detect_pause_resume(sql) {
            return self.handle_pause_resume(pr);
        }
        #[cfg(feature = "code-graph")]
        if let Some(ddl) = code_graph::detect_create_semantic_hash_index(sql) {
            return self.handle_create_semantic_hash_index(ddl);
        }
        // And rewrite any `lsp_*(…)` table-function references.
        // `ON BRANCH '…'` directives, if any, are scoped by a
        // CodeGraphBranchGuard that switches on construction and
        // restores on Drop — covers every early-return path below.
        #[cfg(feature = "code-graph")]
        let (rewritten_owned, _branch_guard) = self.rewrite_and_scope(sql);
        #[cfg(feature = "code-graph")]
        let sql: &str = &rewritten_owned;
        #[cfg(not(feature = "code-graph"))]
        let sql: &str = sql;

        let start = std::time::Instant::now();

        if let Some(count) = self.try_handle_trace_execute(sql)? {
            return Ok(count);
        }

        if let Some((_rows, _columns)) = self.try_handle_db_setting_statement_with_columns(sql)? {
            return Ok(0);
        }

        if let Some(count) = self.try_handle_fk_setting(sql)? {
            return Ok(count);
        }

        // R4.3: VACUUM VERSIONS — manual MVCC version-history collection.
        if let Some(count) = self.try_handle_vacuum_versions(sql)? {
            return Ok(count);
        }

        // Check if this is a transaction control statement
        if Self::is_transaction_control(sql) {
            return self.handle_transaction_control(sql);
        }

        let (result, defer_cache_invalidation) = {
            // R2.1: only touch the global-transaction mutex when the
            // fast-out flag says a transaction is open (flag transitions
            // happen under that mutex, so a `false` load is exactly the
            // "locked and found None" outcome without the lock).
            let txn_lock = if self.global_txn_active.load(std::sync::atomic::Ordering::Acquire) {
                Some(
                    self.current_transaction
                        .lock(),
                )
            } else {
                None
            };
            if let Some(txn_ref) = txn_lock.as_ref().and_then(|guard| guard.as_ref()) {
                // Execute within existing transaction context.
                (self.execute_in_transaction_no_fast_path(sql, txn_ref), true)
            } else {
                drop(txn_lock);
                if let Some(result) = self.try_autocommit_fast_insert(sql) {
                    (result, false)
                } else if let Some(result) = self.try_autocommit_fast_update_delete(sql) {
                    (result, false)
                } else {
                    // No active transaction - create implicit transaction
                    (self.execute_with_implicit_transaction(sql), false)
                }
            }
        };

        // Invalidate result cache on successful DML (any data modification)
        if result.is_ok() {
            if !defer_cache_invalidation {
                self.invalidate_result_cache();
            }
            #[cfg(feature = "code-graph")]
            {
                let touched = Self::touched_table_from_sql(sql);
                self.maybe_auto_reparse(touched.as_deref());
            }
        }

        let rows = result.as_ref().copied().unwrap_or(0);
        self.log_slow_query(sql, start.elapsed(), rows);
        result
    }

    /// Execute a SQL statement with RETURNING clause support
    ///
    /// Similar to `execute`, but returns the tuples from RETURNING clause
    /// if present. For INSERT/UPDATE/DELETE with RETURNING, returns the affected rows.
    ///
    /// # Arguments
    ///
    /// * `sql` - The SQL statement to execute
    ///
    /// # Returns
    ///
    /// A tuple of (rows_affected, returned_tuples). If no RETURNING clause is present,
    /// returned_tuples will be empty.
    ///
    /// # Example
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::EmbeddedDatabase;
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new_in_memory()?;
    /// db.execute("CREATE TABLE users (id INT, name TEXT)")?;
    ///
    /// // INSERT with RETURNING
    /// let (count, rows) = db.execute_returning(
    ///     "INSERT INTO users (id, name) VALUES (1, 'Alice') RETURNING *"
    /// )?;
    ///
    /// assert_eq!(count, 1);
    /// assert_eq!(rows.len(), 1);
    /// # Ok(())
    /// # }
    /// ```
    pub fn execute_returning(&self, sql: &str) -> Result<(u64, Vec<Tuple>)> {
        self.execute_params_returning(sql, &[])
    }

    /// Session transactions only block the autocommit INSERT fast paths when
    /// time-travel versioning is off: fast inserts write MVCC version keys,
    /// so versioned session-txn snapshot reads stay correct. With versioning
    /// disabled there is no version metadata to filter by, and the fast
    /// paths must yield to the fully snapshot-isolated slow path.
    fn session_txns_block_fast_inserts(&self) -> bool {
        self.any_session_txns() && !self.storage.time_travel_enabled()
    }

    /// Lock-free "any session transaction open?" check for hot-path gates.
    #[inline]
    fn any_session_txns(&self) -> bool {
        self.session_txn_count.load(std::sync::atomic::Ordering::Acquire) > 0
    }

    /// Execute eligible autocommit INSERTs without creating an empty implicit
    /// transaction around a direct fast-path storage write.
    fn try_autocommit_fast_insert(&self, sql: &str) -> Option<Result<u64>> {
        if !self.savepoints.read().is_empty()
            || self.session_txns_block_fast_inserts()
            || self.tenant_manager.get_current_context().is_some()
        {
            return None;
        }

        let result = self.try_fast_insert(sql)?;
        if result.is_ok() {
            if let Err(e) = self.storage.durable_autocommit_barrier() {
                return Some(Err(e));
            }
            self.storage.increment_lsn();
        }
        Some(result)
    }

    /// Execute eligible parameterized autocommit INSERTs through the same
    /// direct storage path used by literal INSERTs. This keeps PG-wire
    /// extended-protocol inserts from falling back to the slower
    /// versioned/logical-plan path on every row.
    fn try_autocommit_fast_insert_params(
        &self,
        sql: &str,
        plan: &sql::LogicalPlan,
        params: &[Value],
    ) -> Option<Result<u64>> {
        if self.in_transaction()
            || !self.savepoints.read().is_empty()
            || self.session_txns_block_fast_inserts()
            || self.tenant_manager.get_current_context().is_some()
            || self.storage.get_current_branch_id().is_some()
        {
            return None;
        }

        let spec = match self.fast_param_insert_spec(sql, plan)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };
        let tuple = match Self::materialize_fast_param_insert_tuple(&spec, params) {
            Ok(tuple) => tuple,
            Err(e) => return Some(Err(e)),
        };

        let result = self
            .storage
            .insert_tuple_fast(&spec.table_name, tuple, &spec.schema)
            .map(|_| 1);
        if result.is_ok() {
            if let Err(e) = self.storage.durable_autocommit_barrier() {
                return Some(Err(e));
            }
            self.storage.increment_lsn();
        }
        Some(result)
    }

    fn try_transaction_fast_insert_params(
        &self,
        sql: &str,
        plan: &sql::LogicalPlan,
        params: &[Value],
    ) -> Option<Result<u64>> {
        if !self.in_transaction()
            || !self.savepoints.read().is_empty()
            || self.any_session_txns()
            || self.tenant_manager.get_current_context().is_some()
        {
            return None;
        }

        let spec = match self.fast_param_insert_spec(sql, plan)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };
        let tuple = match Self::materialize_fast_param_insert_tuple(&spec, params) {
            Ok(tuple) => tuple,
            Err(e) => return Some(Err(e)),
        };

        let txn_guard = self.current_transaction.lock();
        let txn = txn_guard.as_ref()?;
        Some(self.insert_validated_tuple_in_transaction(&spec.table_name, tuple, &spec.schema, txn))
    }

    fn try_fast_insert_many_params(
        &self,
        sql: &str,
        plan: &sql::LogicalPlan,
        rows: &[Vec<Value>],
    ) -> Option<Result<u64>> {
        if rows.is_empty() {
            return Some(Ok(0));
        }
        if !self.savepoints.read().is_empty()
            || self.session_txns_block_fast_inserts()
            || self.tenant_manager.get_current_context().is_some()
            || self.storage.get_current_branch_id().is_some()
        {
            return None;
        }

        let spec = match self.fast_param_insert_spec(sql, plan)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };

        let mut tuples = Vec::with_capacity(rows.len());
        for params in rows {
            match Self::materialize_fast_param_insert_tuple(&spec, params) {
                Ok(tuple) => tuples.push(tuple),
                Err(e) => return Some(Err(e)),
            }
        }

        let txn_guard = self.current_transaction.lock();
        if let Some(txn) = txn_guard.as_ref() {
            return Some(self.insert_validated_tuples_in_transaction(&spec.table_name, tuples, &spec.schema, txn));
        }
        drop(txn_guard);

        if !self.storage.fast_dml_requires_logical_wal() && Self::fast_insert_batch_can_use_direct_write(&spec.schema) {
            let prepared = match self.prepare_fast_insert_batch(&spec.table_name, tuples, &spec.schema) {
                Ok(prepared) => prepared,
                Err(e) => return Some(Err(e)),
            };
            if let Err(e) = self.validate_fast_insert_batch(&spec.table_name, &spec.schema, &prepared) {
                return Some(Err(e));
            }
            let inserted =
                match self
                    .storage
                    .insert_prepared_tuples_fast_batch(&spec.table_name, prepared, &spec.schema)
                {
                    Ok(inserted) => inserted,
                    Err(e) => return Some(Err(e)),
                };
            if let Err(e) = self.storage.durable_autocommit_barrier() {
                return Some(Err(e));
            }
            self.storage.increment_lsn();
            return Some(Ok(inserted));
        }

        if !self.storage.fast_dml_requires_logical_wal() {
            let txn = match self.storage.begin_autocommit_transaction() {
                Ok(txn) => txn,
                Err(e) => return Some(Err(e)),
            };
            let inserted =
                match self.insert_validated_tuples_in_transaction(&spec.table_name, tuples, &spec.schema, &txn) {
                    Ok(inserted) => inserted,
                    Err(e) => {
                        let _ = txn.rollback();
                        self.rollback_art_undo_log();
                        self.deferred_fk_checks.lock().clear();
                        return Some(Err(e));
                    }
                };
            if let Err(e) = self.validate_deferred_fk_checks(Some(&txn)) {
                let _ = txn.rollback();
                self.rollback_art_undo_log();
                self.deferred_fk_checks.lock().clear();
                return Some(Err(e));
            }
            if let Err(e) = txn.commit() {
                self.rollback_art_undo_log();
                self.deferred_fk_checks.lock().clear();
                return Some(Err(e));
            }
            self.art_undo_log.write().clear();
            self.deferred_fk_checks.lock().clear();
            self.storage.increment_lsn();
            return Some(Ok(inserted));
        }

        let mut inserted = 0_u64;
        for tuple in tuples {
            if let Err(e) = self.storage.insert_tuple_fast(&spec.table_name, tuple, &spec.schema) {
                if inserted > 0 {
                    self.invalidate_result_cache();
                }
                return Some(Err(e));
            }
            inserted += 1;
            if let Err(e) = self.storage.durable_autocommit_barrier() {
                return Some(Err(e));
            }
            self.storage.increment_lsn();
        }
        Some(Ok(inserted))
    }

    /// R-B1: bulk-apply a decoded `COPY … FROM STDIN` batch through the fast
    /// insert-batch machinery, bypassing the old per-chunk
    /// render-to-SQL → sqlparser → generic-plan-arm path (which cost a ~25KB
    /// INSERT string, a full parse, an AST deep-clone into the parse cache, and
    /// the generic per-row Insert arm — the ~23µs/row COPY was dominated by it).
    ///
    /// The whole COPY is validated and applied as ONE atomic unit (single
    /// WriteBatch when the schema allows a direct write, else one autocommit
    /// transaction), matching PostgreSQL's all-or-nothing COPY semantics: a
    /// constraint failure on any row rejects the entire COPY and a crash
    /// mid-COPY exposes zero rows. This is a deliberate behavior change from the
    /// old per-500-row-chunk commit (which left earlier chunks visible on a
    /// later failure).
    ///
    /// Returns `None` to signal the caller to fall back to the generic SQL path
    /// — used for every shape this fast path does not cover, so semantics are
    /// preserved exactly: an open transaction (handled separately), triggers,
    /// RLS/tenant context, an active branch, FK/CHECK constraints (via
    /// `fast_literal_insert_spec`), dictionary/CAS column storage, or an HA/
    /// logical-WAL requirement.
    pub(crate) fn copy_bulk_insert(
        &self,
        table_name: &str,
        columns: &[String],
        rows: &[Vec<Option<String>>],
    ) -> Option<Result<u64>> {
        if rows.is_empty() {
            return Some(Ok(0));
        }
        // Fall back for every shape the fast batch path does not preserve.
        if self.in_transaction()
            || self.any_session_txns()
            || !self.savepoints.read().is_empty()
            || self.tenant_manager.get_current_context().is_some()
            || self.storage.get_current_branch_id().is_some()
            || self.trigger_registry.has_triggers_for_table(table_name)
            || self.storage.fast_dml_requires_logical_wal()
        {
            return None;
        }

        let explicit_columns: Option<Vec<&str>> =
            (!columns.is_empty()).then(|| columns.iter().map(String::as_str).collect());
        // `fast_literal_insert_spec` resolves the schema + column indices and
        // itself bails (→ None) on FK/CHECK constraints or an unknown table/
        // column — exactly the cases the generic path must handle.
        let spec = match self.fast_literal_insert_spec(table_name, explicit_columns.as_deref(), None)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };
        // Dictionary/CAS column storage needs the per-row transform; let the
        // generic path handle those tables.
        if !Self::fast_insert_batch_can_use_direct_write(&spec.schema) {
            return None;
        }

        // Decode every row up front. Any malformed row or failed cast rejects
        // the whole COPY before a single write (atomicity).
        let mut tuples = Vec::with_capacity(rows.len());
        for row in rows {
            match Self::materialize_copy_tuple(&spec, row) {
                Ok(tuple) => tuples.push(tuple),
                Err(e) => return Some(Err(e)),
            }
        }

        // Suspend SMFI delta tracking for the whole load (one rebuild after,
        // not one per row), matching the other bulk-insert entry points.
        let _smfi_guard = self
            .storage
            .suspend_smfi_for_bulk_load(table_name, storage::filter_index_delta::BulkLoadReason::CopyFrom);

        let prepared = match self.prepare_fast_insert_batch(table_name, tuples, &spec.schema) {
            Ok(prepared) => prepared,
            Err(e) => return Some(Err(e)),
        };
        if let Err(e) = self.validate_fast_insert_batch(table_name, &spec.schema, &prepared) {
            return Some(Err(e));
        }
        let inserted = match self
            .storage
            .insert_prepared_tuples_fast_batch(table_name, prepared, &spec.schema)
        {
            Ok(inserted) => inserted,
            Err(e) => return Some(Err(e)),
        };
        if let Err(e) = self.storage.durable_autocommit_barrier() {
            return Some(Err(e));
        }
        self.storage.increment_lsn();
        self.invalidate_result_cache();
        Some(Ok(inserted))
    }

    /// Materialize one decoded COPY row (`Vec<Option<String>>`, `None` = the
    /// NULL sentinel) into a full-width tuple. Mirrors the old
    /// render-to-SQL-then-parse path's typing: each non-NULL field was rendered
    /// as a quoted string literal and cast to the column type, so here each
    /// `Some(text)` becomes `Value::String(text)` cast via `fast_cast_value` —
    /// the same result, without the SQL round-trip.
    fn materialize_copy_tuple(spec: &FastLiteralInsertSpec, row: &[Option<String>]) -> Result<Tuple> {
        if row.len() != spec.col_indices.len() {
            return Err(Error::query_execution(format!(
                "COPY row has {} fields but {} target columns",
                row.len(),
                spec.col_indices.len()
            )));
        }

        let mut tuple_values = vec![Value::Null; spec.schema.columns.len()];
        let mut user_provided = if spec.all_columns_explicit_no_default {
            Vec::new()
        } else {
            vec![false; spec.schema.columns.len()]
        };

        for (i, (&col_idx, target_type)) in spec.col_indices.iter().zip(&spec.target_types).enumerate() {
            let value = match &row[i] {
                None => Value::Null,
                Some(text) => Self::fast_cast_value(Value::String(text.clone()), target_type)?,
            };
            if let Some(slot) = tuple_values.get_mut(col_idx) {
                *slot = value;
            }
            if !spec.all_columns_explicit_no_default {
                if let Some(flag) = user_provided.get_mut(col_idx) {
                    *flag = true;
                }
            }
        }

        if spec.all_columns_explicit_no_default {
            Self::check_not_null_for_materialized_insert(&tuple_values, &spec.schema)?;
        } else {
            Self::apply_defaults_and_check_not_null(&mut tuple_values, &spec.schema, &user_provided)?;
        }
        Ok(Tuple::new(tuple_values))
    }

    fn fast_insert_batch_can_use_direct_write(schema: &Schema) -> bool {
        // R3.3: STORAGE COLUMNAR schemas take the direct WriteBatch path too
        // (grouped batch writes ride the same WriteBatch as the rows);
        // dictionary/CAS still require the per-row transform.
        schema.columns.iter().all(|column| {
            matches!(
                column.storage_mode,
                ColumnStorageMode::Default | ColumnStorageMode::Columnar
            )
        })
    }

    fn fast_literal_insert_cache_key(table_name: &str, columns: Option<&[&str]>) -> String {
        let mut key = String::with_capacity(table_name.len() + columns.map_or(8, |cols| cols.len() * 12));
        key.push_str("\0fast_literal_insert\0");
        key.push_str(table_name);
        key.push('\0');
        if let Some(columns) = columns {
            for column in columns {
                key.push_str(column);
                key.push('\0');
            }
        } else {
            key.push('*');
        }
        key
    }

    fn fast_literal_insert_spec(
        &self,
        table_name: &str,
        explicit_columns: Option<&[&str]>,
        value_count: Option<usize>,
    ) -> Option<Result<std::sync::Arc<FastLiteralInsertSpec>>> {
        if matches!(value_count, Some(0)) {
            return None;
        }

        let cache_key = Self::fast_literal_insert_cache_key(table_name, explicit_columns);
        if let Some(spec) = self.fast_literal_insert_cache.get(&cache_key) {
            if value_count.map_or(true, |count| spec.target_types.len() == count) {
                return Some(Ok(spec));
            }
            return None;
        }

        let catalog = self.storage.catalog();
        let schema = match catalog.get_table_schema(table_name) {
            Ok(schema) => std::sync::Arc::new(schema),
            Err(_) => return None,
        };

        if let Ok(tc) = catalog.load_table_constraints(table_name) {
            if !tc.foreign_keys.is_empty() || !tc.check_constraints.is_empty() {
                return None;
            }
        }

        let column_names: Vec<&str> = explicit_columns.map_or_else(
            || schema.columns.iter().map(|c| c.name.as_str()).collect(),
            |columns| columns.to_vec(),
        );
        if column_names.is_empty() || value_count.is_some_and(|count| column_names.len() != count) {
            return None;
        }

        let mut col_indices = Vec::with_capacity(column_names.len());
        let mut target_types = Vec::with_capacity(column_names.len());
        let mut provided_columns = vec![false; schema.columns.len()];
        for col_name in &column_names {
            let col_idx = match schema.get_column_index(col_name) {
                Some(idx) => idx,
                None => return None,
            };
            if provided_columns.get(col_idx).copied().unwrap_or(false) {
                return None;
            }
            if let Some(provided) = provided_columns.get_mut(col_idx) {
                *provided = true;
            }
            let target_col = match schema.get_column_at(col_idx) {
                Some(col) => col,
                None => return None,
            };
            col_indices.push(col_idx);
            target_types.push(target_col.data_type.clone());
        }

        let spec = std::sync::Arc::new(FastLiteralInsertSpec {
            table_name: table_name.to_string(),
            schema,
            col_indices,
            target_types,
            all_columns_explicit_no_default: provided_columns.iter().all(|provided| *provided),
        });
        self.fast_literal_insert_cache
            .put(cache_key, std::sync::Arc::clone(&spec));
        Some(Ok(spec))
    }

    fn materialize_fast_literal_insert_tuple(spec: &FastLiteralInsertSpec, values_str: &str) -> Option<Result<Tuple>> {
        let mut tuple_values = vec![Value::Null; spec.schema.columns.len()];
        let mut user_provided = if spec.all_columns_explicit_no_default {
            Vec::new()
        } else {
            vec![false; spec.schema.columns.len()]
        };

        let mut remaining = values_str;
        for (i, (&col_idx, target_type)) in spec.col_indices.iter().zip(&spec.target_types).enumerate() {
            remaining = remaining.trim_start();
            if remaining.is_empty() {
                return None;
            }

            let (mut value, rest) = Self::fast_parse_one_value(remaining, target_type)?;
            if Self::insert_value_needs_cast(&value, target_type) {
                value = match Self::fast_cast_value(value, target_type) {
                    Ok(value) => value,
                    Err(e) => return Some(Err(e)),
                };
            }
            if let Some(slot) = tuple_values.get_mut(col_idx) {
                *slot = value;
            }
            if !spec.all_columns_explicit_no_default {
                if let Some(flag) = user_provided.get_mut(col_idx) {
                    *flag = true;
                }
            }

            if i + 1 == spec.target_types.len() {
                if !rest.trim().is_empty() {
                    return None;
                }
                break;
            }

            let rest = rest.trim_start();
            if let Some(next) = rest.strip_prefix(',') {
                remaining = next;
            } else {
                return None;
            }
        }

        let result = if spec.all_columns_explicit_no_default {
            Self::check_not_null_for_materialized_insert(&tuple_values, &spec.schema)
        } else {
            Self::apply_defaults_and_check_not_null(&mut tuple_values, &spec.schema, &user_provided)
        };
        if let Err(e) = result {
            return Some(Err(e));
        }
        Some(Ok(Tuple::new(tuple_values)))
    }

    fn fast_param_insert_spec(
        &self,
        sql: &str,
        plan: &sql::LogicalPlan,
    ) -> Option<Result<std::sync::Arc<FastParamInsertSpec>>> {
        let cache_key = format!("\0fast_param_insert\0{sql}");
        if let Some(spec) = self.fast_param_insert_cache.get(&cache_key) {
            return Some(Ok(spec));
        }

        let spec = match self.build_fast_param_insert_spec(plan)? {
            Ok(spec) => std::sync::Arc::new(spec),
            Err(e) => return Some(Err(e)),
        };
        self.fast_param_insert_cache
            .put(cache_key, std::sync::Arc::clone(&spec));
        Some(Ok(spec))
    }

    fn build_fast_param_insert_spec(&self, plan: &sql::LogicalPlan) -> Option<Result<FastParamInsertSpec>> {
        let sql::LogicalPlan::Insert {
            table_name,
            columns,
            values,
            returning,
            on_conflict,
        } = plan
        else {
            return None;
        };

        if returning.is_some() || on_conflict.is_some() || values.len() != 1 {
            return None;
        }
        if self.tenant_manager.should_apply_rls(table_name, "INSERT") {
            return None;
        }
        if self.trigger_registry.has_triggers_for_table(table_name) {
            return None;
        }

        let catalog = self.storage.catalog();
        let schema = match catalog.get_table_schema(table_name) {
            Ok(schema) => std::sync::Arc::new(schema),
            Err(_) => return None,
        };
        if let Ok(tc) = catalog.load_table_constraints(table_name) {
            if !tc.foreign_keys.is_empty() || !tc.check_constraints.is_empty() {
                return None;
            }
        }

        let column_names: Vec<&str> = columns.as_ref().map_or_else(
            || schema.columns.iter().map(|c| c.name.as_str()).collect(),
            |cols| cols.iter().map(String::as_str).collect(),
        );
        let value_row = values.first()?;
        if column_names.len() != value_row.len() {
            return None;
        }

        let mut insert_columns = Vec::with_capacity(column_names.len());
        let mut provided_columns = vec![false; schema.columns.len()];
        let mut all_columns_explicit_no_default = column_names.len() == schema.columns.len();
        for (col_name, expr) in column_names.iter().zip(value_row) {
            let col_idx = match schema.get_column_index(col_name) {
                Some(idx) => idx,
                None => return None,
            };
            if provided_columns.get(col_idx).copied().unwrap_or(false) {
                all_columns_explicit_no_default = false;
            } else if let Some(provided) = provided_columns.get_mut(col_idx) {
                *provided = true;
            }
            let target_col = match schema.get_column_at(col_idx) {
                Some(col) => col,
                None => return None,
            };
            if !Self::fast_param_insert_expr_supported(expr) {
                return None;
            }
            if matches!(expr, sql::LogicalExpr::DefaultValue) {
                all_columns_explicit_no_default = false;
            }
            insert_columns.push(FastParamInsertColumn {
                col_idx,
                data_type: target_col.data_type.clone(),
                expr: expr.clone(),
            });
        }
        if !provided_columns.iter().all(|provided| *provided) {
            all_columns_explicit_no_default = false;
        }

        Some(Ok(FastParamInsertSpec {
            table_name: table_name.clone(),
            schema,
            columns: insert_columns,
            all_columns_explicit_no_default,
        }))
    }

    fn materialize_fast_param_insert_tuple(spec: &FastParamInsertSpec, params: &[Value]) -> Result<Tuple> {
        let mut tuple_values = vec![Value::Null; spec.schema.columns.len()];
        let mut user_provided = if spec.all_columns_explicit_no_default {
            Vec::new()
        } else {
            vec![false; spec.schema.columns.len()]
        };

        for column in &spec.columns {
            if matches!(column.expr, sql::LogicalExpr::DefaultValue) {
                continue;
            }

            let mut value = match Self::fast_eval_param_expr(&column.expr, params) {
                Some(value) => value?,
                None => {
                    let evaluator = sql::Evaluator::with_parameters(
                        std::sync::Arc::new(Schema { columns: vec![] }),
                        params.to_vec(),
                    );
                    evaluator.evaluate(&column.expr, &Tuple::new(vec![]))?
                }
            };
            if Self::insert_value_needs_cast(&value, &column.data_type) {
                value = Self::fast_cast_value(value, &column.data_type)?;
            }

            if let Some(slot) = tuple_values.get_mut(column.col_idx) {
                *slot = value;
            }
            if !spec.all_columns_explicit_no_default {
                if let Some(flag) = user_provided.get_mut(column.col_idx) {
                    *flag = true;
                }
            }
        }

        if spec.all_columns_explicit_no_default {
            Self::check_not_null_for_materialized_insert(&tuple_values, &spec.schema)?;
        } else {
            Self::apply_defaults_and_check_not_null(&mut tuple_values, &spec.schema, &user_provided)?;
        }
        Ok(Tuple::new(tuple_values))
    }

    fn check_not_null_for_materialized_insert(tuple_values: &[Value], schema: &Schema) -> Result<()> {
        for (idx, col) in schema.columns.iter().enumerate() {
            if col.nullable || col.primary_key {
                continue;
            }
            if matches!(tuple_values.get(idx), Some(Value::Null)) {
                return Err(Error::constraint_violation(format!(
                    "NOT NULL constraint violated: cannot insert NULL into column '{}'",
                    col.name
                )));
            }
        }
        Ok(())
    }

    fn fast_param_insert_expr_supported(expr: &sql::LogicalExpr) -> bool {
        match expr {
            sql::LogicalExpr::Literal(_) | sql::LogicalExpr::Parameter { .. } | sql::LogicalExpr::DefaultValue => true,
            sql::LogicalExpr::Cast { expr, .. } => Self::fast_param_insert_expr_supported(expr),
            _ => false,
        }
    }

    fn fast_param_value(index: usize, params: &[Value]) -> Result<Value> {
        if index == 0 {
            return Err(Error::query_execution(
                "Parameter indices must be 1-based (e.g., $1, $2)",
            ));
        }

        params.get(index - 1).cloned().ok_or_else(|| {
            Error::query_execution(format!(
                "Parameter ${} not provided. Expected {} parameters, got {}",
                index,
                index,
                params.len()
            ))
        })
    }

    fn fast_eval_param_expr(expr: &sql::LogicalExpr, params: &[Value]) -> Option<Result<Value>> {
        match expr {
            sql::LogicalExpr::Literal(value) => Some(Ok(value.clone())),
            sql::LogicalExpr::Parameter { index } => Some(Self::fast_param_value(*index, params)),
            sql::LogicalExpr::Cast { expr, data_type } => {
                let value = match Self::fast_eval_param_expr(expr, params)? {
                    Ok(value) => value,
                    Err(e) => return Some(Err(e)),
                };
                Some(Self::fast_cast_value(value, data_type))
            }
            sql::LogicalExpr::DefaultValue => None,
            _ => None,
        }
    }

    fn fast_cast_value(value: Value, target_type: &DataType) -> Result<Value> {
        match (value, target_type) {
            (value @ Value::Null, _) => Ok(value),
            (value @ Value::Int2(_), DataType::Int2)
            | (value @ Value::Int4(_), DataType::Int4)
            | (value @ Value::Int8(_), DataType::Int8)
            | (value @ Value::Float4(_), DataType::Float4)
            | (value @ Value::Float8(_), DataType::Float8)
            | (value @ Value::String(_), DataType::Text | DataType::Varchar(_))
            | (value @ Value::Boolean(_), DataType::Boolean)
            | (value @ Value::Json(_), DataType::Json | DataType::Jsonb) => Ok(value),
            (Value::Int2(v), DataType::Int4) => Ok(Value::Int4(i32::from(v))),
            (Value::Int2(v), DataType::Int8) => Ok(Value::Int8(i64::from(v))),
            (Value::Int4(v), DataType::Int2) => i16::try_from(v)
                .map(Value::Int2)
                .map_err(|_| Error::type_conversion(format!("INTEGER value {} out of range for SMALLINT", v))),
            (Value::Int4(v), DataType::Int8) => Ok(Value::Int8(i64::from(v))),
            (Value::Int8(v), DataType::Int2) => i16::try_from(v)
                .map(Value::Int2)
                .map_err(|_| Error::type_conversion(format!("BIGINT value {} out of range for SMALLINT", v))),
            (Value::Int8(v), DataType::Int4) => i32::try_from(v)
                .map(Value::Int4)
                .map_err(|_| Error::type_conversion(format!("BIGINT value {} out of range for INTEGER", v))),
            (Value::Int2(v), DataType::Float4) => Ok(Value::Float4(v as f32)),
            (Value::Int2(v), DataType::Float8) => Ok(Value::Float8(v as f64)),
            (Value::Int4(v), DataType::Float4) => Ok(Value::Float4(v as f32)),
            (Value::Int4(v), DataType::Float8) => Ok(Value::Float8(v as f64)),
            (Value::Int8(v), DataType::Float4) => Ok(Value::Float4(v as f32)),
            (Value::Int8(v), DataType::Float8) => Ok(Value::Float8(v as f64)),
            (Value::Float4(v), DataType::Float8) => Ok(Value::Float8(f64::from(v))),
            (value, _) => {
                let evaluator = sql::Evaluator::new(std::sync::Arc::new(Schema { columns: vec![] }));
                evaluator.cast_value(value, target_type)
            }
        }
    }

    fn insert_value_needs_cast(value: &Value, target_type: &DataType) -> bool {
        match (value, target_type) {
            (Value::Null, _) => false,
            (Value::Vector(_), DataType::Vector(_)) => true,
            (Value::String(_), DataType::Vector(_)) => true,
            (Value::String(_), DataType::Json | DataType::Jsonb) => true,
            (Value::Int4(_), DataType::Int4) => false,
            (Value::Int8(_), DataType::Int8) => false,
            (Value::Float4(_), DataType::Float4) => false,
            (Value::Float8(_), DataType::Float8) => false,
            (Value::String(_), DataType::Text | DataType::Varchar(_)) => false,
            (Value::Boolean(_), DataType::Boolean) => false,
            (Value::Json(_), DataType::Json | DataType::Jsonb) => false,
            _ => true,
        }
    }

    fn try_autocommit_fast_update_delete_params(
        &self,
        sql: &str,
        plan: &sql::LogicalPlan,
        params: &[Value],
    ) -> Option<Result<u64>> {
        if self.in_transaction()
            || !self.savepoints.read().is_empty()
            || self.any_session_txns()
            || self.tenant_manager.get_current_context().is_some()
            || self.storage.get_current_branch_id().is_some()
        {
            return None;
        }

        match plan {
            sql::LogicalPlan::Update {
                table_name,
                assignments,
                selection,
                returning,
            } => self.try_fast_update_params(sql, table_name, assignments, selection, returning, params),
            sql::LogicalPlan::Delete {
                table_name,
                selection,
                returning,
            } => self.try_fast_delete_params(sql, table_name, selection, returning, params),
            _ => None,
        }
    }

    fn try_autocommit_fast_update_delete_many_params(
        &self,
        sql: &str,
        plan: &sql::LogicalPlan,
        rows: &[Vec<Value>],
    ) -> Option<Result<u64>> {
        if rows.is_empty() {
            return Some(Ok(0));
        }
        if self.in_transaction()
            || !self.savepoints.read().is_empty()
            || self.any_session_txns()
            || self.tenant_manager.get_current_context().is_some()
            || self.storage.get_current_branch_id().is_some()
        {
            return None;
        }

        match plan {
            sql::LogicalPlan::Update {
                table_name,
                assignments,
                selection,
                returning,
            } => {
                let spec = match self.fast_param_update_spec(sql, table_name, assignments, selection, returning)? {
                    Ok(spec) => spec,
                    Err(e) => return Some(Err(e)),
                };
                let mut total = 0_u64;
                for params in rows {
                    match self.try_execute_fast_update_param_spec(&spec, params) {
                        Some(Ok(count)) => total += count,
                        Some(Err(e)) => {
                            if total > 0 {
                                self.invalidate_result_cache();
                            }
                            return Some(Err(e));
                        }
                        None => {
                            if total > 0 {
                                self.invalidate_result_cache();
                            }
                            return Some(Err(Error::internal(
                                "fast parameterized UPDATE batch became ineligible",
                            )));
                        }
                    }
                }
                Some(Ok(total))
            }
            sql::LogicalPlan::Delete {
                table_name,
                selection,
                returning,
            } => {
                let spec = match self.fast_param_delete_spec(sql, table_name, selection, returning)? {
                    Ok(spec) => spec,
                    Err(e) => return Some(Err(e)),
                };
                let mut total = 0_u64;
                for params in rows {
                    match self.try_execute_fast_delete_param_spec_inner(&spec, params, false) {
                        Some(Ok(count)) => total += count,
                        Some(Err(e)) => {
                            if total > 0 {
                                if let Err(barrier) = self.storage.durable_autocommit_barrier() {
                                    return Some(Err(barrier));
                                }
                                self.storage.increment_lsn();
                                self.invalidate_result_cache();
                            }
                            return Some(Err(e));
                        }
                        None => {
                            if total > 0 {
                                if let Err(barrier) = self.storage.durable_autocommit_barrier() {
                                    return Some(Err(barrier));
                                }
                                self.storage.increment_lsn();
                                self.invalidate_result_cache();
                            }
                            return Some(Err(Error::internal(
                                "fast parameterized DELETE batch became ineligible",
                            )));
                        }
                    }
                }
                if let Err(e) = self.storage.durable_autocommit_barrier() {
                    return Some(Err(e));
                }
                self.storage.increment_lsn();
                Some(Ok(total))
            }
            _ => None,
        }
    }

    fn try_autocommit_fast_update_delete_params_cached(&self, sql: &str, params: &[Value]) -> Option<Result<u64>> {
        if self.in_transaction()
            || !self.savepoints.read().is_empty()
            || self.any_session_txns()
            || self.tenant_manager.get_current_context().is_some()
            || self.storage.get_current_branch_id().is_some()
        {
            return None;
        }

        let trimmed = sql.trim_start();
        let prefix = trimmed.as_bytes().get(..6)?;
        if prefix.eq_ignore_ascii_case(b"UPDATE") {
            let spec = if let Some(spec) = self
                .hot_fast_param_update_spec
                .read()
                .as_ref()
                .and_then(|(cached_sql, spec)| (cached_sql == sql).then(|| std::sync::Arc::clone(spec)))
            {
                spec
            } else {
                self.fast_param_update_cache.get(sql)?
            };
            if self.tenant_manager.should_apply_rls(&spec.table_name, "UPDATE")
                || self.trigger_registry.has_triggers_for_table(&spec.table_name)
            {
                return None;
            }
            return self.try_execute_fast_update_param_spec(&spec, params);
        }

        if prefix.eq_ignore_ascii_case(b"DELETE") {
            let fk_mode = *self.fk_validation_mode.read();
            let fk_source = *self.fk_validation_source.read();
            let cache_key = format!("\0fast_param_delete\0{fk_mode:?}\0{fk_source:?}\0{sql}");
            let spec = if let Some(spec) = self
                .hot_fast_param_delete_spec
                .read()
                .as_ref()
                .and_then(|(cached_key, spec)| (cached_key == &cache_key).then(|| std::sync::Arc::clone(spec)))
            {
                spec
            } else {
                self.fast_param_delete_cache.get(&cache_key)?
            };
            if self.tenant_manager.should_apply_rls(&spec.table_name, "DELETE")
                || self.trigger_registry.has_triggers_for_table(&spec.table_name)
            {
                return None;
            }
            return self.try_execute_fast_delete_param_spec(&spec, params);
        }

        None
    }

    fn try_fast_update_params(
        &self,
        sql: &str,
        table_name: &str,
        assignments: &[(String, sql::LogicalExpr)],
        selection: &Option<sql::LogicalExpr>,
        returning: &Option<Vec<sql::logical_plan::ReturningItem>>,
        params: &[Value],
    ) -> Option<Result<u64>> {
        if returning.is_some()
            || assignments.is_empty()
            || self.tenant_manager.should_apply_rls(table_name, "UPDATE")
            || self.trigger_registry.has_triggers_for_table(table_name)
        {
            return None;
        }

        let spec = match self.fast_param_update_spec(sql, table_name, assignments, selection, returning)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };
        self.try_execute_fast_update_param_spec(&spec, params)
    }

    fn try_execute_fast_update_param_spec(&self, spec: &FastParamUpdateSpec, params: &[Value]) -> Option<Result<u64>> {
        let pk_value = match Self::fast_pk_value_from_expr_cow(&spec.pk_expr, &spec.pk_data_type, params) {
            Some(Ok(value)) => value,
            Some(Err(e)) => return Some(Err(e)),
            None => return None,
        };
        let pk_value = pk_value.as_ref();

        let existing_row = match self
            .storage
            .get_row_by_typed_pk_for_write_with_schema(&spec.table_name, pk_value, &spec.schema)
        {
            Ok(Some(row)) => row,
            Ok(None) => return Some(Ok(0)),
            Err(e) => return Some(Err(e)),
            };
        let row_id = existing_row.row_id.unwrap_or(0);
        if row_id == 0 {
            return None;
        }

        let mut evaluator: Option<sql::Evaluator> = None;
        let mut replacements = Vec::with_capacity(spec.assignments.len());
        for assignment in &spec.assignments {
            let mut value = if let Some(value) = Self::fast_eval_param_expr(&assignment.expr, params) {
                match value {
                    Ok(value) => value,
                    Err(e) => return Some(Err(e)),
                }
            } else if let Some(value) = Self::fast_eval_self_arithmetic_expr(
                &assignment.expr,
                &assignment.col_name,
                assignment.col_idx,
                &existing_row,
            ) {
                match value {
                    Ok(value) => value,
                    Err(e) => return Some(Err(e)),
                }
            } else {
                let evaluator = evaluator.get_or_insert_with(|| {
                    sql::Evaluator::with_parameters(std::sync::Arc::clone(&spec.schema), params.to_vec())
                });
                match evaluator.evaluate(&assignment.expr, &existing_row) {
                    Ok(value) => value,
                    Err(e) => return Some(Err(e)),
                }
            };
            if Self::insert_value_needs_cast(&value, &assignment.data_type) {
                value = match Self::fast_cast_value(value, &assignment.data_type) {
                    Ok(value) => value,
                    Err(e) => return Some(Err(e)),
                };
            }
            if !assignment.nullable && matches!(value, Value::Null) {
                return Some(Err(Error::constraint_violation(format!(
                    "Column '{}' cannot be null",
                    assignment.col_name
                ))));
            }
            if assignment.col_idx >= existing_row.values.len() {
                return None;
            }
            replacements.push((assignment.col_idx, value));
        }

        let result = if spec.assignments_affect_indexes {
            let mut new_values = existing_row.values.clone();
            for (idx, value) in replacements {
                new_values[idx] = value;
            }
            let new_tuple = Tuple::new(new_values);
            if self.storage.fast_dml_requires_logical_wal() {
                let key = self.storage.branch_aware_data_key(&spec.table_name, row_id);
                let value = match bincode::serialize(&new_tuple) {
                    Ok(value) => value,
                    Err(e) => return Some(Err(Error::storage(format!("Failed to serialize tuple: {}", e)))),
                };
                let wal_result = if self.storage.logical_wal_per_statement() {
                    self.storage.log_data_update(&spec.table_name, &key, &value)
                } else {
                    self.storage.log_data_update_nosync(&spec.table_name, &key, &value)
                };
                if let Err(e) = wal_result {
                    return Some(Err(e));
                }
            }

            self.storage.update_tuple_fast_with_index_hint(
                &spec.table_name,
                row_id,
                new_tuple,
                &existing_row,
                &spec.schema,
                Some(true),
            )
        } else {
            // R5.V1: vector indexes aren't ART indexes, so this "no index
            // change" path may still touch (or carry) a vector column. Keep
            // the pre-update row for HNSW maintenance when the table has a
            // vector index (one atomic load otherwise).
            let vector_old_tuple = if self.storage.vector_indexes().table_has_indexes(&spec.table_name) {
                Some(existing_row.clone())
            } else {
                None
            };
            let mut new_tuple = existing_row;
            new_tuple.row_id = None;
            new_tuple.branch_id = None;
            for (idx, value) in replacements {
                new_tuple.values[idx] = value;
            }
            if self.storage.fast_dml_requires_logical_wal() {
                let key = self.storage.branch_aware_data_key(&spec.table_name, row_id);
                let value = match bincode::serialize(&new_tuple) {
                    Ok(value) => value,
                    Err(e) => return Some(Err(Error::storage(format!("Failed to serialize tuple: {}", e)))),
                };
                let wal_result = if self.storage.logical_wal_per_statement() {
                    self.storage.log_data_update(&spec.table_name, &key, &value)
                } else {
                    self.storage.log_data_update_nosync(&spec.table_name, &key, &value)
                };
                if let Err(e) = wal_result {
                    return Some(Err(e));
                }
            }
            self.storage.update_tuple_fast_no_index(
                &spec.table_name,
                row_id,
                new_tuple,
                &spec.schema,
                vector_old_tuple.as_ref(),
            )
        };
        if result.is_ok() {
            if let Err(e) = self.storage.durable_autocommit_barrier() {
                return Some(Err(e));
            }
            self.storage.increment_lsn();
        }
        Some(result)
    }

    fn try_fast_delete_params(
        &self,
        sql: &str,
        table_name: &str,
        selection: &Option<sql::LogicalExpr>,
        returning: &Option<Vec<sql::logical_plan::ReturningItem>>,
        params: &[Value],
    ) -> Option<Result<u64>> {
        if returning.is_some()
            || self.tenant_manager.should_apply_rls(table_name, "DELETE")
            || self.trigger_registry.has_triggers_for_table(table_name)
        {
            return None;
        }

        let spec = match self.fast_param_delete_spec(sql, table_name, selection, returning)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };
        self.try_execute_fast_delete_param_spec(&spec, params)
    }

    fn try_execute_fast_delete_param_spec(&self, spec: &FastParamDeleteSpec, params: &[Value]) -> Option<Result<u64>> {
        self.try_execute_fast_delete_param_spec_inner(spec, params, true)
    }

    fn try_execute_fast_delete_param_spec_inner(
        &self,
        spec: &FastParamDeleteSpec,
        params: &[Value],
        finalize_statement: bool,
    ) -> Option<Result<u64>> {
        let pk_value = match Self::fast_pk_value_from_expr_cow(&spec.pk_expr, &spec.pk_data_type, params) {
            Some(Ok(value)) => value,
            Some(Err(e)) => return Some(Err(e)),
            None => return None,
        };
        let pk_value = pk_value.as_ref();

        let pk_key = crate::storage::art_manager::ArtIndexManager::encode_key(std::slice::from_ref(pk_value));
        let (row_id, existing_row) = if spec.pk_only_delete {
            match self.storage.art_indexes().pk_index_lookup(&spec.table_name, &pk_key) {
                Some(row_id) => (row_id, None),
                None => return Some(Ok(0)),
            }
        } else {
            let existing_row =
                match self
                    .storage
                    .get_row_by_typed_pk_for_write_with_schema(&spec.table_name, pk_value, &spec.schema)
                {
                    Ok(Some(row)) => row,
                    Ok(None) => return Some(Ok(0)),
                    Err(e) => return Some(Err(e)),
                };
            let row_id = existing_row.row_id.unwrap_or(0);
            if row_id == 0 {
                return None;
            }
            (row_id, Some(existing_row))
        };

        let result = (|| {
            if self.storage.fast_dml_requires_logical_wal() {
                let key = self.storage.branch_aware_data_key(&spec.table_name, row_id);
                if self.storage.logical_wal_per_statement() {
                    self.storage.log_data_delete(&spec.table_name, &key)?;
                } else {
                    self.storage.log_data_delete_nosync(&spec.table_name, &key)?;
                }
            }
            if spec.pk_only_delete {
                self.storage
                    .delete_tuple_fast_pk_only(&spec.table_name, row_id, &pk_key, pk_value)
            } else {
                let existing_row = existing_row
                    .as_ref()
                    .ok_or_else(|| Error::internal("missing fast delete tuple"))?;
                self.storage
                    .delete_tuple_fast(&spec.table_name, row_id, existing_row, &spec.schema)
            }
        })();
        if result.is_ok() && finalize_statement {
            if let Err(e) = self.storage.durable_autocommit_barrier() {
                return Some(Err(e));
            }
            self.storage.increment_lsn();
        }
        Some(result)
    }

    fn fast_param_update_spec(
        &self,
        sql: &str,
        table_name: &str,
        assignments: &[(String, sql::LogicalExpr)],
        selection: &Option<sql::LogicalExpr>,
        returning: &Option<Vec<sql::logical_plan::ReturningItem>>,
    ) -> Option<Result<std::sync::Arc<FastParamUpdateSpec>>> {
        if returning.is_some()
            || assignments.is_empty()
            || self.tenant_manager.should_apply_rls(table_name, "UPDATE")
            || self.trigger_registry.has_triggers_for_table(table_name)
        {
            return None;
        }

        if let Some(spec) = self.fast_param_update_cache.get(sql) {
            return Some(Ok(spec));
        }

        let spec = match self.build_fast_param_update_spec(table_name, assignments, selection, returning)? {
            Ok(spec) => std::sync::Arc::new(spec),
            Err(e) => return Some(Err(e)),
        };
        self.fast_param_update_cache
            .put(sql.to_string(), std::sync::Arc::clone(&spec));
        *self.hot_fast_param_update_spec.write() = Some((sql.to_string(), std::sync::Arc::clone(&spec)));
        Some(Ok(spec))
    }

    fn build_fast_param_update_spec(
        &self,
        table_name: &str,
        assignments: &[(String, sql::LogicalExpr)],
        selection: &Option<sql::LogicalExpr>,
        returning: &Option<Vec<sql::logical_plan::ReturningItem>>,
    ) -> Option<Result<FastParamUpdateSpec>> {
        if returning.is_some()
            || assignments.is_empty()
            || self.tenant_manager.should_apply_rls(table_name, "UPDATE")
            || self.trigger_registry.has_triggers_for_table(table_name)
        {
            return None;
        }

        let catalog = self.storage.catalog();
        let schema = match catalog.get_table_schema(table_name) {
            Ok(schema) => std::sync::Arc::new(schema),
            Err(_) => return None,
        };
        if let Ok(constraints) = catalog.load_table_constraints(table_name) {
            if !constraints.foreign_keys.is_empty() || !constraints.check_constraints.is_empty() {
                return None;
            }
        }

        let (pk_expr, pk_data_type) = Self::fast_pk_expr_from_selection(selection, &schema)?;
        let mut fast_assignments = Vec::with_capacity(assignments.len());
        let mut assignment_columns = Vec::with_capacity(assignments.len());
        for (col_name, expr) in assignments {
            let col_idx = match schema.get_column_index(col_name) {
                Some(idx) => idx,
                None => return None,
            };
            let column = match schema.get_column_at(col_idx) {
                Some(column) => column,
                None => return None,
            };
            if column.primary_key || column.unique || !Self::fast_update_expr_supported(expr) {
                return None;
            }
            assignment_columns.push(col_name.clone());
            fast_assignments.push(FastParamUpdateAssignment {
                col_idx,
                col_name: col_name.clone(),
                data_type: column.data_type.clone(),
                nullable: column.nullable,
                expr: expr.clone(),
            });
        }
        let assignments_affect_indexes = self
            .storage
            .art_indexes()
            .columns_affect_indexes(table_name, &assignment_columns);

        Some(Ok(FastParamUpdateSpec {
            table_name: table_name.to_string(),
            schema,
            pk_expr,
            pk_data_type,
            assignments: fast_assignments,
            assignments_affect_indexes,
        }))
    }

    fn fast_param_delete_spec(
        &self,
        sql: &str,
        table_name: &str,
        selection: &Option<sql::LogicalExpr>,
        returning: &Option<Vec<sql::logical_plan::ReturningItem>>,
    ) -> Option<Result<std::sync::Arc<FastParamDeleteSpec>>> {
        if returning.is_some()
            || self.tenant_manager.should_apply_rls(table_name, "DELETE")
            || self.tenant_manager.get_current_context().is_some()
            || self.trigger_registry.has_triggers_for_table(table_name)
        {
            return None;
        }

        let fk_mode = *self.fk_validation_mode.read();
        let fk_source = *self.fk_validation_source.read();
        let cache_key = format!("\0fast_param_delete\0{fk_mode:?}\0{fk_source:?}\0{sql}");
        if let Some(spec) = self.fast_param_delete_cache.get(&cache_key) {
            return Some(Ok(spec));
        }

        let spec = match self.build_fast_param_delete_spec(table_name, selection, returning, fk_mode, fk_source)? {
            Ok(spec) => std::sync::Arc::new(spec),
            Err(e) => return Some(Err(e)),
        };
        self.fast_param_delete_cache
            .put(cache_key.clone(), std::sync::Arc::clone(&spec));
        *self.hot_fast_param_delete_spec.write() = Some((cache_key, std::sync::Arc::clone(&spec)));
        Some(Ok(spec))
    }

    fn build_fast_param_delete_spec(
        &self,
        table_name: &str,
        selection: &Option<sql::LogicalExpr>,
        returning: &Option<Vec<sql::logical_plan::ReturningItem>>,
        fk_mode: FkValidationMode,
        fk_source: FkValidationSource,
    ) -> Option<Result<FastParamDeleteSpec>> {
        if returning.is_some()
            || self.tenant_manager.should_apply_rls(table_name, "DELETE")
            || self.tenant_manager.get_current_context().is_some()
            || self.trigger_registry.has_triggers_for_table(table_name)
        {
            return None;
        }

        let catalog = self.storage.catalog();
        let schema = match catalog.get_table_schema(table_name) {
            Ok(schema) => std::sync::Arc::new(schema),
            Err(_) => return None,
        };
        if let Ok(constraints) = catalog.load_table_constraints(table_name) {
            if !constraints.foreign_keys.is_empty() {
                return None;
            }
        }
        if fk_mode != FkValidationMode::Off && fk_source != FkValidationSource::Proxy {
            match catalog.get_referencing_fks(table_name) {
                Ok(referencing_fks) if referencing_fks.is_empty() => {}
                Ok(_) => return None,
                Err(e) => return Some(Err(e)),
            }
        }

        let (pk_expr, pk_data_type) = Self::fast_pk_expr_from_selection(selection, &schema)?;
        Some(Ok(FastParamDeleteSpec {
            table_name: table_name.to_string(),
            pk_only_delete: self.fast_delete_can_skip_tuple_fetch(table_name, &schema),
            schema,
            pk_expr,
            pk_data_type,
        }))
    }

    fn fast_pk_expr_from_selection(
        selection: &Option<sql::LogicalExpr>,
        schema: &Schema,
    ) -> Option<(sql::LogicalExpr, DataType)> {
        let sql::LogicalExpr::BinaryExpr { left, op, right } = selection.as_ref()? else {
            return None;
        };
        if !matches!(op, sql::BinaryOperator::Eq) {
            return None;
        }

        let (column_name, value_expr) = match (left.as_ref(), right.as_ref()) {
            (sql::LogicalExpr::Column { name, .. }, value_expr) => (name, value_expr),
            (value_expr, sql::LogicalExpr::Column { name, .. }) => (name, value_expr),
            _ => return None,
        };
        let col_idx = schema.get_column_index(column_name)?;
        let column = schema.get_column_at(col_idx)?;
        if !column.primary_key
            || matches!(value_expr, sql::LogicalExpr::DefaultValue)
            || !Self::fast_param_insert_expr_supported(value_expr)
        {
            return None;
        }
        // BUG F: a composite PRIMARY KEY marks every member column
        // `primary_key = true`. The parameterized ($1) UPDATE/DELETE fast paths
        // resolve the target row via a single-value PK index probe, which can
        // never match the grouped composite key. Only a sole PK column qualifies;
        // otherwise fall through to the planner, which scans + filters.
        if !schema.has_single_column_pk() {
            return None;
        }
        Some((value_expr.clone(), column.data_type.clone()))
    }

    fn fast_pk_value_from_expr(
        expr: &sql::LogicalExpr,
        data_type: &DataType,
        params: &[Value],
    ) -> Option<Result<Value>> {
        let mut value = match Self::fast_eval_param_expr(expr, params) {
            Some(Ok(value)) => value,
            Some(Err(e)) => return Some(Err(e)),
            None => {
                let evaluator =
                    sql::Evaluator::with_parameters(std::sync::Arc::new(Schema { columns: vec![] }), params.to_vec());
                let empty_tuple = Tuple::new(vec![]);
                match evaluator.evaluate(expr, &empty_tuple) {
                    Ok(value) => value,
                    Err(e) => return Some(Err(e)),
                }
            }
        };
        if Self::insert_value_needs_cast(&value, data_type) {
            value = match Self::fast_cast_value(value, data_type) {
                Ok(value) => value,
                Err(e) => return Some(Err(e)),
            };
        }
        Some(Ok(value))
    }

    fn fast_pk_value_from_expr_cow<'a>(
        expr: &sql::LogicalExpr,
        data_type: &DataType,
        params: &'a [Value],
    ) -> Option<Result<std::borrow::Cow<'a, Value>>> {
        if let sql::LogicalExpr::Parameter { index } = expr {
            if *index == 0 {
                return Some(Err(Error::query_execution(
                    "Parameter indices must be 1-based (e.g., $1, $2)",
                )));
            }
            let Some(value) = params.get(index - 1) else {
                return Some(Err(Error::query_execution(format!(
                    "Parameter ${} not provided. Expected {} parameters, got {}",
                    index,
                    index,
                    params.len()
                ))));
            };
            if !Self::insert_value_needs_cast(value, data_type) {
                return Some(Ok(std::borrow::Cow::Borrowed(value)));
            }
        }

        Self::fast_pk_value_from_expr(expr, data_type, params).map(|result| result.map(std::borrow::Cow::Owned))
    }

    fn fast_eval_self_arithmetic_expr(
        expr: &sql::LogicalExpr,
        col_name: &str,
        col_idx: usize,
        row: &Tuple,
    ) -> Option<Result<Value>> {
        let sql::LogicalExpr::BinaryExpr { left, op, right } = expr else {
            return None;
        };
        if !matches!(
            op,
            sql::BinaryOperator::Plus
                | sql::BinaryOperator::Minus
                | sql::BinaryOperator::Multiply
                | sql::BinaryOperator::Divide
                | sql::BinaryOperator::Modulo
        ) {
            return None;
        }

        let sql::LogicalExpr::Column { table: None, name } = left.as_ref() else {
            return None;
        };
        if !name.eq_ignore_ascii_case(col_name) {
            return None;
        }
        let sql::LogicalExpr::Literal(rhs) = right.as_ref() else {
            return None;
        };
        let current = row.values.get(col_idx)?;

        Some(Self::fast_apply_numeric_op(current, op, rhs))
    }

    fn fast_apply_numeric_op(left: &Value, op: &sql::BinaryOperator, right: &Value) -> Result<Value> {
        if matches!(left, Value::Null) || matches!(right, Value::Null) {
            return Ok(Value::Null);
        }

        if let (Some(l), Some(r)) = (Self::fast_int_as_i128(left), Self::fast_int_as_i128(right)) {
            return Self::fast_apply_i128(l, op, r, |v| Self::fast_int_like(left, v));
        }

        if matches!(left, Value::Float4(_) | Value::Float8(_)) {
            if let Some(r) = Self::fast_numeric_as_f64(right) {
                let l = Self::fast_numeric_as_f64(left).expect("Float value must convert to f64");
                let value = Self::fast_apply_f64(l, op, r)?;
                return if matches!(left, Value::Float4(_)) {
                    Ok(Value::Float4(value as f32))
                } else {
                    Ok(Value::Float8(value))
                };
            }
        }

        let evaluator = sql::Evaluator::new(std::sync::Arc::new(Schema { columns: vec![] }));
        let expr = sql::LogicalExpr::BinaryExpr {
            left: Box::new(sql::LogicalExpr::Literal(left.clone())),
            op: *op,
            right: Box::new(sql::LogicalExpr::Literal(right.clone())),
        };
        evaluator.evaluate(&expr, &Tuple::new(vec![]))
    }

    fn fast_int_as_i128(value: &Value) -> Option<i128> {
        match value {
            Value::Int2(v) => Some(i128::from(*v)),
            Value::Int4(v) => Some(i128::from(*v)),
            Value::Int8(v) => Some(i128::from(*v)),
            _ => None,
        }
    }

    fn fast_int_like(template: &Value, value: i128) -> Option<Value> {
        match template {
            Value::Int2(_) => i16::try_from(value).ok().map(Value::Int2),
            Value::Int4(_) => i32::try_from(value).ok().map(Value::Int4),
            Value::Int8(_) => i64::try_from(value).ok().map(Value::Int8),
            _ => None,
        }
    }

    fn fast_numeric_as_f64(value: &Value) -> Option<f64> {
        match value {
            Value::Int2(v) => Some(f64::from(*v)),
            Value::Int4(v) => Some(f64::from(*v)),
            Value::Int8(v) => Some(*v as f64),
            Value::Float4(v) => Some(f64::from(*v)),
            Value::Float8(v) => Some(*v),
            _ => None,
        }
    }

    fn fast_apply_i128<F>(left: i128, op: &sql::BinaryOperator, right: i128, convert: F) -> Result<Value>
    where
        F: FnOnce(i128) -> Option<Value>,
    {
        let value = match op {
            sql::BinaryOperator::Plus => left.checked_add(right),
            sql::BinaryOperator::Minus => left.checked_sub(right),
            sql::BinaryOperator::Multiply => left.checked_mul(right),
            sql::BinaryOperator::Divide => {
                if right == 0 {
                    return Err(Error::query_execution("Division by zero"));
                }
                left.checked_div(right)
            }
            sql::BinaryOperator::Modulo => {
                if right == 0 {
                    return Err(Error::query_execution("Division by zero"));
                }
                left.checked_rem(right)
            }
            _ => None,
        }
        .and_then(convert)
        .ok_or_else(|| Error::query_execution("Arithmetic overflow"))?;
        Ok(value)
    }

    fn fast_apply_f64(left: f64, op: &sql::BinaryOperator, right: f64) -> Result<f64> {
        match op {
            sql::BinaryOperator::Plus => Ok(left + right),
            sql::BinaryOperator::Minus => Ok(left - right),
            sql::BinaryOperator::Multiply => Ok(left * right),
            sql::BinaryOperator::Divide => {
                if right == 0.0 {
                    Err(Error::query_execution("Division by zero"))
                } else {
                    Ok(left / right)
                }
            }
            sql::BinaryOperator::Modulo => {
                if right == 0.0 {
                    Err(Error::query_execution("Division by zero"))
                } else {
                    Ok(left % right)
                }
            }
            _ => Err(Error::query_execution("Unsupported arithmetic operator")),
        }
    }

    fn fast_update_expr_supported(expr: &sql::LogicalExpr) -> bool {
        match expr {
            sql::LogicalExpr::Literal(_) | sql::LogicalExpr::Parameter { .. } | sql::LogicalExpr::Column { .. } => true,
            sql::LogicalExpr::Cast { expr, .. } | sql::LogicalExpr::UnaryExpr { expr, .. } => {
                Self::fast_update_expr_supported(expr)
            }
            sql::LogicalExpr::BinaryExpr { left, op, right } => {
                matches!(
                    op,
                    sql::BinaryOperator::Plus
                        | sql::BinaryOperator::Minus
                        | sql::BinaryOperator::Multiply
                        | sql::BinaryOperator::Divide
                        | sql::BinaryOperator::Modulo
                ) && Self::fast_update_expr_supported(left)
                    && Self::fast_update_expr_supported(right)
            }
            _ => false,
        }
    }

    /// Execute eligible autocommit UPDATE/DELETE fast paths without creating an
    /// otherwise-empty transaction wrapper.
    fn try_autocommit_fast_update_delete(&self, sql: &str) -> Option<Result<u64>> {
        if !self.savepoints.read().is_empty()
            || self.any_session_txns()
            || self.tenant_manager.get_current_context().is_some()
        {
            return None;
        }

        let trimmed = sql.trim_start();
        let prefix = trimmed.as_bytes().get(..6)?;
        let result = if prefix.eq_ignore_ascii_case(b"UPDATE") {
            self.try_fast_update(sql)?
        } else if prefix.eq_ignore_ascii_case(b"DELETE") {
            self.try_fast_delete_autocommit(sql)?
        } else {
            return None;
        };

        if result.is_ok() {
            if let Err(e) = self.storage.durable_autocommit_barrier() {
                return Some(Err(e));
            }
            self.storage.increment_lsn();
        }
        Some(result)
    }

    /// Execute SQL with an implicit transaction (auto-commit)
    fn execute_with_implicit_transaction(&self, sql: &str) -> Result<u64> {
        // Begin implicit transaction
        let txn_start = std::time::Instant::now();
        let txn = self.storage.begin_autocommit_transaction()?;
        tracing::trace!(
            phase = "txn_begin",
            duration_us = txn_start.elapsed().as_micros() as u64,
            "Transaction started"
        );

        // Execute the query within transaction context
        let exec_start = std::time::Instant::now();
        let result = self.execute_in_transaction(sql, &txn);
        tracing::debug!(
            phase = "execute",
            duration_us = exec_start.elapsed().as_micros() as u64,
            "Query executed"
        );

        // Commit or rollback based on result
        match result {
            Ok(count) => {
                let commit_start = std::time::Instant::now();
                if let Err(e) = self.validate_deferred_fk_checks(Some(&txn)) {
                    let _ = txn.rollback();
                    self.rollback_art_undo_log();
                    return Err(e);
                }
                txn.commit()?;
                self.art_undo_log.write().clear();
                self.deferred_fk_checks.lock().clear();
                // Increment LSN to track transaction commits
                self.storage.increment_lsn();
                tracing::debug!(
                    phase = "txn_commit",
                    duration_us = commit_start.elapsed().as_micros() as u64,
                    rows = count,
                    "Transaction committed"
                );
                Ok(count)
            }
            Err(e) => {
                let _ = txn.rollback(); // Ignore rollback errors
                self.rollback_art_undo_log();
                self.deferred_fk_checks.lock().clear();
                Err(e)
            }
        }
    }

    /// Invalidate the plan cache (call after DDL operations)
    fn invalidate_plan_cache(&self) {
        self.plan_cache.clear();
        // Also invalidate parse cache since schema changes may affect SQL interpretation
        self.parse_cache.clear();
        self.fast_param_insert_cache.clear();
        self.fast_literal_insert_cache.clear();
        self.fast_param_update_cache.clear();
        *self.hot_fast_param_update_spec.write() = None;
        self.fast_literal_update_cache.clear();
        self.fast_param_delete_cache.clear();
        *self.hot_fast_param_delete_spec.write() = None;
        self.fast_literal_delete_cache.clear();
        self.fast_select_cache.clear();
        *self.hot_fast_select_spec.write() = None;
        // Also invalidate result cache since schema changes affect query results
        self.invalidate_result_cache();
    }

    /// Invalidate all cached query results (called on any DML operation)
    fn invalidate_result_cache(&self) {
        *self.hot_result_cache_entry.write() = None;
        if !self
            .result_cache_nonempty
            .swap(false, std::sync::atomic::Ordering::AcqRel)
        {
            return;
        }
        self.result_cache.clear();
    }

    /// Handle SQLite `PRAGMA` queries from the embedded path. Returns
    /// SQLite-shaped rows for introspection PRAGMAs (`table_info(t)`)
    /// and an empty result for connection-tuning PRAGMAs (`foreign_keys`,
    /// `journal_mode`, `synchronous`, `busy_timeout`, …) so sqlite3-driven
    /// apps boot cleanly.
    fn handle_pragma_query(&self, name: &str, arg: Option<&str>) -> Result<Vec<Tuple>> {
        match name.to_lowercase().as_str() {
            "table_info" => {
                let table = arg
                    .unwrap_or("")
                    .trim()
                    .trim_matches(|c| c == '\'' || c == '"' || c == '`');
                if table.is_empty() {
                    return Ok(vec![]);
                }
                let catalog = self.storage.catalog();
                let schema = catalog.get_table_schema(table)?;
                let mut rows = Vec::with_capacity(schema.columns.len());
                for (idx, col) in schema.columns.iter().enumerate() {
                    rows.push(Tuple::new(vec![
                        Value::Int4(idx as i32),
                        Value::String(col.name.clone()),
                        Value::String(format!("{:?}", col.data_type).to_uppercase()),
                        Value::Int4(if col.nullable { 0 } else { 1 }),
                        col.default_expr
                            .as_ref()
                            .map(|d| Value::String(d.clone()))
                            .unwrap_or(Value::Null),
                        Value::Int4(if col.primary_key { 1 } else { 0 }),
                    ]));
                }
                Ok(rows)
            }
            _ => {
                tracing::debug!("PRAGMA stubbed (no-op rows): {} = {:?}", name, arg);
                Ok(vec![])
            }
        }
    }

    fn alter_table_set_column_nullability(&self, table_name: &str, column_name: &str, nullable: bool) -> Result<u64> {
        let catalog = self.storage.catalog();
        let mut schema = catalog.get_table_schema(table_name)?;
        let col_idx = schema
            .columns
            .iter()
            .position(|c| c.name == column_name)
            .ok_or_else(|| {
                Error::query_execution(format!(
                    "Column '{}' does not exist in table '{}'",
                    column_name, table_name
                ))
            })?;

        let column = schema
            .get_column_at_mut(col_idx)
            .ok_or_else(|| Error::internal("column index out of bounds"))?;
        if nullable && column.primary_key {
            return Err(Error::query_execution(format!(
                "Cannot drop NOT NULL from primary key column '{}'",
                column_name
            )));
        }
        if column.nullable == nullable {
            return Ok(0);
        }
        column.nullable = nullable;
        catalog.update_table_schema(table_name, &schema)?;
        Ok(0)
    }

    /// Execute a single ALTER TABLE operation from its logical plan.
    ///
    /// This is used by the `AlterTableMulti` handler to execute each sub-operation
    /// sequentially, and also serves as the shared implementation for ALTER TABLE
    /// execution across different code paths.
    fn execute_alter_table_op(&self, plan: &sql::LogicalPlan) -> Result<u64> {
        match plan {
            sql::LogicalPlan::AlterTableAddColumn {
                table_name,
                column_def,
                if_not_exists,
            } => {
                let catalog = self.storage.catalog();
                let mut schema = catalog.get_table_schema(table_name)?;

                if schema.columns.iter().any(|c| c.name == column_def.name) {
                    if *if_not_exists {
                        return Ok(0);
                    }
                    return Err(Error::query_execution(format!(
                        "Column '{}' already exists in table '{}'",
                        column_def.name, table_name
                    )));
                }

                let new_column = Column {
                    name: column_def.name.clone(),
                    data_type: column_def.data_type.clone(),
                    nullable: !column_def.not_null,
                    primary_key: column_def.primary_key,
                    source_table: None,
                    source_table_name: Some(table_name.clone()),
                    default_expr: Self::serialize_default_expr(&column_def.default),
                    unique: column_def.unique,
                    storage_mode: column_def.storage_mode,
                };

                schema.columns.push(new_column);
                catalog.update_table_schema(table_name, &schema)?;

                let rows_updated = self.storage.add_column_to_rows(table_name, &column_def.default)?;

                tracing::info!(
                    "Added column '{}' to table '{}', updated {} rows",
                    column_def.name,
                    table_name,
                    rows_updated
                );

                Ok(rows_updated as u64)
            }
            sql::LogicalPlan::AlterTableDropColumn {
                table_name,
                column_name,
                if_exists,
                cascade,
            } => {
                let catalog = self.storage.catalog();
                let mut schema = catalog.get_table_schema(table_name)?;

                let col_idx = schema.columns.iter().position(|c| c.name == *column_name);

                match col_idx {
                    Some(idx) => {
                        let is_pk = schema
                            .get_column_at(idx)
                            .ok_or_else(|| Error::internal("column index out of bounds"))?
                            .primary_key;
                        if is_pk && !cascade {
                            return Err(Error::query_execution(format!(
                                "Cannot drop primary key column '{}' without CASCADE",
                                column_name
                            )));
                        }

                        let was_columnar = schema
                            .get_column_at(idx)
                            .is_some_and(|c| c.storage_mode == ColumnStorageMode::Columnar);
                        schema.columns.remove(idx);
                        catalog.update_table_schema(table_name, &schema)?;

                        let rows_updated = self.storage.drop_column_from_rows(table_name, idx)?;
                        self.cleanup_columnar_after_drop_column(table_name, column_name, was_columnar, &schema)?;

                        tracing::info!(
                            "Dropped column '{}' from table '{}', updated {} rows",
                            column_name,
                            table_name,
                            rows_updated
                        );

                        Ok(rows_updated as u64)
                    }
                    None => {
                        if *if_exists {
                            Ok(0)
                        } else {
                            Err(Error::query_execution(format!(
                                "Column '{}' does not exist in table '{}'",
                                column_name, table_name
                            )))
                        }
                    }
                }
            }
            sql::LogicalPlan::AlterTableRenameColumn {
                table_name,
                old_column_name,
                new_column_name,
            } => {
                let catalog = self.storage.catalog();
                let mut schema = catalog.get_table_schema(table_name)?;

                if schema.columns.iter().any(|c| c.name == *new_column_name) {
                    return Err(Error::query_execution(format!(
                        "Column '{}' already exists in table '{}'",
                        new_column_name, table_name
                    )));
                }

                let col_idx = schema
                    .columns
                    .iter()
                    .position(|c| c.name == *old_column_name)
                    .ok_or_else(|| {
                        Error::query_execution(format!(
                            "Column '{}' does not exist in table '{}'",
                            old_column_name, table_name
                        ))
                    })?;

                schema
                    .get_column_at_mut(col_idx)
                    .ok_or_else(|| Error::internal("column index out of bounds"))?
                    .name = new_column_name.clone();
                catalog.update_table_schema(table_name, &schema)?;

                tracing::info!(
                    "Renamed column '{}' to '{}' in table '{}'",
                    old_column_name,
                    new_column_name,
                    table_name
                );

                Ok(0)
            }
            sql::LogicalPlan::AlterTableAlterColumnNullability {
                table_name,
                column_name,
                nullable,
            } => self.alter_table_set_column_nullability(table_name, column_name, *nullable),
            sql::LogicalPlan::AlterTableRename {
                table_name,
                new_table_name,
            } => {
                let catalog = self.storage.catalog();

                if catalog.get_table_schema(new_table_name).is_ok() {
                    return Err(Error::query_execution(format!(
                        "Table '{}' already exists",
                        new_table_name
                    )));
                }

                self.storage.rename_table(table_name, new_table_name)?;

                tracing::info!("Renamed table '{}' to '{}'", table_name, new_table_name);

                Ok(0)
            }
            _ => Err(Error::internal(format!(
                "execute_alter_table_op called with non-ALTER plan: {:?}",
                plan.plan_type_name()
            ))),
        }
    }

    /// Fast path for simple INSERT statements.
    ///
    /// Detects `INSERT INTO <table> (<cols>) VALUES (<vals>)` and bypasses
    /// full SQL parsing + planning when:
    /// - Statement has simple literal values only (no expressions/subqueries)
    /// - No RETURNING, ON CONFLICT, or DEFAULT keywords
    /// - No RLS enforcement active for the table
    /// - No triggers defined for the table
    ///
    /// Returns `None` to fall through to the normal path for anything complex.
    #[allow(clippy::indexing_slicing)] // validated indices
    fn try_fast_insert(&self, sql: &str) -> Option<Result<u64>> {
        let trimmed = sql.trim();

        // Quick prefix check (case-insensitive, avoid allocation)
        if trimmed.len() < 20 || !trimmed.as_bytes().get(..6)?.eq_ignore_ascii_case(b"INSERT") {
            return None;
        }

        // Bail on complex features without allocating an uppercased copy.
        // Word-boundary + literal-aware (R1.2): a table named
        // `default_settings` or a TEXT literal containing 'select' no longer
        // bails. Real keyword uses still fall back gracefully even if missed
        // here: INSERT…SELECT fails the `VALUES (` structural check,
        // DEFAULT-in-VALUES fails `fast_parse_one_value`, and trailing
        // RETURNING / ON CONFLICT fail the `after_values`-empty check.
        if Self::contains_sql_keyword(trimmed, b"RETURNING")
            || Self::contains_sql_keyword(trimmed, b"ON CONFLICT")
            || Self::contains_sql_keyword(trimmed, b"DEFAULT")
            || Self::contains_sql_keyword(trimmed, b"SELECT")
        {
            return None;
        }

        // Parse: INSERT INTO <table> (<col1>, <col2>, ...) VALUES (<val1>, <val2>, ...)
        // Find "INTO " after INSERT
        let after_insert = trimmed.get(6..)?.trim_start();
        if !after_insert.as_bytes().get(..4)?.eq_ignore_ascii_case(b"INTO") {
            return None;
        }
        let after_into = after_insert.get(4..)?.trim_start();

        // Extract table name (until '(' or whitespace). Strip
        // surrounding double quotes so `INSERT INTO "workspaces" …`
        // and `INSERT INTO workspaces …` both match the same schema
        // entry — without this, quoted identifiers fell out of the
        // fast path and routed to the normal path (part of B36).
        let table_end = after_into.find(|c: char| c == '(' || c.is_whitespace())?;
        let table_name = after_into.get(..table_end)?.trim().trim_matches('"');
        if table_name.is_empty() {
            return None;
        }
        let rest = after_into.get(table_end..)?.trim_start();

        // Extract optional column list: (<col1>, <col2>, ...). If omitted,
        // VALUES map to the full schema order.
        let (columns, after_cols): (Option<Vec<&str>>, &str) = if rest.starts_with('(') {
            let col_end = rest.find(')')?;
            let col_list_str = rest.get(1..col_end)?;
            let columns: Vec<&str> = col_list_str.split(',').map(|s| s.trim()).collect();
            if columns.is_empty() || columns.iter().any(|c| c.is_empty()) {
                return None;
            }
            (Some(columns), rest.get(col_end + 1..)?.trim_start())
        } else {
            (None, rest)
        };

        // Find VALUES keyword
        if after_cols.len() < 6 || !after_cols.as_bytes().get(..6)?.eq_ignore_ascii_case(b"VALUES") {
            return None;
        }
        let values_rest = after_cols.get(6..)?.trim_start();

        // Extract values: (<val1>, <val2>, ...)
        if !values_rest.starts_with('(') {
            return None;
        }
        // Find matching closing paren (handle nested strings with single quotes)
        let values_inner = values_rest.get(1..)?;
        let close_idx = Self::find_closing_paren(values_inner)?;
        let values_str = values_inner.get(..close_idx)?;

        // Check nothing significant after the closing paren
        let after_values = values_inner.get(close_idx + 1..)?.trim();
        if !after_values.is_empty() && after_values != ";" {
            return None; // ON CONFLICT, RETURNING, or multi-row VALUES
        }

        // Check RLS — skip fast path if RLS is active
        if self.tenant_manager.should_apply_rls(table_name, "INSERT") {
            return None;
        }

        // Check triggers — skip fast path if triggers exist
        if self.trigger_registry.has_triggers_for_table(table_name) {
            return None;
        }

        let spec = match self.fast_literal_insert_spec(table_name, columns.as_deref(), None)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };
        let tuple = match Self::materialize_fast_literal_insert_tuple(&spec, values_str)? {
            Ok(tuple) => tuple,
            Err(e) => return Some(Err(e)),
        };

        // Use fast INSERT (skip WAL fsync + snapshot versioning) when on main branch
        if self.storage.get_current_branch_id().is_none() {
            Some(
                self.storage
                    .insert_tuple_fast(&spec.table_name, tuple, &spec.schema)
                    .map(|_| 1),
            )
        } else {
            Some(
                self.storage
                    .insert_tuple_branch_aware_with_schema(&spec.table_name, tuple, &spec.schema)
                    .map(|_| 1),
            )
        }
    }

    /// Transaction-aware fast path for simple literal INSERT statements.
    ///
    /// Handles `INSERT INTO t (a, b) VALUES (...)` and `INSERT INTO t VALUES
    /// (...)`, including multi-row VALUES, while buffering rows in the active
    /// transaction write set.
    #[allow(clippy::indexing_slicing)] // validated indices
    fn try_fast_insert_literal_in_transaction(&self, sql: &str, txn: &storage::Transaction) -> Option<Result<u64>> {
        let trimmed = sql.trim();

        if trimmed.len() < 20 || !trimmed.as_bytes().get(..6)?.eq_ignore_ascii_case(b"INSERT") {
            return None;
        }
        if self.tenant_manager.get_current_context().is_some() {
            return None;
        }

        let after_insert = trimmed.get(6..)?.trim_start();
        if !after_insert.as_bytes().get(..4)?.eq_ignore_ascii_case(b"INTO") {
            return None;
        }
        let after_into = after_insert.get(4..)?.trim_start();

        let table_end = after_into.find(|c: char| c == '(' || c.is_whitespace())?;
        let table_name = after_into.get(..table_end)?.trim().trim_matches('"');
        if table_name.is_empty() {
            return None;
        }
        let rest = after_into.get(table_end..)?.trim_start();

        let (explicit_columns, after_cols) = if rest.starts_with('(') {
            let col_end = rest.find(')')?;
            let col_list_str = rest.get(1..col_end)?;
            let columns: Vec<&str> = col_list_str.split(',').map(|s| s.trim().trim_matches('"')).collect();
            if columns.is_empty() || columns.iter().any(|c| c.is_empty()) {
                return None;
            }
            (Some(columns), rest.get(col_end + 1..)?.trim_start())
        } else {
            (None, rest)
        };

        if after_cols.len() < 6 || !after_cols.as_bytes().get(..6)?.eq_ignore_ascii_case(b"VALUES") {
            return None;
        }
        let values_rest = after_cols.get(6..)?.trim_start();

        let single_values = if values_rest.starts_with('(') {
            let inner = values_rest.get(1..)?;
            let close_idx = Self::find_closing_paren(inner)?;
            let values_str = inner.get(..close_idx)?;
            let after_values = inner.get(close_idx + 1..)?.trim_start();
            if after_values.is_empty() || after_values == ";" {
                Some(values_str)
            } else {
                None
            }
        } else {
            None
        };

        if self.tenant_manager.should_apply_rls(table_name, "INSERT") {
            return None;
        }
        if self.trigger_registry.has_triggers_for_table(table_name) {
            return None;
        }

        if let Some(values_str) = single_values {
            let spec = match self.fast_literal_insert_spec(table_name, explicit_columns.as_deref(), None)? {
                Ok(spec) => spec,
                Err(e) => return Some(Err(e)),
            };

            let tuple = match Self::materialize_fast_literal_insert_tuple(&spec, values_str)? {
                Ok(tuple) => tuple,
                Err(e) => return Some(Err(e)),
            };

            return Some(self.insert_validated_tuple_in_transaction(&spec.table_name, tuple, &spec.schema, txn));
        }

        let value_groups = Self::fast_parse_value_groups(values_rest)?;
        let first_values = value_groups.first()?;
        let value_count = Self::fast_parse_value_count(first_values);
        let spec = match self.fast_literal_insert_spec(table_name, explicit_columns.as_deref(), Some(value_count))? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };

        let mut tuples = Vec::with_capacity(value_groups.len());
        for values_str in value_groups {
            if spec.target_types.len() != Self::fast_parse_value_count(values_str) {
                return None;
            }

            let tuple = match Self::materialize_fast_literal_insert_tuple(&spec, values_str)? {
                Ok(tuple) => tuple,
                Err(e) => return Some(Err(e)),
            };
            tuples.push(tuple);
        }

        Some(self.insert_validated_tuples_in_transaction(&spec.table_name, tuples, &spec.schema, txn))
    }

    /// R3.3: after `ALTER TABLE … DROP COLUMN` of a `STORAGE COLUMNAR`
    /// column, drop its `col:`/`colz:`/`colzm:` side-data (a later column
    /// re-created under the same name must not read stale batches) and, when
    /// the table no longer has ANY columnar column, purge the live-row
    /// presence sidecar — presence stops being maintained for row-only
    /// tables, so a stale manifest must not survive a future re-columnarize.
    fn cleanup_columnar_after_drop_column(
        &self,
        table_name: &str,
        column_name: &str,
        was_columnar: bool,
        schema_after: &Schema,
    ) -> Result<()> {
        if !was_columnar {
            return Ok(());
        }
        storage::ColumnarStore::drop_column(&self.storage.db(), table_name, column_name)?;
        if !schema_after
            .columns
            .iter()
            .any(|c| c.storage_mode == ColumnStorageMode::Columnar)
        {
            storage::ColumnarStore::purge_presence(&self.storage.db(), table_name)?;
        }
        Ok(())
    }

    fn tuple_column_values(schema: &Schema, tuple: &Tuple) -> std::collections::HashMap<String, Value> {
        let mut col_values = std::collections::HashMap::with_capacity(schema.columns.len());
        for (i, col) in schema.columns.iter().enumerate() {
            if let Some(value) = tuple.values.get(i) {
                col_values.insert(col.name.clone(), value.clone());
            }
        }
        col_values
    }

    fn validate_fast_insert_batch(&self, table_name: &str, schema: &Schema, prepared: &[(u64, Tuple)]) -> Result<()> {
        if let Some((_, tuple)) = prepared.first() {
            if prepared.len() == 1 {
                if let Err(e) = self
                    .storage
                    .art_indexes()
                    .check_unique_constraints_tuple(table_name, schema, tuple)
                {
                    return Err(Error::constraint_violation(e.to_string()));
                }
                return Ok(());
            }
        }

        // BUG G: derive the intra-batch uniqueness specs from the actual
        // PK/UNIQUE ART indexes, which group composite-key columns together —
        // the same authoritative source the correct single-row
        // `check_unique_constraints_tuple` path trusts. Re-deriving them from
        // per-column `primary_key`/`unique` schema flags fragments a composite
        // `PRIMARY KEY(a, b)` into two bogus single-column specs `[a]` and `[b]`
        // (every member column carries `primary_key = true`), which then keys
        // the intra-batch dedup on each column individually and falsely rejects
        // two *distinct* composite keys that merely share one column value.
        // This shared validator is also reached by multi-row `VALUES` INSERT and
        // COPY, so the fix covers those batch paths too (sweep finding #2).
        let mut unique_specs: Vec<Vec<usize>> = Vec::new();
        for (_name, index_type, columns) in self.storage.art_indexes().list_table_indexes(table_name)
        {
            if !matches!(
                index_type,
                crate::storage::art_index::ArtIndexType::PrimaryKey
                    | crate::storage::art_index::ArtIndexType::Unique
            ) {
                continue;
            }
            let mut indexes = Vec::with_capacity(columns.len());
            let mut resolved = true;
            for col_name in &columns {
                match schema.get_column_index(col_name) {
                    Some(idx) => indexes.push(idx),
                    None => {
                        // Index columns are engine-maintained and always present
                        // in the schema; skip defensively rather than erroring.
                        resolved = false;
                        break;
                    }
                }
            }
            if resolved && !indexes.is_empty() {
                unique_specs.push(indexes);
            }
        }
        unique_specs.sort();
        unique_specs.dedup();

        let check_existing_unique_indexes = self
            .storage
            .art_indexes()
            .pk_index_len(table_name)
            .map_or(true, |len| len != 0);

        let duplicate_key_slots = prepared.len().saturating_mul(unique_specs.len()).max(1);
        let mut seen = std::collections::HashSet::with_capacity(duplicate_key_slots);
        for (_, tuple) in prepared {
            if check_existing_unique_indexes {
                if let Err(e) = self
                    .storage
                    .art_indexes()
                    .check_unique_constraints_tuple(table_name, schema, tuple)
                {
                    return Err(Error::constraint_violation(e.to_string()));
                }
            }

            for spec in &unique_specs {
                let Some(key) = Self::fast_insert_batch_unique_key(spec, tuple) else {
                    continue;
                };
                if !seen.insert(key) {
                    return Err(Error::constraint_violation(
                        "Duplicate key value violates UNIQUE constraint".to_string(),
                    ));
                }
            }
        }

        Ok(())
    }

    fn fast_insert_batch_unique_key(spec: &[usize], tuple: &Tuple) -> Option<Vec<u8>> {
        let mut values = Vec::with_capacity(spec.len());
        for &idx in spec {
            match tuple.values.get(idx) {
                Some(Value::Null) | None => return None,
                Some(value) => values.push(value),
            }
        }

        let value_key = crate::storage::art_manager::ArtIndexManager::encode_key_from_values(values);
        let mut key = Vec::with_capacity(spec.len() * std::mem::size_of::<u64>() + 1 + value_key.len());
        for &idx in spec {
            key.extend_from_slice(&(idx as u64).to_be_bytes());
        }
        key.push(0xff);
        key.extend_from_slice(&value_key);
        Some(key)
    }

    fn insert_validated_tuples_in_transaction(
        &self,
        table_name: &str,
        tuples: Vec<Tuple>,
        schema: &Schema,
        txn: &storage::Transaction,
    ) -> Result<u64> {
        if tuples.len() == 1 {
            let tuple = tuples
                .into_iter()
                .next()
                .ok_or_else(|| Error::internal("missing insert tuple"))?;
            return self.insert_validated_tuple_in_transaction(table_name, tuple, schema, txn);
        }

        let prepared = self.prepare_fast_insert_batch(table_name, tuples, schema)?;

        self.validate_fast_insert_batch(table_name, schema, &prepared)?;

        // R3.3: stage columnar side-data grouped by (column, batch) — one
        // staged read-modify-write per touched batch per statement instead of
        // one per value — including the live-row presence bits.
        if self.storage.get_current_branch().is_none() {
            let row_refs: Vec<(u64, &Tuple)> = prepared.iter().map(|(row_id, tuple)| (*row_id, tuple)).collect();
            self.storage
                .stage_columnar_rows_grouped_in_transaction(table_name, &row_refs, schema, txn, true)?;
        }

        let mut inserted = 0_u64;
        let mut final_row_id = None;
        for (row_id, tuple) in prepared {
            self.insert_prepared_tuple_in_transaction(table_name, row_id, tuple, schema, txn, true, false)?;
            final_row_id = Some(row_id);
            inserted += 1;
        }

        if let Some(row_id) = final_row_id {
            self.storage.stage_row_counter_in_transaction(table_name, row_id, txn)?;
        }
        Ok(inserted)
    }

    fn prepare_fast_insert_batch(
        &self,
        table_name: &str,
        tuples: Vec<Tuple>,
        schema: &Schema,
    ) -> Result<Vec<(u64, Tuple)>> {
        let mut prepared = Vec::with_capacity(tuples.len());
        for tuple in tuples {
            let (row_id, tuple) = self.prepare_tuple_for_transaction_insert(table_name, tuple, schema);
            prepared.push((row_id, tuple));
        }
        Ok(prepared)
    }

    fn insert_validated_tuple_in_transaction(
        &self,
        table_name: &str,
        tuple: Tuple,
        schema: &Schema,
        txn: &storage::Transaction,
    ) -> Result<u64> {
        let (row_id, tuple) = self.prepare_tuple_for_transaction_insert(table_name, tuple, schema);
        self.insert_prepared_tuple_in_transaction(table_name, row_id, tuple, schema, txn, false, true)?;
        self.storage.stage_row_counter_in_transaction(table_name, row_id, txn)?;
        Ok(1)
    }

    fn prepare_tuple_for_transaction_insert(
        &self,
        table_name: &str,
        mut tuple: Tuple,
        schema: &Schema,
    ) -> (u64, Tuple) {
        let row_id = self.storage.next_row_id_volatile(table_name);

        for (i, col) in schema.columns.iter().enumerate() {
            if col.primary_key {
                if let Some(value) = tuple.values.get(i) {
                    if matches!(value, Value::Null) && i < tuple.values.len() {
                        match col.data_type {
                            DataType::Int2 => tuple.values[i] = Value::Int2(row_id as i16),
                            DataType::Int4 => tuple.values[i] = Value::Int4(row_id as i32),
                            _ => tuple.values[i] = Value::Int8(row_id as i64),
                        }
                    }
                }
            }
        }

        (row_id, tuple)
    }

    #[allow(clippy::too_many_arguments)]
    fn insert_prepared_tuple_in_transaction(
        &self,
        table_name: &str,
        row_id: u64,
        tuple: Tuple,
        schema: &Schema,
        txn: &storage::Transaction,
        constraints_prechecked: bool,
        stage_columnar: bool,
    ) -> Result<()> {
        // Callers reach this helper only through the fast INSERT paths, which
        // already reject tables with FK/CHECK constraints while building their
        // statement metadata. Avoid reloading constraint metadata on every row
        // in large explicit-transaction insert loops.

        let col_values = match self
            .storage
            .art_indexes()
            .on_insert_tuple_collect_index_values(table_name, row_id, schema, &tuple)
        {
            Ok(values) => values,
            Err(e) if constraints_prechecked => {
                tracing::debug!("ART index insert for '{}': {}", table_name, e);
                Self::tuple_column_values(schema, &tuple)
            }
            Err(e) => return Err(Error::constraint_violation(e.to_string())),
        };

        // R3.3: multi-row callers stage columnar side-data grouped per batch
        // BEFORE this per-row loop (`stage_columnar = false`); single-row
        // callers stage here (grouped staging marks presence too).
        if stage_columnar && self.storage.get_current_branch().is_none() {
            if let Err(e) = self.storage.stage_columnar_rows_grouped_in_transaction(
                table_name,
                &[(row_id, &tuple)],
                schema,
                txn,
                true,
            ) {
                let _ = self.storage.art_indexes().on_delete(table_name, row_id, &col_values);
                return Err(e);
            }
        }
        let val = bincode::serialize(&tuple).map_err(|e| Error::storage(e.to_string()))?;
        let key = self.storage.branch_aware_data_key(table_name, row_id);
        if let Err(e) = txn.put_insert_fast(key, val) {
            let _ = self.storage.art_indexes().on_delete(table_name, row_id, &col_values);
            return Err(e);
        }
        self.push_art_undo(
            txn,
            ArtUndoOp::RemoveInserted {
                table_name: table_name.to_string(),
                row_id,
                col_values,
            },
        );

        // R5.V1: eagerly maintain HNSW vector indexes (undo on rollback)
        if self.vector_dml_gate(table_name) {
            let vops = self
                .storage
                .vector_indexes()
                .on_row_insert(table_name, row_id, schema, &tuple);
            self.push_vector_undo(txn, vops);
        }

        Ok(())
    }

    fn fast_literal_update_cache_key(table_name: &str, set_col: &str, pk_col: &str) -> String {
        format!("\0fast_literal_update\0{table_name}\0{set_col}\0{pk_col}")
    }

    fn fast_literal_update_spec(
        &self,
        table_name: &str,
        set_col: &str,
        pk_col: &str,
    ) -> Option<Result<std::sync::Arc<FastLiteralUpdateSpec>>> {
        if self.tenant_manager.should_apply_rls(table_name, "UPDATE")
            || self.trigger_registry.has_triggers_for_table(table_name)
        {
            return None;
        }

        let cache_key = Self::fast_literal_update_cache_key(table_name, set_col, pk_col);
        if let Some(spec) = self.fast_literal_update_cache.get(&cache_key) {
            return Some(Ok(spec));
        }

        let catalog = self.storage.catalog();
        let schema = match catalog.get_table_schema(table_name) {
            Ok(schema) => std::sync::Arc::new(schema),
            Err(_) => return None,
        };

        let pk_col_idx = schema.get_column_index(pk_col)?;
        let pk_column = schema.get_column_at(pk_col_idx)?;
        if !pk_column.primary_key {
            return None;
        }
        // BUG F: composite PRIMARY KEY — a single prefix-column equality is not
        // resolvable by the single-value PK index probe; only a sole primary-key
        // column is fast-path eligible. Bail to the planner otherwise.
        if !schema.has_single_column_pk() {
            return None;
        }
        let pk_data_type = pk_column.data_type.clone();

        let set_col_idx = schema.get_column_index(set_col)?;
        let set_column = schema.get_column_at(set_col_idx)?;
        if set_column.primary_key || set_column.unique {
            return None;
        }
        let set_data_type = set_column.data_type.clone();
        let set_nullable = set_column.nullable;

        if self.storage.art_indexes().has_fk(table_name) {
            return None;
        }
        if let Ok(constraints) = catalog.load_table_constraints(table_name) {
            if !constraints.foreign_keys.is_empty() || !constraints.check_constraints.is_empty() {
                return None;
            }
        }

        let assignment_columns = [set_col.to_string()];
        let assignment_affects_indexes = self
            .storage
            .art_indexes()
            .columns_affect_indexes(table_name, &assignment_columns);

        let spec = std::sync::Arc::new(FastLiteralUpdateSpec {
            table_name: table_name.to_string(),
            schema,
            pk_data_type,
            set_col_idx,
            set_col_name: set_col.to_string(),
            set_data_type,
            set_nullable,
            assignment_affects_indexes,
        });
        self.fast_literal_update_cache
            .put(cache_key, std::sync::Arc::clone(&spec));
        Some(Ok(spec))
    }

    fn fast_literal_delete_cache_key(
        table_name: &str,
        pk_col: &str,
        fk_mode: FkValidationMode,
        fk_source: FkValidationSource,
    ) -> String {
        format!("\0fast_literal_delete\0{fk_mode:?}\0{fk_source:?}\0{table_name}\0{pk_col}")
    }

    fn fast_literal_delete_spec(
        &self,
        table_name: &str,
        pk_col: &str,
        fk_mode: FkValidationMode,
        fk_source: FkValidationSource,
    ) -> Option<Result<std::sync::Arc<FastLiteralDeleteSpec>>> {
        if self.tenant_manager.should_apply_rls(table_name, "DELETE")
            || self.tenant_manager.get_current_context().is_some()
            || self.trigger_registry.has_triggers_for_table(table_name)
        {
            return None;
        }

        let cache_key = Self::fast_literal_delete_cache_key(table_name, pk_col, fk_mode, fk_source);
        if let Some(spec) = self.fast_literal_delete_cache.get(&cache_key) {
            return Some(Ok(spec));
        }

        let catalog = self.storage.catalog();
        let schema = match catalog.get_table_schema(table_name) {
            Ok(schema) => std::sync::Arc::new(schema),
            Err(_) => return None,
        };

        let pk_col_idx = schema.get_column_index(pk_col)?;
        let pk_column = schema.get_column_at(pk_col_idx)?;
        if !pk_column.primary_key {
            return None;
        }
        // BUG F: composite PRIMARY KEY — a single prefix-column equality is not
        // resolvable by the single-value PK index probe; only a sole primary-key
        // column is fast-path eligible. Bail to the planner otherwise.
        if !schema.has_single_column_pk() {
            return None;
        }
        let pk_data_type = pk_column.data_type.clone();

        if let Ok(constraints) = catalog.load_table_constraints(table_name) {
            if !constraints.foreign_keys.is_empty() {
                return None;
            }
        }
        if fk_mode != FkValidationMode::Off && fk_source != FkValidationSource::Proxy {
            match catalog.get_referencing_fks(table_name) {
                Ok(referencing_fks) if referencing_fks.is_empty() => {}
                Ok(_) => return None,
                Err(e) => return Some(Err(e)),
            }
        }

        let spec = std::sync::Arc::new(FastLiteralDeleteSpec {
            table_name: table_name.to_string(),
            pk_only_delete: self.fast_delete_can_skip_tuple_fetch(table_name, &schema),
            schema,
            pk_data_type,
        });
        self.fast_literal_delete_cache
            .put(cache_key, std::sync::Arc::clone(&spec));
        Some(Ok(spec))
    }

    fn fast_delete_can_skip_tuple_fetch(&self, table_name: &str, schema: &Schema) -> bool {
        schema
            .columns
            .iter()
            .all(|column| column.storage_mode == ColumnStorageMode::Default)
            && self.storage.art_indexes().has_only_single_column_pk_index(table_name)
    }

    /// Fast path for simple UPDATE: `UPDATE table SET col = literal WHERE pk_col = literal`
    /// Returns None to fall through to normal path for complex UPDATE statements.
    fn try_fast_update(&self, sql: &str) -> Option<Result<u64>> {
        let trimmed = sql.trim();

        // Quick prefix check
        if trimmed.len() < 20 || !trimmed.as_bytes().get(..6)?.eq_ignore_ascii_case(b"UPDATE") {
            return None;
        }

        // Bail on complex features. Word-boundary + literal-aware (R1.2):
        // `SET note = 'from paris'` or a table named `case_files` no longer
        // bails; real RETURNING/JOIN/FROM/SELECT/CASE/COALESCE keywords do.
        if Self::contains_sql_keyword(trimmed, b"RETURNING")
            || Self::contains_sql_keyword(trimmed, b"JOIN")
            || Self::contains_sql_keyword(trimmed, b"FROM")
            || Self::contains_sql_keyword(trimmed, b"SELECT")
            || Self::contains_sql_keyword(trimmed, b"CASE")
            || Self::contains_sql_keyword(trimmed, b"COALESCE")
        {
            return None;
        }

        // Parse: UPDATE <table> SET <col> = <val> WHERE <pk_col> = <pk_val>
        let after_update = trimmed.get(6..)?.trim_start();

        // Extract table name (until whitespace)
        let table_end = after_update.find(|c: char| c.is_whitespace())?;
        let table_name = after_update.get(..table_end)?.trim();
        if table_name.is_empty() {
            return None;
        }
        let rest = after_update.get(table_end..)?.trim_start();

        // Expect SET keyword
        if rest.len() < 3 || !rest.as_bytes().get(..3)?.eq_ignore_ascii_case(b"SET") {
            return None;
        }
        let after_set = rest.get(3..)?.trim_start();

        // Find WHERE keyword (case-insensitive, word-bounded, outside string
        // literals — `SET msg = 'tell me where' WHERE id = 1` splits at the
        // real WHERE, not the one inside the literal).
        let where_pos = Self::find_sql_keyword(after_set, b"WHERE")?;
        if where_pos == 0 {
            return None; // Empty SET clause
        }

        let set_clause = after_set.get(..where_pos)?.trim();
        let where_clause = after_set.get(where_pos + 5..)?.trim();

        // Parse SET clause: col = value (single assignment only for fast path)
        if set_clause.contains(',') {
            return None; // Multiple columns — fall through
        }
        let eq_pos = set_clause.find('=')?;
        let set_col = set_clause.get(..eq_pos)?.trim();
        let set_val_str = set_clause.get(eq_pos + 1..)?.trim();
        if set_col.is_empty() || set_val_str.is_empty() {
            return None;
        }

        // Parse WHERE clause: pk_col = pk_value
        // Strip trailing semicolon if present
        let where_clause = where_clause.strip_suffix(';').unwrap_or(where_clause).trim();
        // Bail on complex WHERE (AND, OR, etc.). Word-boundary + literal-aware
        // (R1.2): `WHERE points = 5` (contains "in") and `WHERE order_id = 3`
        // (contains "or") no longer bail; real AND/OR/IN/BETWEEN keywords do.
        if Self::contains_sql_keyword(where_clause, b"AND")
            || Self::contains_sql_keyword(where_clause, b"OR")
            || Self::contains_sql_keyword(where_clause, b"IN")
            || Self::contains_sql_keyword(where_clause, b"BETWEEN")
        {
            return None;
        }
        let weq_pos = where_clause.find('=')?;
        let pk_col = where_clause.get(..weq_pos)?.trim();
        let pk_val_str = where_clause.get(weq_pos + 1..)?.trim();
        if pk_col.is_empty() || pk_val_str.is_empty() {
            return None;
        }

        // Check branch — skip fast path on branches
        if self.storage.get_current_branch_id().is_some() {
            return None;
        }

        let spec = match self.fast_literal_update_spec(table_name, set_col, pk_col)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };

        // Parse PK value. The literal must consume the whole token — trailing
        // text (e.g. `WHERE id = 5 LIMIT 1`) means the fast parser didn't
        // understand the full clause and must fall back to the planner.
        let (pk_value, pk_rest) = Self::fast_parse_one_value(pk_val_str, &spec.pk_data_type)?;
        if !pk_rest.trim().is_empty() {
            return None;
        }

        // Look up the existing row by PK (needed for both literal and expression SET)
        let existing_row =
            match self
                .storage
                .get_row_by_typed_pk_for_write_with_schema(&spec.table_name, &pk_value, &spec.schema)
            {
                Ok(Some(row)) => row,
                Ok(None) => return Some(Ok(0)), // No matching row
                Err(e) => return Some(Err(e)),
            };

        let row_id = existing_row.row_id.unwrap_or(0);
        if row_id == 0 {
            return None; // No row_id — can't do fast update
        }

        // Parse SET value: try literal first, then simple expression (col +/- literal).
        // A literal with trailing text (`SET x = 5 junk`) is not a literal —
        // fall through to the expression/planner paths.
        let new_value = if let Some(val) = Self::fast_parse_one_value(set_val_str, &spec.set_data_type)
            .and_then(|(val, rest)| rest.trim().is_empty().then_some(val))
        {
            val
        } else if let Some(val) =
            Self::fast_eval_simple_expr(set_val_str, &spec.set_col_name, spec.set_col_idx, &existing_row)
        {
            val
        } else {
            return None; // Complex expression — fall through to normal path
        };

        // Check NOT NULL constraint
        if !spec.set_nullable && matches!(new_value, Value::Null) {
            return Some(Err(Error::constraint_violation(format!(
                "Column '{}' cannot be null",
                spec.set_col_name
            ))));
        }

        if spec.set_col_idx >= existing_row.values.len() {
            return None;
        }

        let result = if spec.assignment_affects_indexes {
            let mut new_values = existing_row.values.clone();
            new_values[spec.set_col_idx] = new_value;
            let new_tuple = Tuple::new(new_values);

            // Preserve logical WAL / HA broadcast semantics only when strict
            // logical WAL or HA replication needs the logical stream. In the
            // standalone default, RocksDB's own WAL covers local recovery.
            if self.storage.fast_dml_requires_logical_wal() {
                let key = self.storage.branch_aware_data_key(&spec.table_name, row_id);
                let value = match bincode::serialize(&new_tuple) {
                    Ok(value) => value,
                    Err(e) => return Some(Err(Error::storage(format!("Failed to serialize tuple: {}", e)))),
                };
                let wal_result = if self.storage.logical_wal_per_statement() {
                    self.storage.log_data_update(&spec.table_name, &key, &value)
                } else {
                    self.storage.log_data_update_nosync(&spec.table_name, &key, &value)
                };
                if let Err(e) = wal_result {
                    return Some(Err(e));
                }
            }

            self.storage.update_tuple_fast_with_index_hint(
                &spec.table_name,
                row_id,
                new_tuple,
                &existing_row,
                &spec.schema,
                Some(true),
            )
        } else {
            // R5.V1: keep the pre-update row for HNSW vector maintenance when
            // the table has a vector index (one atomic load otherwise).
            let vector_old_tuple = if self.storage.vector_indexes().table_has_indexes(&spec.table_name) {
                Some(existing_row.clone())
            } else {
                None
            };
            let mut new_tuple = existing_row;
            new_tuple.row_id = None;
            new_tuple.branch_id = None;
            new_tuple.values[spec.set_col_idx] = new_value;

            if self.storage.fast_dml_requires_logical_wal() {
                let key = self.storage.branch_aware_data_key(&spec.table_name, row_id);
                let value = match bincode::serialize(&new_tuple) {
                    Ok(value) => value,
                    Err(e) => return Some(Err(Error::storage(format!("Failed to serialize tuple: {}", e)))),
                };
                let wal_result = if self.storage.logical_wal_per_statement() {
                    self.storage.log_data_update(&spec.table_name, &key, &value)
                } else {
                    self.storage.log_data_update_nosync(&spec.table_name, &key, &value)
                };
                if let Err(e) = wal_result {
                    return Some(Err(e));
                }
            }

            self.storage.update_tuple_fast_no_index(
                &spec.table_name,
                row_id,
                new_tuple,
                &spec.schema,
                vector_old_tuple.as_ref(),
            )
        };

        Some(result)
    }

    fn prepare_fast_delete(&self, sql: &str, require_tuple: bool) -> Option<Result<Option<FastDeleteTarget>>> {
        let trimmed = sql.trim();

        if trimmed.len() < 24 || !trimmed.as_bytes().get(..6)?.eq_ignore_ascii_case(b"DELETE") {
            return None;
        }

        // Word-boundary + literal-aware (R1.2): a table named `with_drawals`
        // or a literal containing 'select' no longer bails; real
        // RETURNING/USING/JOIN/SELECT/WITH keywords still do.
        if Self::contains_sql_keyword(trimmed, b"RETURNING")
            || Self::contains_sql_keyword(trimmed, b"USING")
            || Self::contains_sql_keyword(trimmed, b"JOIN")
            || Self::contains_sql_keyword(trimmed, b"SELECT")
            || Self::contains_sql_keyword(trimmed, b"WITH")
        {
            return None;
        }

        let after_delete = trimmed.get(6..)?.trim_start();
        if after_delete.len() < 4 || !after_delete.as_bytes().get(..4)?.eq_ignore_ascii_case(b"FROM") {
            return None;
        }
        let after_from = after_delete.get(4..)?.trim_start();

        let table_end = after_from.find(|c: char| c.is_whitespace())?;
        let table_name = after_from.get(..table_end)?.trim().trim_matches('"');
        if table_name.is_empty() {
            return None;
        }

        let rest = after_from.get(table_end..)?.trim_start();
        if rest.len() < 5 || !rest.as_bytes().get(..5)?.eq_ignore_ascii_case(b"WHERE") {
            return None;
        }

        let where_clause = rest.get(5..)?.trim_start();
        let where_clause = where_clause.strip_suffix(';').unwrap_or(where_clause).trim();
        // Word-boundary + literal-aware (R1.2): `WHERE finalized = 1`
        // (contains "in") no longer bails; real AND/OR/IN/BETWEEN/LIKE do.
        if Self::contains_sql_keyword(where_clause, b"AND")
            || Self::contains_sql_keyword(where_clause, b"OR")
            || Self::contains_sql_keyword(where_clause, b"IN")
            || Self::contains_sql_keyword(where_clause, b"BETWEEN")
            || Self::contains_sql_keyword(where_clause, b"LIKE")
        {
            return None;
        }

        let eq_pos = where_clause.find('=')?;
        if where_clause.get(eq_pos + 1..)?.contains('=') {
            return None;
        }
        let pk_col = where_clause.get(..eq_pos)?.trim().trim_matches('"');
        let pk_val_str = where_clause.get(eq_pos + 1..)?.trim();
        if pk_col.is_empty() || pk_val_str.is_empty() {
            return None;
        }

        if self.tenant_manager.should_apply_rls(table_name, "DELETE")
            || self.tenant_manager.get_current_context().is_some()
        {
            return None;
        }
        if self.trigger_registry.has_triggers_for_table(table_name) {
            return None;
        }
        if self.storage.get_current_branch().is_some() {
            return None;
        }

        let fk_mode = *self.fk_validation_mode.read();
        let fk_source = *self.fk_validation_source.read();
        let spec = match self.fast_literal_delete_spec(table_name, pk_col, fk_mode, fk_source)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };

        // The PK literal must consume the whole token — trailing text means
        // an unparsed construct; fall back to the planner.
        let (pk_value, pk_rest) = Self::fast_parse_one_value(pk_val_str, &spec.pk_data_type)?;
        if !pk_rest.trim().is_empty() {
            return None;
        }
        let pk_key = crate::storage::art_manager::ArtIndexManager::encode_key(std::slice::from_ref(&pk_value));
        let (row_id, existing_row) = if spec.pk_only_delete && !require_tuple {
            match self.storage.art_indexes().pk_index_lookup(&spec.table_name, &pk_key) {
                Some(row_id) => (row_id, None),
                None => return Some(Ok(None)),
            }
        } else {
            let existing_row =
                match self
                    .storage
                    .get_row_by_typed_pk_for_write_with_schema(&spec.table_name, &pk_value, &spec.schema)
                {
                    Ok(Some(row)) => row,
                    Ok(None) => return Some(Ok(None)),
                    Err(e) => return Some(Err(e)),
                };

            let row_id = existing_row.row_id.unwrap_or(0);
            if row_id == 0 {
                return None;
            }
            (row_id, Some(existing_row))
        };

        Some(Ok(Some(FastDeleteTarget {
            table_name: spec.table_name.clone(),
            row_id,
            pk_key,
            pk_value,
            schema: std::sync::Arc::clone(&spec.schema),
            existing_row,
            pk_only_delete: spec.pk_only_delete,
        })))
    }

    /// Fast path for simple DELETE: `DELETE FROM table WHERE pk_col = literal`.
    /// Returns None to fall through to the normal path for complex DELETE statements.
    fn try_fast_delete(&self, sql: &str, txn: &storage::Transaction) -> Option<Result<u64>> {
        let target = match self.prepare_fast_delete(sql, true)? {
            Ok(Some(target)) => target,
            Ok(None) => return Some(Ok(0)),
            Err(e) => return Some(Err(e)),
        };
        let existing_row = target.existing_row.as_ref()?;
        let result = (|| {
            let key = self.storage.branch_aware_data_key(&target.table_name, target.row_id);
            self.storage.stage_columnar_delete_in_transaction(
                &target.table_name,
                target.row_id,
                &target.schema,
                txn,
            )?;
            txn.delete(key.clone())?;

            if self.storage.fast_dml_requires_logical_wal() {
                if self.storage.logical_wal_per_statement() {
                    self.storage.log_data_delete(&target.table_name, &key)?;
                } else {
                    self.storage.log_data_delete_nosync(&target.table_name, &key)?;
                }
            }

            if let Err(e) = self.storage.art_indexes().on_delete_tuple(
                &target.table_name,
                target.row_id,
                &target.schema,
                existing_row,
            ) {
                tracing::debug!("ART index delete for table '{}': {}", target.table_name, e);
            }

            let mut col_values = std::collections::HashMap::with_capacity(target.schema.columns.len());
            for (i, col) in target.schema.columns.iter().enumerate() {
                if let Some(v) = existing_row.values.get(i) {
                    col_values.insert(col.name.clone(), v.clone());
                }
            }
            self.push_art_undo(
                txn,
                ArtUndoOp::RestoreDeleted {
                    table_name: target.table_name.clone(),
                    row_id: target.row_id,
                    col_values,
                },
            );

            // R5.V1: eagerly drop the row from HNSW vector indexes (undo on rollback)
            if self.vector_dml_gate(&target.table_name) {
                let vops = self.storage.vector_indexes().on_row_delete(
                    &target.table_name,
                    target.row_id,
                    Some(&target.schema),
                    Some(existing_row),
                );
                self.push_vector_undo(txn, vops);
            }

            self.storage.row_cache().invalidate(&target.table_name, target.row_id);
            Ok(1)
        })();

        Some(result)
    }

    fn try_fast_delete_autocommit(&self, sql: &str) -> Option<Result<u64>> {
        let target = match self.prepare_fast_delete(sql, false)? {
            Ok(Some(target)) => target,
            Ok(None) => return Some(Ok(0)),
            Err(e) => return Some(Err(e)),
        };

        let result = (|| {
            if self.storage.fast_dml_requires_logical_wal() {
                let key = self.storage.branch_aware_data_key(&target.table_name, target.row_id);
                if self.storage.logical_wal_per_statement() {
                    self.storage.log_data_delete(&target.table_name, &key)?;
                } else {
                    self.storage.log_data_delete_nosync(&target.table_name, &key)?;
                }
            }

            if target.pk_only_delete {
                self.storage.delete_tuple_fast_pk_only(
                    &target.table_name,
                    target.row_id,
                    &target.pk_key,
                    &target.pk_value,
                )
            } else {
                let existing_row = target
                    .existing_row
                    .as_ref()
                    .ok_or_else(|| Error::internal("missing fast delete tuple"))?;
                self.storage
                    .delete_tuple_fast(&target.table_name, target.row_id, existing_row, &target.schema)
            }
        })();

        Some(result)
    }

    fn fast_select_cache_key(table_name: &str, pk_col: &str) -> String {
        format!("\0fast_select\0{table_name}\0{pk_col}")
    }

    fn fast_select_spec(&self, table_name: &str, pk_col: &str) -> Option<Result<std::sync::Arc<FastSelectSpec>>> {
        if self.tenant_manager.should_apply_rls(table_name, "SELECT") {
            return None;
        }

        // R2.1: hot single-slot front. Point-lookup workloads resolve the
        // same (table, pk) spec on every statement; a shared-read slot keeps
        // the per-statement path off any mutex (an LRU `get` always needs
        // exclusive access for recency bookkeeping, so even a sharded cache
        // serializes on one hot key). Check this slot before building the LRU
        // key so the 1T point-lookup path avoids one allocation per query.
        if let Some(spec) = self.hot_fast_select_spec.read().as_ref().and_then(|spec| {
            (spec.table_name == table_name && spec.pk_col == pk_col).then(|| std::sync::Arc::clone(spec))
        }) {
            return Some(Ok(spec));
        }

        let cache_key = Self::fast_select_cache_key(table_name, pk_col);
        if let Some(spec) = self.fast_select_cache.get(&cache_key) {
            *self.hot_fast_select_spec.write() = Some(std::sync::Arc::clone(&spec));
            return Some(Ok(spec));
        }

        let catalog = self.storage.catalog();
        let schema = match catalog.get_table_schema(table_name) {
            Ok(schema) => std::sync::Arc::new(schema),
            Err(_) => return None,
        };

        let pk_col_idx = schema.get_column_index(pk_col)?;
        let pk_column = schema.get_column_at(pk_col_idx)?;
        if !pk_column.primary_key {
            return None;
        }
        // BUG F (read path / sweep finding #1): a composite PRIMARY KEY marks
        // every member column `primary_key = true`. A fast point SELECT on a
        // prefix column would build a single-value key that can never match the
        // grouped composite index entry, silently returning zero rows. Only a
        // sole PK column is fast-path eligible; otherwise the planner scans.
        if !schema.has_single_column_pk() {
            return None;
        }
        let pk_data_type = pk_column.data_type.clone();

        let spec = std::sync::Arc::new(FastSelectSpec {
            table_name: table_name.to_string(),
            pk_col: pk_col.to_string(),
            schema,
            pk_data_type,
        });
        self.fast_select_cache
            .put(cache_key.clone(), std::sync::Arc::clone(&spec));
        *self.hot_fast_select_spec.write() = Some(std::sync::Arc::clone(&spec));
        Some(Ok(spec))
    }

    /// Fast path for SELECT: `SELECT * FROM table WHERE pk_col = literal`
    /// Bypasses full SQL parsing, planning, and optimization for simple PK lookups.
    fn try_fast_select(&self, sql: &str) -> Option<Result<Vec<Tuple>>> {
        let (spec, pk_value) = match self.fast_select_lookup(sql)? {
            Ok(lookup) => lookup,
            Err(e) => return Some(Err(e)),
        };

        Some(self.fast_select_rows(&spec, &pk_value))
    }

    fn try_fast_select_with_columns(&self, sql: &str) -> Option<Result<(Vec<Tuple>, Vec<String>)>> {
        let (spec, pk_value) = match self.fast_select_lookup(sql)? {
            Ok(lookup) => lookup,
            Err(e) => return Some(Err(e)),
        };

        let columns = spec.schema.columns.iter().map(|column| column.name.clone()).collect();
        Some(self.fast_select_rows(&spec, &pk_value).map(|rows| (rows, columns)))
    }

    fn fast_select_lookup(&self, sql: &str) -> Option<Result<(std::sync::Arc<FastSelectSpec>, Value)>> {
        if self.in_transaction() {
            return None;
        }

        let trimmed = sql.trim();

        // Quick prefix check
        if trimmed.len() < 20 || !trimmed.as_bytes().get(..6)?.eq_ignore_ascii_case(b"SELECT") {
            return None;
        }

        let after_select = trimmed.get(6..)?.trim_start();

        // Only handle SELECT * (not column lists, expressions, aliases)
        if !after_select.starts_with('*') {
            return None;
        }
        let after_star = after_select.get(1..)?.trim_start();

        // Expect FROM keyword
        if after_star.len() < 4 || !after_star.as_bytes().get(..4)?.eq_ignore_ascii_case(b"FROM") {
            return None;
        }
        let after_from = after_star.get(4..)?.trim_start();

        // Extract table name (until whitespace)
        let table_end = after_from.find(|c: char| c.is_whitespace())?;
        let table_name = after_from.get(..table_end)?.trim().trim_matches('"');
        if table_name.is_empty() {
            return None;
        }
        let rest = after_from.get(table_end..)?.trim_start();

        // Expect WHERE keyword
        if rest.len() < 5 || !rest.as_bytes().get(..5)?.eq_ignore_ascii_case(b"WHERE") {
            return None;
        }
        let where_clause = rest.get(5..)?.trim_start();

        let simple_where_clause = where_clause.strip_suffix(';').unwrap_or(where_clause).trim();
        if let Some(eq_pos) = simple_where_clause.find('=') {
            let pk_col = simple_where_clause.get(..eq_pos)?.trim().trim_matches('"');
            let pk_val_str = simple_where_clause.get(eq_pos + 1..)?.trim();
            if !pk_col.is_empty() && !pk_val_str.is_empty() {
                let spec = match self.fast_select_spec(table_name, pk_col)? {
                    Ok(spec) => spec,
                    Err(e) => return Some(Err(e)),
                };
                if let Some((pk_value, pk_rest)) = Self::fast_parse_one_value(pk_val_str, &spec.pk_data_type) {
                    if pk_rest.trim().is_empty() {
                        return Some(Ok((spec, pk_value)));
                    }
                }
            }
        }

        // Bail on complex WHERE. Word-boundary + literal-aware (R1.2):
        // `WHERE order_id = 3` (contains "or"/"order") no longer bails;
        // real AND/OR/JOIN/ORDER/GROUP/LIMIT keywords still do.
        if Self::contains_sql_keyword(where_clause, b"AND")
            || Self::contains_sql_keyword(where_clause, b"OR")
            || Self::contains_sql_keyword(where_clause, b"JOIN")
            || Self::contains_sql_keyword(where_clause, b"ORDER")
            || Self::contains_sql_keyword(where_clause, b"GROUP")
            || Self::contains_sql_keyword(where_clause, b"LIMIT")
        {
            return None;
        }

        // Parse WHERE: col = value
        let where_clause = where_clause.strip_suffix(';').unwrap_or(where_clause).trim();
        let eq_pos = where_clause.find('=')?;
        let pk_col = where_clause.get(..eq_pos)?.trim().trim_matches('"');
        let pk_val_str = where_clause.get(eq_pos + 1..)?.trim();
        if pk_col.is_empty() || pk_val_str.is_empty() {
            return None;
        }

        let spec = match self.fast_select_spec(table_name, pk_col)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };

        // Parse PK value; trailing text after the literal means an unparsed
        // construct — fall back to the planner.
        let (pk_value, pk_rest) = Self::fast_parse_one_value(pk_val_str, &spec.pk_data_type)?;
        if !pk_rest.trim().is_empty() {
            return None;
        }

        Some(Ok((spec, pk_value)))
    }

    fn fast_select_rows(&self, spec: &FastSelectSpec, pk_value: &Value) -> Result<Vec<Tuple>> {
        let result = if self.config.storage.memory_only {
            // In-memory hot-set workloads deliberately pre-warm the row cache.
            // Disk-backed random point lookups keep no-cache-fill admission to
            // avoid paying cache insert cost for one-off reads.
            self.storage
                .get_row_by_typed_pk_with_schema(&spec.table_name, pk_value, &spec.schema)
        } else {
            self.storage
                .get_row_by_typed_pk_with_schema_no_cache_fill(&spec.table_name, pk_value, &spec.schema)
        };
        match result {
            Ok(Some(row)) => Ok(vec![row]),
            Ok(None) => Ok(vec![]),
            Err(e) => Err(e),
        }
    }

    fn try_fast_count_pk_query(&self, sql: &str) -> Option<Result<Vec<Tuple>>> {
        if self.in_transaction()
            || self.storage.is_branch_active()
            || self.tenant_manager.get_current_context().is_some()
        {
            return None;
        }

        let trimmed = sql.trim();
        if trimmed.len() < 20 || !trimmed.as_bytes().get(..6)?.eq_ignore_ascii_case(b"SELECT") {
            return None;
        }

        let after_select = trimmed.get(6..)?.trim_start();
        if after_select.len() < 5 || !after_select.as_bytes().get(..5)?.eq_ignore_ascii_case(b"COUNT") {
            return None;
        }
        let after_count = after_select.get(5..)?.trim_start();
        let count_inner = after_count.strip_prefix('(')?;
        let close_idx = Self::find_closing_paren(count_inner)?;
        let count_arg = count_inner.get(..close_idx)?.trim().trim_matches('"');
        if count_arg.is_empty() || count_arg.bytes().any(|b| b == b',' || b == b'(' || b == b')') {
            return None;
        }
        let mut rest = count_inner.get(close_idx + 1..)?.trim_start();
        rest = strip_prefix_icase(rest, "FROM")?.trim_start();

        let (table_name, after_table) = Self::fast_split_table_name(rest)?;
        if self.tenant_manager.should_apply_rls(table_name, "SELECT") {
            return None;
        }
        match self.storage.mv_catalog().view_exists(table_name) {
            Ok(true) | Err(_) => return None,
            Ok(false) => {}
        }

        let pk_col = if count_arg == "*" {
            None
        } else {
            Some(count_arg)
        };
        let spec = match self.fast_count_pk_spec(table_name, pk_col)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };

        let where_clause = after_table.strip_suffix(';').unwrap_or(after_table).trim();
        let count = if where_clause.is_empty() {
            match self.storage.count_table_rows(&spec.table_name) {
                Ok(count) => count,
                Err(e) => return Some(Err(e)),
            }
        } else {
            let predicate = strip_prefix_icase(where_clause, "WHERE")?.trim();
            match self.fast_count_pk_predicate(&spec, predicate) {
                Some(Ok(count)) => count,
                Some(Err(e)) => return Some(Err(e)),
                None => return None,
            }
        };

        Some(Ok(vec![Tuple {
            values: vec![Value::Int8(count as i64)],
            row_id: None,
            branch_id: None,
        }]))
    }

    fn fast_count_pk_spec(
        &self,
        table_name: &str,
        count_pk_col: Option<&str>,
    ) -> Option<Result<std::sync::Arc<FastSelectSpec>>> {
        let catalog = self.storage.catalog();
        let schema = match catalog.get_table_schema(table_name) {
            Ok(schema) => schema,
            Err(_) => return None,
        };
        let mut pk_cols = schema.columns.iter().filter(|col| col.primary_key);
        let pk_col = match (pk_cols.next(), pk_cols.next()) {
            (Some(col), None) => col,
            _ => return None,
        };
        if count_pk_col.is_some_and(|col| !col.eq_ignore_ascii_case(&pk_col.name)) {
            return None;
        }
        if !matches!(pk_col.data_type, DataType::Int2 | DataType::Int4 | DataType::Int8) {
            return None;
        }
        self.fast_select_spec(table_name, &pk_col.name)
    }

    fn fast_count_pk_predicate(&self, spec: &FastSelectSpec, predicate: &str) -> Option<Result<usize>> {
        let predicate = predicate.strip_suffix(';').unwrap_or(predicate).trim();
        if predicate.is_empty()
            || Self::contains_sql_keyword(predicate, b"OR")
            || Self::contains_sql_keyword(predicate, b"JOIN")
            || Self::contains_sql_keyword(predicate, b"LIKE")
            || Self::contains_sql_keyword(predicate, b"BETWEEN")
            || Self::contains_sql_keyword(predicate, b"ORDER")
            || Self::contains_sql_keyword(predicate, b"GROUP")
            || Self::contains_sql_keyword(predicate, b"LIMIT")
        {
            return None;
        }

        if let Some(open_idx) = Self::find_sql_keyword(predicate, b"IN") {
            return self.fast_count_pk_in_predicate(spec, predicate, open_idx);
        }

        let mut lower = None;
        let mut upper = None;
        for part in Self::fast_split_and_terms(predicate)? {
            let (term_lower, term_upper) = self.fast_pk_bound_term(spec, part)?;
            lower = Self::merge_fast_lower_bound(lower, term_lower)?;
            upper = Self::merge_fast_upper_bound(upper, term_upper)?;
        }

        match self
            .storage
            .count_table_pk_int_range_with_schema(&spec.table_name, &spec.schema, lower, upper)
        {
            Ok(Some(count)) => Some(Ok(count)),
            Ok(None) => None,
            Err(e) => Some(Err(e)),
        }
    }

    fn fast_count_pk_in_predicate(
        &self,
        spec: &FastSelectSpec,
        predicate: &str,
        in_idx: usize,
    ) -> Option<Result<usize>> {
        let left = predicate.get(..in_idx)?.trim().trim_matches('"');
        if !left.eq_ignore_ascii_case(&spec.pk_col) {
            return None;
        }
        let after_in = predicate.get(in_idx + 2..)?.trim_start();
        let inner = after_in.strip_prefix('(')?;
        let close_idx = Self::find_closing_paren(inner)?;
        let values = inner.get(..close_idx)?;
        if !inner.get(close_idx + 1..)?.trim().is_empty() {
            return None;
        }

        // NOTE (Opus 2026-06-13): the per-key dedupe + per-key pk_index_contains
        // probe below is the EMPIRICALLY-CHOSEN path. A batched-helper variant
        // (HashSet dedupe + pk_index_count_keys single-lock probe) was tried by
        // Fable 5 and REGRESSED small `count_pk(id IN)` probes (~-3.9%, see
        // perf/v337_vs_latest/focused_scan_art_batch_*), so it was reverted.
        // Left as-is intentionally; do not "optimize" without an A/B.
        let mut seen_keys: Vec<Vec<u8>> = Vec::new();
        for raw in Self::fast_split_comma_terms(values)? {
            let value = match Self::fast_literal_for_type(raw, &spec.pk_data_type) {
                Some(value) if !matches!(value, Value::Null) => value,
                Some(_) => continue,
                None => return None,
            };
            let key = storage::ArtIndexManager::encode_key(std::slice::from_ref(&value));
            if seen_keys.iter().any(|seen| seen == &key) {
                continue;
            }
            seen_keys.push(key);
        }

        let mut count = 0usize;
        for key in &seen_keys {
            match self.storage.art_indexes().pk_index_contains(&spec.table_name, key) {
                Some(true) => count += 1,
                Some(false) => {}
                None => return None,
            }
        }
        Some(Ok(count))
    }

    fn fast_pk_bound_term(
        &self,
        spec: &FastSelectSpec,
        term: &str,
    ) -> Option<(Option<(i64, bool)>, Option<(i64, bool)>)> {
        for op in ["<=", ">=", "=", "<", ">"] {
            let Some(op_idx) = term.find(op) else {
                continue;
            };
            let left = term.get(..op_idx)?.trim().trim_matches('"');
            let right = term.get(op_idx + op.len()..)?.trim();
            if !left.eq_ignore_ascii_case(&spec.pk_col) {
                return None;
            }
            let value = Self::fast_i64_literal_for_type(right, &spec.pk_data_type)?;
            return match op {
                "=" => Some((Some((value, true)), Some((value, true)))),
                ">=" => Some((Some((value, true)), None)),
                ">" => Some((Some((value, false)), None)),
                "<=" => Some((None, Some((value, true)))),
                "<" => Some((None, Some((value, false)))),
                _ => None,
            };
        }
        None
    }

    fn fast_literal_for_type(token: &str, target_type: &DataType) -> Option<Value> {
        let token = Self::strip_fast_postgres_type_cast(token.trim());
        let (value, rest) = Self::fast_parse_one_value(token, target_type)?;
        rest.trim().is_empty().then_some(value)
    }

    fn fast_i64_literal_for_type(token: &str, target_type: &DataType) -> Option<i64> {
        match Self::fast_literal_for_type(token, target_type)? {
            Value::Int2(v) => Some(i64::from(v)),
            Value::Int4(v) => Some(i64::from(v)),
            Value::Int8(v) => Some(v),
            _ => None,
        }
    }

    fn merge_fast_lower_bound(
        existing: Option<(i64, bool)>,
        incoming: Option<(i64, bool)>,
    ) -> Option<Option<(i64, bool)>> {
        Some(match (existing, incoming) {
            (None, bound) | (bound, None) => bound,
            (Some((a, ai)), Some((b, bi))) => {
                if b > a {
                    Some((b, bi))
                } else if a > b {
                    Some((a, ai))
                } else {
                    Some((a, ai && bi))
                }
            }
        })
    }

    fn merge_fast_upper_bound(
        existing: Option<(i64, bool)>,
        incoming: Option<(i64, bool)>,
    ) -> Option<Option<(i64, bool)>> {
        Some(match (existing, incoming) {
            (None, bound) | (bound, None) => bound,
            (Some((a, ai)), Some((b, bi))) => {
                if b < a {
                    Some((b, bi))
                } else if a < b {
                    Some((a, ai))
                } else {
                    Some((a, ai && bi))
                }
            }
        })
    }

    fn fast_split_table_name(s: &str) -> Option<(&str, &str)> {
        let s = s.trim_start();
        if s.is_empty() {
            return None;
        }
        if let Some(rest) = s.strip_prefix('"') {
            let end = rest.find('"')?;
            let table = rest.get(..end)?;
            let after = rest.get(end + 1..)?.trim_start();
            return Some((table, after));
        }
        let end = s.find(|c: char| c.is_whitespace() || c == ';').unwrap_or(s.len());
        let table = s.get(..end)?;
        if table.is_empty() {
            return None;
        }
        Some((table, s.get(end..)?.trim_start()))
    }

    fn fast_split_and_terms(mut s: &str) -> Option<Vec<&str>> {
        let mut terms = Vec::new();
        loop {
            let Some(and_idx) = Self::find_sql_keyword(s, b"AND") else {
                let term = s.trim();
                if term.is_empty() {
                    return None;
                }
                terms.push(term);
                return Some(terms);
            };
            let term = s.get(..and_idx)?.trim();
            if term.is_empty() {
                return None;
            }
            terms.push(term);
            s = s.get(and_idx + 3..)?.trim_start();
        }
    }

    fn fast_split_comma_terms(mut s: &str) -> Option<Vec<&str>> {
        let mut terms = Vec::new();
        loop {
            let idx = Self::find_top_level_comma(s);
            let (term, rest) = match idx {
                Some(idx) => (s.get(..idx)?.trim(), Some(s.get(idx + 1..)?)),
                None => (s.trim(), None),
            };
            if term.is_empty() {
                return None;
            }
            terms.push(term);
            match rest {
                Some(rest) => s = rest,
                None => return Some(terms),
            }
        }
    }

    fn find_top_level_comma(s: &str) -> Option<usize> {
        let bytes = s.as_bytes();
        let mut in_string = false;
        let mut i = 0;
        while i < bytes.len() {
            let b = bytes[i];
            if in_string {
                if b == b'\'' {
                    if i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                        i += 2;
                        continue;
                    }
                    in_string = false;
                }
            } else if b == b'\'' {
                in_string = true;
            } else if b == b',' {
                return Some(i);
            }
            i += 1;
        }
        None
    }

    fn try_direct_projected_filtered_scan(&self, plan: &sql::LogicalPlan) -> Option<Result<Vec<Tuple>>> {
        if self.in_transaction() || self.tenant_manager.get_current_context().is_some() {
            return None;
        }

        let sql::LogicalPlan::FilteredScan {
            table_name,
            alias,
            schema: _plan_schema,
            projection: Some(projection),
            predicate: Some(predicate),
            as_of: None,
        } = plan
        else {
            return None;
        };

        if alias.is_some() || projection.is_empty() || self.tenant_manager.should_apply_rls(table_name, "SELECT") {
            return None;
        }

        if !Self::direct_projected_filter_expr_supported(predicate) {
            return None;
        }

        let catalog = self.storage.catalog();
        let schema = match catalog.get_table_schema(table_name) {
            Ok(schema) => schema,
            Err(_) => return None,
        };
        match self.storage.mv_catalog().view_exists(table_name) {
            Ok(true) | Err(_) => return None,
            Ok(false) => {}
        }

        let analyzed_predicates = self.storage.predicate_pushdown().analyze_predicate(predicate, &schema, &[]);
        if analyzed_predicates.len() != 1
            || !crate::sql::executor::scan::storage_predicates_are_sql_safe(&schema, &analyzed_predicates)
        {
            return None;
        }

        match self.storage.scan_table_with_schema_projected_filtered(
            table_name,
            &schema,
            projection,
            &analyzed_predicates,
        ) {
            Ok(Some(rows)) => Some(Ok(rows)),
            Ok(None) => None,
            Err(e) => Some(Err(e)),
        }
    }

    fn direct_projected_filter_expr_supported(expr: &sql::LogicalExpr) -> bool {
        let sql::LogicalExpr::BinaryExpr { left, op, right } = expr else {
            return false;
        };
        matches!(
            op,
            sql::BinaryOperator::Eq
                | sql::BinaryOperator::Lt
                | sql::BinaryOperator::LtEq
                | sql::BinaryOperator::Gt
                | sql::BinaryOperator::GtEq
        ) && matches!(left.as_ref(), sql::LogicalExpr::Column { .. })
            && matches!(
                right.as_ref(),
                sql::LogicalExpr::Literal(value) if !matches!(value, Value::Null)
            )
    }

    fn try_fast_select_params(&self, sql: &str, params: &[Value]) -> Option<Result<Vec<Tuple>>> {
        if self.in_transaction() {
            return None;
        }

        let trimmed = sql.trim();
        if trimmed.len() < 20 || !trimmed.as_bytes().get(..6)?.eq_ignore_ascii_case(b"SELECT") {
            return None;
        }

        let after_select = trimmed.get(6..)?.trim_start();
        if !after_select.starts_with('*') {
            return None;
        }
        let after_star = after_select.get(1..)?.trim_start();
        if after_star.len() < 4 || !after_star.as_bytes().get(..4)?.eq_ignore_ascii_case(b"FROM") {
            return None;
        }
        let after_from = after_star.get(4..)?.trim_start();
        let table_end = after_from.find(|c: char| c.is_whitespace())?;
        let table_name = after_from.get(..table_end)?.trim().trim_matches('"');
        if table_name.is_empty() {
            return None;
        }

        let rest = after_from.get(table_end..)?.trim_start();
        if rest.len() < 5 || !rest.as_bytes().get(..5)?.eq_ignore_ascii_case(b"WHERE") {
            return None;
        }
        let where_clause = rest.get(5..)?.trim_start();
        let simple_where_clause = where_clause.strip_suffix(';').unwrap_or(where_clause).trim();
        if let Some(eq_pos) = simple_where_clause.find('=') {
            let pk_col = simple_where_clause.get(..eq_pos)?.trim().trim_matches('"');
            let pk_val_str = simple_where_clause.get(eq_pos + 1..)?.trim();
            if !pk_col.is_empty() && !pk_val_str.is_empty() {
                let spec = match self.fast_select_spec(table_name, pk_col)? {
                    Ok(spec) => spec,
                    Err(e) => return Some(Err(e)),
                };
                let pk_value = match Self::fast_param_or_literal_value(pk_val_str, params, &spec.pk_data_type) {
                    Some(Ok(value)) => value,
                    Some(Err(e)) => return Some(Err(e)),
                    None => return None,
                };
                return match self
                    .storage
                    .get_row_by_typed_pk_with_schema(&spec.table_name, &pk_value, &spec.schema)
                {
                    Ok(Some(row)) => Some(Ok(vec![row])),
                    Ok(None) => Some(Ok(vec![])),
                    Err(e) => Some(Err(e)),
                };
            }
        }
        // Word-boundary + literal-aware (R1.2); see fast_select_lookup.
        if Self::contains_sql_keyword(where_clause, b"AND")
            || Self::contains_sql_keyword(where_clause, b"OR")
            || Self::contains_sql_keyword(where_clause, b"JOIN")
            || Self::contains_sql_keyword(where_clause, b"ORDER")
            || Self::contains_sql_keyword(where_clause, b"GROUP")
            || Self::contains_sql_keyword(where_clause, b"LIMIT")
        {
            return None;
        }

        let where_clause = where_clause.strip_suffix(';').unwrap_or(where_clause).trim();
        let eq_pos = where_clause.find('=')?;
        let pk_col = where_clause.get(..eq_pos)?.trim().trim_matches('"');
        let pk_val_str = where_clause.get(eq_pos + 1..)?.trim();
        if pk_col.is_empty() || pk_val_str.is_empty() {
            return None;
        }
        let spec = match self.fast_select_spec(table_name, pk_col)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };

        let pk_value = match Self::fast_param_or_literal_value(pk_val_str, params, &spec.pk_data_type) {
            Some(Ok(value)) => value,
            Some(Err(e)) => return Some(Err(e)),
            None => return None,
        };

        match self
            .storage
            .get_row_by_typed_pk_with_schema(&spec.table_name, &pk_value, &spec.schema)
        {
            Ok(Some(row)) => Some(Ok(vec![row])),
            Ok(None) => Some(Ok(vec![])),
            Err(e) => Some(Err(e)),
        }
    }

    fn fast_param_or_literal_value(token: &str, params: &[Value], target_type: &DataType) -> Option<Result<Value>> {
        let token = Self::strip_fast_postgres_type_cast(token.trim());
        if let Some(index_str) = token.strip_prefix('$') {
            if !index_str.bytes().all(|b| b.is_ascii_digit()) {
                return None;
            }
            let index = match index_str.parse::<usize>() {
                Ok(index) if index > 0 => index,
                Ok(_) => {
                    return Some(Err(Error::query_execution(
                        "Parameter indices must be 1-based (e.g., $1, $2)",
                    )))
                }
                Err(_) => {
                    return Some(Err(Error::query_execution(format!(
                        "Invalid parameter placeholder: {token}. Expected format: $1, $2, etc."
                    ))))
                }
            };
            let mut value = match params.get(index - 1) {
                Some(value) => value.clone(),
                None => {
                    return Some(Err(Error::query_execution(format!(
                        "Parameter ${} not provided. Expected {} parameters, got {}",
                        index,
                        index,
                        params.len()
                    ))))
                }
            };
            if Self::insert_value_needs_cast(&value, target_type) {
                value = match Self::fast_cast_value(value, target_type) {
                    Ok(value) => value,
                    Err(e) => return Some(Err(e)),
                };
            }
            return Some(Ok(value));
        }

        // The literal must consume the whole token — trailing text means an
        // unparsed construct; fall back to the planner.
        let (value, rest) = Self::fast_parse_one_value(token, target_type)?;
        if !rest.trim().is_empty() {
            return None;
        }
        Some(Ok(value))
    }

    fn strip_fast_postgres_type_cast(token: &str) -> &str {
        let Some(cast_pos) = token.find("::") else {
            return token;
        };
        let suffix = token.get(cast_pos + 2..).unwrap_or_default().trim();
        if suffix.is_empty() {
            return token;
        }
        if suffix
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'.')
        {
            token.get(..cast_pos).unwrap_or(token).trim_end()
        } else {
            token
        }
    }

    /// Evaluate simple expressions like `col + 0.01`, `col - 5`, `col * 2`, `col || 'suffix'`
    /// Returns None for anything more complex.
    fn fast_eval_simple_expr(expr: &str, col_name: &str, col_idx: usize, row: &Tuple) -> Option<Value> {
        let expr = expr.trim();

        // Check for pattern: col_name <op> literal
        // The column name must appear at the start
        if !expr.starts_with(col_name) {
            return None;
        }
        let after_col = expr.get(col_name.len()..)?.trim_start();
        if after_col.is_empty() {
            return None;
        }

        // Get current value from the row
        let current = row.values.get(col_idx)?;

        // Determine operator
        let (op, operand_str) = if let Some(rest) = after_col.strip_prefix('+') {
            ('+', rest.trim())
        } else if let Some(rest) = after_col.strip_prefix('-') {
            ('-', rest.trim())
        } else if let Some(rest) = after_col.strip_prefix('*') {
            ('*', rest.trim())
        } else {
            return None;
        };

        // Parse the operand as a number
        match (current, op) {
            (Value::Int2(v), '+') => {
                let n: i16 = operand_str.parse().ok()?;
                Some(Value::Int2(v.checked_add(n)?))
            }
            (Value::Int2(v), '-') => {
                let n: i16 = operand_str.parse().ok()?;
                Some(Value::Int2(v.checked_sub(n)?))
            }
            (Value::Int2(v), '*') => {
                let n: i16 = operand_str.parse().ok()?;
                Some(Value::Int2(v.checked_mul(n)?))
            }
            (Value::Int4(v), '+') => {
                let n: i32 = operand_str.parse().ok()?;
                Some(Value::Int4(v.checked_add(n)?))
            }
            (Value::Int4(v), '-') => {
                let n: i32 = operand_str.parse().ok()?;
                Some(Value::Int4(v.checked_sub(n)?))
            }
            (Value::Int4(v), '*') => {
                let n: i32 = operand_str.parse().ok()?;
                Some(Value::Int4(v.checked_mul(n)?))
            }
            (Value::Int8(v), '+') => {
                let n: i64 = operand_str.parse().ok()?;
                Some(Value::Int8(v.checked_add(n)?))
            }
            (Value::Int8(v), '-') => {
                let n: i64 = operand_str.parse().ok()?;
                Some(Value::Int8(v.checked_sub(n)?))
            }
            (Value::Int8(v), '*') => {
                let n: i64 = operand_str.parse().ok()?;
                Some(Value::Int8(v.checked_mul(n)?))
            }
            (Value::Float4(v), '+') => {
                let n: f32 = operand_str.parse().ok()?;
                Some(Value::Float4(v + n))
            }
            (Value::Float4(v), '-') => {
                let n: f32 = operand_str.parse().ok()?;
                Some(Value::Float4(v - n))
            }
            (Value::Float4(v), '*') => {
                let n: f32 = operand_str.parse().ok()?;
                Some(Value::Float4(v * n))
            }
            (Value::Float8(v), '+') => {
                let n: f64 = operand_str.parse().ok()?;
                Some(Value::Float8(v + n))
            }
            (Value::Float8(v), '-') => {
                let n: f64 = operand_str.parse().ok()?;
                Some(Value::Float8(v - n))
            }
            (Value::Float8(v), '*') => {
                let n: f64 = operand_str.parse().ok()?;
                Some(Value::Float8(v * n))
            }
            _ => None,
        }
    }

    /// Find the closing ')' in a string, respecting single-quoted strings
    #[allow(clippy::indexing_slicing)] // Safety: all accesses guarded by `i < bytes.len()`
    fn find_closing_paren(s: &str) -> Option<usize> {
        let mut in_string = false;
        let bytes = s.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            let b = bytes[i];
            if in_string {
                if b == b'\'' {
                    // Check for escaped quote ''
                    if i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                        i += 2;
                        continue;
                    }
                    in_string = false;
                }
            } else if b == b'\'' {
                in_string = true;
            } else if b == b')' {
                return Some(i);
            }
            i += 1;
        }
        None
    }

    /// Quick count of comma-separated values (respecting quoted strings)
    #[allow(clippy::indexing_slicing)] // Safety: all accesses guarded by `i < bytes.len()`
    fn fast_parse_value_count(s: &str) -> usize {
        if s.trim().is_empty() {
            return 0;
        }
        let mut count = 1;
        let mut in_string = false;
        let bytes = s.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            let b = bytes[i];
            if in_string {
                if b == b'\'' {
                    if i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                        i += 2;
                        continue;
                    }
                    in_string = false;
                }
            } else if b == b'\'' {
                in_string = true;
            } else if b == b',' {
                count += 1;
            }
            i += 1;
        }
        count
    }

    fn contains_ascii_case_insensitive(haystack: &str, needle: &[u8]) -> bool {
        !needle.is_empty()
            && haystack
                .as_bytes()
                .windows(needle.len())
                .any(|window| window.eq_ignore_ascii_case(needle))
    }

    /// True when `byte` can be part of a SQL identifier (`[A-Za-z0-9_$]`).
    #[inline]
    fn is_sql_ident_byte(byte: u8) -> bool {
        byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'$'
    }

    /// Word-boundary, literal-aware SQL keyword search (R1.2).
    ///
    /// Returns the byte offset of the first occurrence of `keyword` in
    /// `haystack` that is:
    /// - OUTSIDE single-quoted string literals (doubled `''` escapes are
    ///   handled, so `'it''s'` is one literal), and
    /// - delimited by non-identifier characters on both sides (identifier
    ///   characters are `[A-Za-z0-9_$]`), so `points` does not match `IN`
    ///   and `order_id` does not match `OR`.
    ///
    /// Deliberate, conservative design choices:
    /// - Double-quoted identifiers are scanned as plain text: a quoted
    ///   identifier like `"my select"` still counts as containing `SELECT`.
    ///   A false positive here only costs performance (the statement takes
    ///   the full parse/plan path); it can never produce wrong results.
    /// - An unterminated single-quoted literal swallows the rest of the
    ///   haystack. The structural fast parsers reject unterminated literals
    ///   anyway, so nothing incorrect can slip through.
    /// - Multi-word needles (e.g. `ON CONFLICT`) match only the exact
    ///   single-space spelling, like the previous raw substring check;
    ///   other spellings are rejected structurally by the fast parsers.
    ///
    /// Allocation-free single pass.
    #[allow(clippy::indexing_slicing)] // Safety: all accesses guarded by `i < bytes.len()`
    fn find_sql_keyword(haystack: &str, keyword: &[u8]) -> Option<usize> {
        if keyword.is_empty() {
            return None;
        }
        let bytes = haystack.as_bytes();
        let klen = keyword.len();
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == b'\'' {
                // Skip the single-quoted literal, honoring '' escapes.
                i += 1;
                while i < bytes.len() {
                    if bytes[i] == b'\'' {
                        if i + 1 < bytes.len() && bytes[i + 1] == b'\'' {
                            i += 2; // escaped quote — still inside the literal
                            continue;
                        }
                        i += 1; // closing quote
                        break;
                    }
                    i += 1;
                }
                continue;
            }
            if i + klen <= bytes.len()
                && bytes[i..i + klen].eq_ignore_ascii_case(keyword)
                && (i == 0 || !Self::is_sql_ident_byte(bytes[i - 1]))
                && (i + klen == bytes.len() || !Self::is_sql_ident_byte(bytes[i + klen]))
            {
                return Some(i);
            }
            i += 1;
        }
        None
    }

    /// True when `keyword` appears in `haystack` as a standalone word outside
    /// single-quoted string literals. See [`Self::find_sql_keyword`] for the
    /// exact boundary/escape semantics. Used by the fast-path eligibility
    /// checks so identifiers like `points` (contains `IN`) or literals like
    /// `'please select me'` no longer knock statements off the parse-skipping
    /// fast paths (R1.2).
    fn contains_sql_keyword(haystack: &str, keyword: &[u8]) -> bool {
        Self::find_sql_keyword(haystack, keyword).is_some()
    }

    /// Parse one or more VALUES groups from a simple INSERT statement.
    ///
    /// Returns the contents inside each parenthesized group. Anything after the
    /// groups other than an optional semicolon causes the caller to fall back to
    /// the normal parser.
    #[allow(clippy::indexing_slicing)] // validated by get()/prefix checks
    fn fast_parse_value_groups(mut remaining: &str) -> Option<Vec<&str>> {
        let mut groups = Vec::new();

        loop {
            remaining = remaining.trim_start();
            if remaining.is_empty() {
                break;
            }
            if remaining == ";" {
                break;
            }
            if !remaining.starts_with('(') {
                return None;
            }

            let inner = remaining.get(1..)?;
            let close_idx = Self::find_closing_paren(inner)?;
            groups.push(inner.get(..close_idx)?);
            remaining = inner.get(close_idx + 1..)?.trim_start();

            if remaining.is_empty() || remaining == ";" {
                break;
            }
            if remaining.starts_with(',') {
                remaining = remaining.get(1..)?;
                continue;
            }
            return None;
        }

        if groups.is_empty() {
            None
        } else {
            Some(groups)
        }
    }

    /// Parse a single literal value, returning (Value, remaining_str)
    #[allow(clippy::indexing_slicing)] // Safety: all byte accesses guarded by `end < bytes.len()`
    fn fast_parse_one_value<'a>(s: &'a str, target_type: &DataType) -> Option<(Value, &'a str)> {
        let s = s.trim_start();
        if s.is_empty() {
            return None;
        }

        let first = s.as_bytes().first()?;

        // String literal: 'value'
        if *first == b'\'' {
            // Reject string literals for numeric/boolean target types — bail to
            // the normal parser which will produce a proper type mismatch error
            match target_type {
                DataType::Int2
                | DataType::Int4
                | DataType::Int8
                | DataType::Float4
                | DataType::Float8
                | DataType::Boolean => return None,
                _ => {}
            }

            let inner = s.get(1..)?;
            if let Some(end) = inner.find('\'') {
                let rest = inner.get(end + 1..)?;
                if !rest.starts_with('\'') {
                    let result = inner.get(..end)?.to_string();
                    return Some((Self::fast_string_literal_value(result, target_type), rest));
                }
            }

            let mut end = 0;
            let bytes = inner.as_bytes();
            let mut result = String::new();
            let mut seg_start = 0; // start of current non-quote segment
            while end < bytes.len() {
                if bytes[end] == b'\'' {
                    // Flush the segment before this quote as a UTF-8 slice
                    if seg_start < end {
                        result.push_str(inner.get(seg_start..end)?);
                    }
                    if end + 1 < bytes.len() && bytes[end + 1] == b'\'' {
                        result.push('\'');
                        end += 2;
                        seg_start = end;
                        continue;
                    }
                    // End of string
                    let rest = inner.get(end + 1..)?;
                    // Coerce string literal to target type when the
                    // column is non-textual.  Without this the
                    // fast-select PK lookup compares
                    // Value::String("<uuid>") against the stored
                    // Value::Uuid(...) and misses every time —
                    // root cause of the CloudV2 admin_db
                    // persistence bug (#205).
                    return Some((Self::fast_string_literal_value(result, target_type), rest));
                }
                end += 1;
            }
            return None; // Unterminated string
        }

        // NULL
        if s.len() >= 4 && s.as_bytes().get(..4)?.eq_ignore_ascii_case(b"NULL") {
            let rest = s.get(4..)?;
            // Make sure NULL isn't part of a longer identifier
            if rest.is_empty() || rest.starts_with(',') || rest.starts_with(')') || rest.starts_with(' ') {
                return Some((Value::Null, rest));
            }
        }

        // Boolean: true/false
        if s.len() >= 4 && s.as_bytes().get(..4)?.eq_ignore_ascii_case(b"TRUE") {
            let rest = s.get(4..)?;
            if rest.is_empty() || rest.starts_with(',') || rest.starts_with(')') || rest.starts_with(' ') {
                return Some((Value::Boolean(true), rest));
            }
        }
        if s.len() >= 5 && s.as_bytes().get(..5)?.eq_ignore_ascii_case(b"FALSE") {
            let rest = s.get(5..)?;
            if rest.is_empty() || rest.starts_with(',') || rest.starts_with(')') || rest.starts_with(' ') {
                return Some((Value::Boolean(false), rest));
            }
        }

        // Number: integer or float (possibly negative)
        if first.is_ascii_digit() || *first == b'-' || *first == b'+' || *first == b'.' {
            let end = s.find([',', ')', ' ']).unwrap_or(s.len());
            let num_str = s.get(..end)?.trim();
            let rest = s.get(end..)?;

            // Parse based on target type
            let value = match target_type {
                DataType::Int2 => {
                    let n: i16 = num_str.parse().ok()?;
                    Value::Int2(n)
                }
                DataType::Int4 => {
                    let n: i32 = num_str.parse().ok()?;
                    Value::Int4(n)
                }
                DataType::Int8 => {
                    let n: i64 = num_str.parse().ok()?;
                    Value::Int8(n)
                }
                DataType::Float4 => {
                    let f: f32 = num_str.parse().ok()?;
                    Value::Float4(f)
                }
                DataType::Float8 => {
                    let f: f64 = num_str.parse().ok()?;
                    Value::Float8(f)
                }
                DataType::Numeric => {
                    // NUMERIC/DECIMAL values are stored and ART-key-encoded as
                    // their string form (ArtIndexManager::encode_value_into ->
                    // Value::Numeric uses the raw bytes of the decimal string).
                    // Parsing the literal as Int8/Float8 here produced a key
                    // (8-byte sign-flipped int / IEEE float) that never matched
                    // the stored Numeric("6") key (the bytes of "6"), so the PK
                    // fast-path for DELETE/UPDATE/SELECT silently matched 0 rows
                    // on a DECIMAL PK while the full-scan path matched 1. Keep
                    // the canonical string form, after validating it is numeric.
                    if num_str.parse::<i64>().is_ok() || num_str.parse::<f64>().is_ok() {
                        Value::Numeric(num_str.to_string())
                    } else {
                        return None;
                    }
                }
                _ => {
                    // For INTEGER (which maps to Int4), try int
                    if num_str.contains('.') {
                        let f: f64 = num_str.parse().ok()?;
                        Value::Float8(f)
                    } else if let Ok(n) = num_str.parse::<i32>() {
                        Value::Int4(n)
                    } else if let Ok(n) = num_str.parse::<i64>() {
                        Value::Int8(n)
                    } else {
                        return None;
                    }
                }
            };
            return Some((value, rest));
        }

        // Not a recognized literal — bail to normal parser
        None
    }

    fn fast_string_literal_value(result: String, target_type: &DataType) -> Value {
        match target_type {
            DataType::Uuid => uuid::Uuid::parse_str(&result)
                .map(Value::Uuid)
                .unwrap_or(Value::String(result)),
            DataType::Date => result
                .parse::<chrono::NaiveDate>()
                .map(Value::Date)
                .unwrap_or(Value::String(result)),
            DataType::Timestamp => chrono::DateTime::parse_from_rfc3339(&result)
                .map(|t| Value::Timestamp(t.to_utc()))
                .unwrap_or(Value::String(result)),
            _ => Value::String(result),
        }
    }

    /// Largest SQL text (bytes) the parse cache will key on. COPY renders each
    /// chunk into a ~25KB multi-row `INSERT … VALUES (…),(…)…` string with a
    /// unique key that can never hit; caching it deep-clones a 500-row AST and
    /// evicts genuinely hot entries. Real reusable statements are far smaller.
    const PARSE_CACHE_MAX_SQL_LEN: usize = 4096;

    /// Parse SQL with caching. Returns (statement, was_cached).
    pub(crate) fn parse_cached(&self, sql: &str) -> Result<(sqlparser::ast::Statement, bool)> {
        // Check parse cache first
        if let Some(stmt) = self.parse_cache.get(sql) {
            return Ok((stmt, true));
        }
        // Cache miss — parse, and cache unless the text is too large to be a
        // reusable statement (B3: stops COPY/bulk-INSERT parse-cache pollution).
        let parser = sql::Parser::new();
        let statement = parser.parse_one(sql)?;
        if sql.len() <= Self::PARSE_CACHE_MAX_SQL_LEN {
            self.parse_cache.put(sql.to_string(), statement.clone());
        }
        Ok((statement, false))
    }

    /// Resolve a trigger function's body into a BEFORE-row NEW-mutation recipe
    /// for the `NEW.<col> = <expr>; … RETURN NEW|NULL` pattern. Returns `None`
    /// when the function is unknown or its body has no recognised effect.
    fn build_trigger_row_mutation(
        &self,
        function_name: &str,
        events: &[sql::logical_plan::TriggerEvent],
    ) -> Option<sql::triggers::TriggerRowMutation> {
        let func = self.function_registry.get_function(function_name)?;
        let (assigns, returns_null) = Self::parse_trigger_assignments(&func.body);
        if assigns.is_empty() && !returns_null {
            return None;
        }
        let mut assignments = Vec::new();
        for (col, rhs) in &assigns {
            // Convert each RHS independently so one unsupported expression
            // doesn't drop the others. Conversion goes straight through
            // `expr_to_logical` (not full SELECT planning) so `NEW.col` /
            // `OLD.col` references survive — they're resolved against the row
            // context when the trigger fires.
            if let Ok(expr) = self.rhs_to_logical_expr(rhs) {
                assignments.push((col.clone(), expr));
            }
        }
        if assignments.is_empty() && !returns_null {
            return None;
        }
        Some(sql::triggers::TriggerRowMutation {
            events: events.to_vec(),
            assignments,
            returns_null,
        })
    }

    /// Parse a PL/pgSQL trigger body for `NEW.<col> = <expr>` assignments and a
    /// `RETURN NULL` (skip-row) marker. Best effort: statements it doesn't
    /// recognise are ignored.
    fn parse_trigger_assignments(body: &str) -> (Vec<(String, String)>, bool) {
        // Narrow to the BEGIN … END block when present.
        let inner = {
            let upper = body.to_ascii_uppercase();
            let start = upper.find("BEGIN").map(|i| i + "BEGIN".len()).unwrap_or(0);
            let end = upper.rfind("END").unwrap_or(body.len());
            if start <= end && end <= body.len() {
                &body[start..end]
            } else {
                body
            }
        };

        let mut assignments = Vec::new();
        let mut returns_null = false;
        for raw in inner.split(';') {
            let stmt = raw.trim();
            if stmt.is_empty() {
                continue;
            }
            let upper = stmt.to_ascii_uppercase();
            if upper.starts_with("RETURN") {
                if upper.contains("NULL") {
                    returns_null = true;
                }
                continue;
            }
            // NEW.<col> [:]= <rhs>
            if upper.starts_with("NEW.") {
                let after = &stmt[4..]; // after "NEW."
                if let Some(eq) = after.find('=') {
                    let col = after[..eq].trim();
                    // tolerate ':=' assignment
                    let col = col.strip_suffix(':').unwrap_or(col).trim();
                    let rhs = after[eq + 1..].trim();
                    if !col.is_empty() && !rhs.is_empty() {
                        assignments.push((col.to_string(), rhs.to_string()));
                    }
                }
            }
        }
        (assignments, returns_null)
    }

    /// Convert a single scalar RHS expression (e.g. `NOW()`, `NEW.a + 1`) to a
    /// logical expression via `expr_to_logical`, deferring column resolution so
    /// `NEW.`/`OLD.` references are kept for the trigger evaluator.
    fn rhs_to_logical_expr(&self, rhs: &str) -> Result<sql::logical_plan::LogicalExpr> {
        let parser = sql::Parser::new();
        let statement = parser.parse_one(&format!("SELECT {rhs}"))?;
        let expr = match statement {
            sqlparser::ast::Statement::Query(query) => match *query.body {
                sqlparser::ast::SetExpr::Select(select) => match select.projection.into_iter().next() {
                    Some(sqlparser::ast::SelectItem::UnnamedExpr(e)) => e,
                    Some(sqlparser::ast::SelectItem::ExprWithAlias { expr, .. }) => expr,
                    _ => return Err(Error::query_execution("unsupported trigger RHS".to_string())),
                },
                _ => return Err(Error::query_execution("unsupported trigger RHS".to_string())),
            },
            _ => return Err(Error::query_execution("unsupported trigger RHS".to_string())),
        };
        let catalog = self.storage.catalog();
        let planner = sql::Planner::with_catalog(&catalog);
        planner.expr_to_logical(&expr)
    }

    /// Parse and plan a parameterized statement with a cache key that cannot
    /// collide with the non-parameterized `query()` plan cache entries.
    fn parameterized_plan_cached(&self, sql: &str) -> Result<std::sync::Arc<sql::LogicalPlan>> {
        let cache_key = format!("\0params\0{sql}");
        if let Some(plan) = self.plan_cache.get(&cache_key) {
            return Ok(plan);
        }

        let (statement, _) = self.parse_cached(sql)?;
        let catalog = self.storage.catalog();
        let planner = sql::Planner::with_catalog(&catalog).with_sql(sql.to_string());
        let plan = std::sync::Arc::new(planner.statement_to_plan(statement)?);
        self.plan_cache.put(cache_key, std::sync::Arc::clone(&plan));
        Ok(plan)
    }

    /// Plan-cache invalidation epoch — wire handlers pin `Arc<LogicalPlan>`s
    /// in prepared statements (R5.W2) and use this to detect that DDL
    /// cleared the plan cache since the plan was captured.
    pub(crate) fn wire_plan_epoch(&self) -> u64 {
        self.plan_cache.epoch()
    }

    /// Fetch (or build) the parameterized plan for `sql` together with the
    /// plan-cache epoch observed *before* the fetch — the pair a prepared
    /// statement needs to pin the plan and later detect invalidation.
    /// The plan is exactly `parameterized_plan_cached` output: no extra
    /// optimizer passes run here (R5.W3 is explicitly out of scope; the
    /// 3.37.3 index-probe behavior must not be bypassed).
    pub(crate) fn wire_parameterized_plan(&self, sql: &str) -> Result<(std::sync::Arc<sql::LogicalPlan>, u64)> {
        let epoch = self.plan_cache.epoch();
        let plan = self.parameterized_plan_cached(sql)?;
        Ok((plan, epoch))
    }

    /// Internal execute method without transaction management
    fn execute_internal(&self, sql: &str) -> Result<u64> {
        // 1. Record query for quota tracking (QPS enforcement)
        if let Some(context) = self.tenant_manager.get_current_context() {
            self.tenant_manager
                .record_query(context.tenant_id)
                .map_err(|e| Error::query_execution(format!("Quota exceeded: {}", e)))?;
        }

        // 2. Parse SQL (with cache)
        let parse_start = std::time::Instant::now();
        let (statement, parse_cached) = self.parse_cached(sql)?;
        let parse_elapsed = parse_start.elapsed();
        if parse_cached {
            tracing::debug!(
                phase = "parse",
                duration_us = parse_elapsed.as_micros() as u64,
                "SQL parsed (AST cached)"
            );
        } else {
            tracing::debug!(
                phase = "parse",
                duration_us = parse_elapsed.as_micros() as u64,
                "SQL parsed"
            );
        }

        // 3. Create logical plan with catalog access
        let plan_start = std::time::Instant::now();
        let catalog = self.storage.catalog();
        let planner = sql::Planner::with_catalog(&catalog);
        let plan = planner.statement_to_plan(statement)?;
        let plan_elapsed = plan_start.elapsed();
        tracing::debug!(
            phase = "plan",
            duration_us = plan_elapsed.as_micros() as u64,
            "Logical plan created"
        );

        // Invalidate SQL metadata caches on DDL operations that can alter schemas,
        // constraints, indexes, triggers, or materialized-view shape.
        if Self::plan_invalidates_sql_caches(&plan) {
            self.invalidate_plan_cache();
        }

        // 3. Execute plan based on type
        match &plan {
            sql::LogicalPlan::CreateTable {
                name,
                columns,
                if_not_exists,
                ..
            } => {
                // Handle IF NOT EXISTS: silently succeed when table already exists
                if *if_not_exists && self.storage.catalog().table_exists(name).unwrap_or(false) {
                    return Ok(0);
                }

                // Convert ColumnDef to Column
                let schema_columns: Vec<Column> = columns
                    .iter()
                    .map(|col_def| {
                        Column {
                            name: col_def.name.clone(),
                            data_type: col_def.data_type.clone(),
                            nullable: !col_def.not_null, // nullable is opposite of not_null
                            primary_key: col_def.primary_key,
                            source_table: None,
                            source_table_name: None,
                            default_expr: None,
                            unique: false,
                            storage_mode: col_def.storage_mode,
                        }
                    })
                    .collect();

                let schema = Schema::new(schema_columns);
                let catalog = self.storage.catalog();

                // Log to WAL for replication before creating (schema will be moved)
                if let Err(e) = self.storage.log_create_table(name, &schema) {
                    tracing::warn!("Failed to log CREATE TABLE to WAL: {}", e);
                }

                catalog.create_table(name, schema)?;
                Ok(1) // 1 table created
            }
            sql::LogicalPlan::Insert {
                table_name,
                columns,
                values,
                returning,
                on_conflict: _,
            } => {
                // Check for RLS enforcement (with_check_expr)
                let rls_enforced = self.tenant_manager.should_apply_rls(table_name, "INSERT");
                let rls_check = if rls_enforced {
                    self.tenant_manager.get_rls_conditions(table_name, "INSERT")
                } else {
                    None
                };

                // Get table schema for column types
                let catalog = self.storage.catalog();
                let schema = catalog.get_table_schema(table_name)?;

                // Create evaluator with schema for expression evaluation
                // Use empty tuple for evaluation context since INSERT values are constants
                let evaluator = sql::Evaluator::new(std::sync::Arc::new(Schema {
                    columns: vec![], // Empty schema - INSERT values don't reference columns
                }));
                let empty_tuple = Tuple::new(vec![]);

                let mut count = 0;
                for value_row in values {
                    // Evaluate each expression to get actual values
                    // This handles literals, CAST expressions, and more
                    let mut tuple_values: Vec<Value> = Vec::new();

                    for (col_idx, expr) in value_row.iter().enumerate() {
                        // Determine target column type for auto-casting
                        let target_col_idx = if let Some(ref cols) = columns {
                            // Explicit column list - find index
                            let col_name = cols
                                .get(col_idx)
                                .ok_or_else(|| Error::internal("column index out of bounds"))?;
                            schema
                                .get_column_index(col_name)
                                .ok_or_else(|| Error::query_execution(format!("Column '{}' not found", col_name)))?
                        } else {
                            // No column list - use position
                            col_idx
                        };

                        let target_col = schema.get_column_at(target_col_idx).ok_or_else(|| {
                            Error::query_execution(format!(
                                "Too many values for INSERT: table has {} columns",
                                schema.columns.len()
                            ))
                        })?;

                        let target_type = &target_col.data_type;

                        // Evaluate expression
                        let mut value = evaluator.evaluate(expr, &empty_tuple)?;

                        // Auto-cast if value type doesn't match column type
                        let needs_cast = match (&value, target_type) {
                            (Value::Null, _) => false, // NULL is compatible with any type
                            (Value::Vector(_), DataType::Vector(_)) => true,
                            (Value::String(_), DataType::Vector(_)) => true, // Always cast strings to vectors
                            (Value::String(_), DataType::Json | DataType::Jsonb) => true, // Always cast strings to JSON
                            (Value::Int4(_), DataType::Int4) => false,
                            (Value::Int8(_), DataType::Int8) => false,
                            (Value::Float4(_), DataType::Float4) => false,
                            (Value::Float8(_), DataType::Float8) => false,
                            (Value::String(_), DataType::Text | DataType::Varchar(_)) => false,
                            (Value::Boolean(_), DataType::Boolean) => false,
                            (Value::Json(_), DataType::Json | DataType::Jsonb) => false,
                            _ => true, // Type mismatch - needs cast
                        };

                        if needs_cast {
                            value = evaluator.cast_value(value, target_type)?;
                        }

                        tuple_values.push(value);
                    }

                    let tuple = Tuple::new(tuple_values);

                    // Validate RLS with_check_expr if present
                    if let Some((_, with_check)) = &rls_check {
                        if let Some(ref with_check_expr) = with_check {
                            // Evaluate RLS with_check expression to ensure inserted row satisfies policy
                            let tenant_context = self.tenant_manager.get_current_context();
                            let rls_evaluator = tenant::RLSExpressionEvaluator::new(
                                std::sync::Arc::new(schema.clone()),
                                tenant_context,
                            );
                            let expr = rls_evaluator.parse(with_check_expr)?;
                            let satisfies_policy = rls_evaluator.evaluate(&expr, &tuple)?;

                            if !satisfies_policy {
                                return Err(Error::query_execution(format!(
                                    "Row-Level Security policy violation: inserted row does not satisfy WITH CHECK expression"
                                )));
                            }
                        }
                    }

                    self.storage
                        .insert_tuple_branch_aware_with_schema(table_name, tuple, &schema)?;
                    count += 1;
                }
                Ok(count)
            }
            sql::LogicalPlan::InsertSelect {
                table_name,
                columns,
                source,
                returning: _,
            } => {
                // Execute source SELECT plan to get rows
                let mut executor =
                    sql::Executor::with_storage(&self.storage).with_timeout(self.effective_statement_timeout_ms());
                let source_rows = executor.execute(source)?;

                // Check for RLS enforcement
                let rls_enforced = self.tenant_manager.should_apply_rls(table_name, "INSERT");
                let rls_check = if rls_enforced {
                    self.tenant_manager.get_rls_conditions(table_name, "INSERT")
                } else {
                    None
                };

                let catalog = self.storage.catalog();
                let schema = catalog.get_table_schema(table_name)?;
                let evaluator = sql::Evaluator::new(std::sync::Arc::new(Schema { columns: vec![] }));
                let empty_tuple = Tuple::new(vec![]);

                let column_indices: Option<Vec<usize>> = columns.as_ref().map(|cols| {
                    cols.iter()
                        .filter_map(|col_name| schema.get_column_index(col_name))
                        .collect()
                });

                let default_exprs: Vec<Option<sql::LogicalExpr>> = schema
                    .columns
                    .iter()
                    .map(|col| {
                        col.default_expr
                            .as_ref()
                            .and_then(|json| serde_json::from_str(json).ok())
                    })
                    .collect();

                let mut count = 0u64;
                for source_row in &source_rows {
                    let mut tuple_values: Vec<Option<Value>> = vec![None; schema.columns.len()];

                    for (val_idx, value) in source_row.values.iter().enumerate() {
                        let target_col_idx = if let Some(ref indices) = column_indices {
                            if val_idx >= indices.len() {
                                return Err(Error::query_execution("More values than columns specified"));
                            }
                            *indices
                                .get(val_idx)
                                .ok_or_else(|| Error::internal("column index out of bounds"))?
                        } else {
                            val_idx
                        };

                        let target_col = schema.get_column_at(target_col_idx).ok_or_else(|| {
                            Error::query_execution(format!(
                                "Too many values for INSERT: table has {} columns",
                                schema.columns.len()
                            ))
                        })?;

                        let target_type = &target_col.data_type;
                        let mut val = value.clone();

                        let needs_cast = match (&val, target_type) {
                            (Value::Null, _) => false,
                            (Value::Vector(_), DataType::Vector(_)) => true,
                            (Value::String(_), DataType::Vector(_)) => true,
                            (Value::String(_), DataType::Json | DataType::Jsonb) => true,
                            (Value::Int4(_), DataType::Int4) => false,
                            (Value::Int8(_), DataType::Int8) => false,
                            (Value::Float4(_), DataType::Float4) => false,
                            (Value::Float8(_), DataType::Float8) => false,
                            (Value::String(_), DataType::Text | DataType::Varchar(_)) => false,
                            (Value::Boolean(_), DataType::Boolean) => false,
                            (Value::Json(_), DataType::Json | DataType::Jsonb) => false,
                            _ => true,
                        };

                        if needs_cast {
                            val = evaluator.cast_value(val, target_type)?;
                        }

                        let tv = tuple_values
                            .get_mut(target_col_idx)
                            .ok_or_else(|| Error::internal("column index out of bounds"))?;
                        *tv = Some(val);
                    }

                    let final_values: Result<Vec<Value>> = tuple_values
                        .into_iter()
                        .enumerate()
                        .map(|(idx, opt_val)| {
                            if let Some(val) = opt_val {
                                Ok(val)
                            } else {
                                let col = schema
                                    .get_column_at(idx)
                                    .ok_or_else(|| Error::internal("column index out of bounds"))?;
                                if let Some(ref default_expr) = default_exprs.get(idx).and_then(|d| d.as_ref()) {
                                    let mut value = evaluator.evaluate(default_expr, &empty_tuple)?;
                                    if value.data_type() != col.data_type {
                                        value = evaluator.cast_value(value, &col.data_type)?;
                                    }
                                    Ok(value)
                                } else if col.primary_key {
                                    // PK column omitted from INSERT — fill with NULL so
                                    // the SERIAL auto-fill logic replaces it with row_id.
                                    Ok(Value::Null)
                                } else if col.nullable {
                                    Ok(Value::Null)
                                } else {
                                    Err(Error::query_execution(format!(
                                        "Column '{}' does not have a default value and is not nullable",
                                        col.name
                                    )))
                                }
                            }
                        })
                        .collect();

                    let tuple = Tuple::new(final_values?);

                    // Validate RLS
                    if let Some((_, with_check)) = &rls_check {
                        if let Some(ref with_check_expr) = with_check {
                            let tenant_context = self.tenant_manager.get_current_context();
                            let rls_evaluator = tenant::RLSExpressionEvaluator::new(
                                std::sync::Arc::new(schema.clone()),
                                tenant_context,
                            );
                            let expr = rls_evaluator.parse(with_check_expr)?;
                            let satisfies_policy = rls_evaluator.evaluate(&expr, &tuple)?;
                            if !satisfies_policy {
                                return Err(Error::query_execution(
                                    "Row-Level Security policy violation: inserted row does not satisfy WITH CHECK expression"
                                ));
                            }
                        }
                    }

                    self.storage
                        .insert_tuple_branch_aware_with_schema(table_name, tuple, &schema)?;
                    count += 1;
                }
                Ok(count)
            }
            sql::LogicalPlan::Update {
                table_name,
                assignments,
                selection,
                returning,
            } => {
                // Check for RLS enforcement
                let rls_enforced = self.tenant_manager.should_apply_rls(table_name, "UPDATE");
                let rls_condition = if rls_enforced {
                    self.tenant_manager.get_rls_conditions(table_name, "UPDATE")
                } else {
                    None
                };

                // Scan table to get all tuples with their row IDs
                let catalog = self.storage.catalog();
                let schema = catalog.get_table_schema(table_name)?;
                // Stamp source_table_name so qualified predicates resolve (B31).
                let eval_schema = schema.clone().with_source_table_name(table_name);
                let evaluator = sql::Evaluator::new(std::sync::Arc::new(eval_schema));

                // Use branch-aware scan to get tuples (includes main + branch overrides - deleted)
                let tuples = self.storage.scan_table_branch_aware(table_name)?;
                let mut updates: Vec<(u64, Tuple)> = Vec::new();

                for mut tuple in tuples {
                    // Check if tuple matches WHERE clause (if provided)
                    let where_matches = if let Some(predicate) = selection {
                        let result = evaluator.evaluate(predicate, &tuple)?;
                        match result {
                            Value::Boolean(b) => b,
                            _ => false,
                        }
                    } else {
                        true // No WHERE clause means update all
                    };

                    // Check RLS policy (if enforced)
                    let rls_matches = if let Some((using_expr, _)) = &rls_condition {
                        // Evaluate RLS using expression to check if row can be updated
                        let tenant_context = self.tenant_manager.get_current_context();
                        let rls_evaluator =
                            tenant::RLSExpressionEvaluator::new(std::sync::Arc::new(schema.clone()), tenant_context);
                        let expr = rls_evaluator.parse(using_expr)?;
                        rls_evaluator.evaluate(&expr, &tuple)?
                    } else {
                        true // No RLS policy = allow
                    };

                    if where_matches && rls_matches {
                        // Apply updates — materialise any scalar
                        // subqueries (including correlated ones) per
                        // row before handing the expression to the
                        // row-scoped evaluator.
                        for (col_name, value_expr) in assignments {
                            let bound =
                                self.materialize_scalar_subqueries_for_row(value_expr, &tuple, &schema, table_name, &[])?;
                            let mut new_value = evaluator.evaluate(&bound, &tuple)?;
                            // Find column index
                            let col_index = evaluator
                                .schema()
                                .get_column_index(col_name)
                                .ok_or_else(|| Error::query_execution(format!("Column '{}' not found", col_name)))?;
                            // Auto-cast to target column type (B34).
                            let target_col = schema
                                .get_column_at(col_index)
                                .ok_or_else(|| Error::query_execution(format!("Column '{}' not found", col_name)))?;
                            let target_type = &target_col.data_type;
                            let needs_cast = !matches!(&new_value, Value::Null)
                                && !matches!(
                                    (&new_value, target_type),
                                    (Value::Vector(_), DataType::Vector(_))
                                        | (Value::Int2(_), DataType::Int2)
                                        | (Value::Int4(_), DataType::Int4)
                                        | (Value::Int8(_), DataType::Int8)
                                        | (Value::Float4(_), DataType::Float4)
                                        | (Value::Float8(_), DataType::Float8)
                                        | (Value::String(_), DataType::Text | DataType::Varchar(_))
                                        | (Value::Boolean(_), DataType::Boolean)
                                        | (Value::Json(_), DataType::Json | DataType::Jsonb)
                                        | (Value::Timestamp(_), DataType::Timestamp | DataType::Timestamptz)
                                        | (Value::Date(_), DataType::Date)
                                );
                            if needs_cast {
                                new_value = evaluator.cast_value(new_value, target_type)?;
                            }
                            if let Some(slot) = tuple.values.get_mut(col_index) {
                                *slot = new_value;
                            }
                        }

                        // FK validation on UPDATE (Kanttban bug #6 fix)
                        // — secondary path that bypassed the txn-bound
                        // executor.
                        let mut new_col_values = std::collections::HashMap::with_capacity(schema.columns.len());
                        for (i, col) in schema.columns.iter().enumerate() {
                            if let Some(v) = tuple.values.get(i) {
                                new_col_values.insert(col.name.clone(), v.clone());
                            }
                        }
                        self.check_fk_constraints_on_write(table_name, &new_col_values, None)?;

                        let row_id = tuple.row_id.unwrap_or(0);
                        updates.push((row_id, tuple));
                    }
                }

                // Use branch-aware update which properly handles:
                // - Main branch: direct key update
                // - Other branches: write to branch-specific keys
                let update_count = self.storage.update_tuples_branch_aware(table_name, updates)?;
                Ok(update_count)
            }
            sql::LogicalPlan::Delete {
                table_name,
                selection,
                returning,
            } => {
                // Check for RLS enforcement
                let rls_enforced = self.tenant_manager.should_apply_rls(table_name, "DELETE");
                let rls_condition = if rls_enforced {
                    self.tenant_manager.get_rls_conditions(table_name, "DELETE")
                } else {
                    None
                };

                // Scan table to get all tuples
                let catalog = self.storage.catalog();
                let schema = catalog.get_table_schema(table_name)?;
                // Stamp source_table_name so qualified predicates resolve (B31).
                let eval_schema = schema.clone().with_source_table_name(table_name);
                let evaluator = sql::Evaluator::new(std::sync::Arc::new(eval_schema));

                // Use branch-aware scan to get tuples (includes main + branch overrides - deleted)
                let tuples = self.storage.scan_table_branch_aware(table_name)?;
                let mut row_ids_to_delete: Vec<u64> = Vec::new();
                let mut deleted_tuples: Vec<(u64, Tuple)> = Vec::new();

                for tuple in tuples {
                    // Check if tuple matches WHERE clause (if provided)
                    let where_matches = if let Some(predicate) = selection {
                        let result = evaluator.evaluate(predicate, &tuple)?;
                        match result {
                            Value::Boolean(b) => b,
                            _ => false,
                        }
                    } else {
                        true // No WHERE clause means delete all
                    };

                    // Check RLS policy (if enforced)
                    let rls_matches = if let Some((using_expr, _)) = &rls_condition {
                        // Evaluate RLS using expression to check if row can be deleted
                        let tenant_context = self.tenant_manager.get_current_context();
                        let rls_evaluator =
                            tenant::RLSExpressionEvaluator::new(std::sync::Arc::new(schema.clone()), tenant_context);
                        let expr = rls_evaluator.parse(using_expr)?;
                        rls_evaluator.evaluate(&expr, &tuple)?
                    } else {
                        true // No RLS policy = allow
                    };

                    if where_matches && rls_matches {
                        if let Some(row_id) = tuple.row_id {
                            row_ids_to_delete.push(row_id);
                            deleted_tuples.push((row_id, tuple.clone()));
                        }
                    }
                }

                // Update ART indexes for deleted rows
                for (row_id, tuple) in &deleted_tuples {
                    let mut col_values = std::collections::HashMap::new();
                    for (i, col) in schema.columns.iter().enumerate() {
                        if let Some(v) = tuple.values.get(i) {
                            col_values.insert(col.name.clone(), v.clone());
                        }
                    }
                    if let Err(e) = self.storage.art_indexes().on_delete(table_name, *row_id, &col_values) {
                        tracing::debug!("ART index delete for table '{}': {}", table_name, e);
                    }
                }

                // Use branch-aware delete which properly handles:
                // - Main branch: actual key deletion
                // - Other branches: delete marker creation
                let delete_count = self.storage.delete_tuples_branch_aware(table_name, row_ids_to_delete)?;
                Ok(delete_count)
            }
            sql::LogicalPlan::DropTable { name, if_exists } => {
                // Check if table exists
                let catalog = self.storage.catalog();
                let exists = catalog.table_exists(name)?;

                if exists {
                    // Check if any materialized views depend on this table
                    let mv_catalog = self.storage.mv_catalog();
                    if let Ok(mv_names) = mv_catalog.list_views() {
                        let mut dependent_mvs = Vec::new();
                        for mv_name in &mv_names {
                            if let Ok(metadata) = mv_catalog.get_view(mv_name) {
                                if metadata.base_tables.iter().any(|t| t == name) {
                                    dependent_mvs.push(mv_name.clone());
                                }
                            }
                        }
                        if !dependent_mvs.is_empty() {
                            tracing::warn!(
                                "Dropping table '{}' which is used by materialized view(s): {}. Those views will be stale.",
                                name,
                                dependent_mvs.join(", ")
                            );
                        }
                    }

                    // Drop the table (schema, data, ART indexes, stats)
                    catalog.drop_table(name)?;

                    // Clean up triggers for this table
                    if let Err(e) = self.trigger_registry.drop_table_triggers(name) {
                        tracing::warn!("Failed to clean up triggers for dropped table '{}': {}", name, e);
                    }

                    // Clean up bloom filters and zone maps
                    self.storage.predicate_pushdown().remove_table(name);

                    // Invalidate all cached rows for this table
                    self.storage.row_cache().invalidate_table(name);

                    // Log to WAL for replication
                    if let Err(e) = self.storage.log_drop_table(name) {
                        tracing::warn!("Failed to log DROP TABLE to WAL: {}", e);
                    }

                    Ok(0) // 0 rows affected by DROP TABLE
                } else if *if_exists {
                    // IF EXISTS - no error if table doesn't exist
                    Ok(0)
                } else {
                    // Table doesn't exist and IF NOT EXISTS wasn't specified
                    Err(Error::query_execution(format!("Table '{}' does not exist", name)))
                }
            }
            sql::LogicalPlan::Truncate { table_name } => {
                // TRUNCATE removes all rows from a table
                // Implementation: Delete all keys with the table prefix

                // Initialize trigger context for cascading detection
                let mut trigger_context = sql::TriggerContext::new();
                let trigger_event = sql::logical_plan::TriggerEvent::Truncate;

                // TRUNCATE triggers are FOR EACH STATEMENT only - no OLD/NEW rows
                let row_context = sql::triggers::TriggerRowContext {
                    old_tuple: None,
                    new_tuple: None,
                    transition_tables: None,
                };

                // Execute BEFORE TRUNCATE triggers
                let db_ref = self.clone_for_trigger();
                let mut executor_fn =
                    |stmt: &sql::LogicalPlan, _ctx: &sql::triggers::TriggerRowContext| -> Result<()> {
                        db_ref.execute_plan_internal(stmt)?;
                        Ok(())
                    };

                let action = self.trigger_registry.execute_triggers(
                    table_name,
                    &trigger_event,
                    &sql::logical_plan::TriggerTiming::Before,
                    &row_context,
                    &mut trigger_context,
                    None, // No schema needed for statement-level TRUNCATE triggers
                    &mut executor_fn,
                )?;

                // Handle trigger action
                match action {
                    sql::triggers::TriggerAction::Abort(msg) => {
                        return Err(Error::query_execution(format!("TRUNCATE aborted by trigger: {}", msg)));
                    }
                    sql::triggers::TriggerAction::Skip => {
                        // INSTEAD OF trigger - skip the truncate
                        return Ok(0);
                    }
                    sql::triggers::TriggerAction::Continue => {
                        // Continue with truncate
                    }
                }

                let prefix = format!("data:{}:", table_name);
                let prefix_bytes = prefix.as_bytes();
                let mut keys_to_delete = Vec::new();

                // Collect all keys for this table
                let iter = self.storage.db.iterator(rocksdb::IteratorMode::Start);
                for item in iter {
                    let (key, _) = item.map_err(|e| Error::storage(format!("Iterator error: {}", e)))?;

                    if !key.starts_with(prefix_bytes) {
                        if !key.is_empty() && key.first() > prefix_bytes.first() {
                            break;
                        }
                        continue;
                    }

                    keys_to_delete.push(key.to_vec());
                }

                // Item #2: materialize COPY marker-covered rows' insert versions
                // before removing their `data:`, so AS-OF reads predating this
                // TRUNCATE still resolve them (matches the per-row baseline,
                // which leaves `v:` intact across TRUNCATE). No-op without markers.
                self.storage.materialize_copy_markers_for_table(table_name)?;

                // Delete all collected keys
                for key in &keys_to_delete {
                    self.storage.delete(key)?;
                }

                // R3.3: purge columnar sidecars (col:/colz:/colzm:/colp:/colpm:)
                // with the rows — otherwise batch-driven columnar reads and the
                // presence sidecar would resurrect truncated rows. No-op prefix
                // seeks for tables without columnar columns.
                storage::ColumnarStore::purge_table_sidecars(&self.storage.db(), table_name)?;

                // Invalidate all cached rows for this table
                self.storage.row_cache().invalidate_table(table_name);

                // Clear ART index entries for this table so that stale PK/UNIQUE
                // values do not block re-insertion of the same values.
                // Skip clearing if user-created branches exist (exclude the
                // auto-created "main" branch). Branch data uses separate key
                // prefixes and does not share the ART index, but as a safety
                // measure we skip clearing when user branches exist.
                let has_user_branches = self
                    .storage
                    .list_branches()
                    .map(|b| b.iter().any(|br| br.name != "main"))
                    .unwrap_or(false);
                if !has_user_branches {
                    self.storage.art_indexes().clear_table_indexes(table_name);
                }

                // Execute AFTER TRUNCATE triggers
                let action = self.trigger_registry.execute_triggers(
                    table_name,
                    &trigger_event,
                    &sql::logical_plan::TriggerTiming::After,
                    &row_context,
                    &mut trigger_context,
                    None, // No schema needed for statement-level TRUNCATE triggers
                    &mut executor_fn,
                )?;

                // Handle AFTER trigger action
                if let sql::triggers::TriggerAction::Abort(msg) = action {
                    return Err(Error::query_execution(format!(
                        "TRUNCATE failed in AFTER trigger: {}",
                        msg
                    )));
                }

                // Log to WAL for replication
                if let Err(e) = self.storage.log_truncate(table_name) {
                    tracing::warn!("Failed to log TRUNCATE to WAL: {}", e);
                }

                Ok(keys_to_delete.len() as u64) // Return number of rows deleted
            }
            sql::LogicalPlan::AlterColumnStorage {
                table_name,
                column_name,
                storage_mode,
            } => {
                // ALTER TABLE t ALTER COLUMN c SET STORAGE mode
                // Migrates existing data to the new storage format online

                let catalog = self.storage.catalog();
                let mut schema = catalog.get_table_schema(table_name)?;

                // Find column index
                let col_idx = schema
                    .columns
                    .iter()
                    .position(|c| c.name == *column_name)
                    .ok_or_else(|| {
                        Error::query_execution(format!("Column '{}' not found in table '{}'", column_name, table_name))
                    })?;

                let col_ref = schema
                    .get_column_at(col_idx)
                    .ok_or_else(|| Error::internal("column index out of bounds"))?;
                let old_mode = col_ref.storage_mode;
                if old_mode == *storage_mode {
                    // No change needed
                    return Ok(0);
                }

                // Migrate existing data online
                let column = col_ref.clone();
                let rows_migrated =
                    self.storage
                        .migrate_column_storage(table_name, col_idx, &column, old_mode, *storage_mode)?;

                // Update schema with new storage mode
                schema
                    .get_column_at_mut(col_idx)
                    .ok_or_else(|| Error::internal("column index out of bounds"))?
                    .storage_mode = *storage_mode;
                catalog.update_table_schema(table_name, &schema)?;

                // Log to WAL for replication
                if let Err(e) = self
                    .storage
                    .log_alter_column_storage(table_name, column_name, storage_mode)
                {
                    tracing::warn!("Failed to log ALTER COLUMN STORAGE to WAL: {}", e);
                }

                tracing::info!(
                    "Altered {}.{} storage from {:?} to {:?}, migrated {} rows",
                    table_name,
                    column_name,
                    old_mode,
                    storage_mode,
                    rows_migrated
                );

                Ok(rows_migrated as u64)
            }
            sql::LogicalPlan::AlterTableAddColumn {
                table_name,
                column_def,
                if_not_exists,
            } => {
                let catalog = self.storage.catalog();
                let mut schema = catalog.get_table_schema(table_name)?;

                if schema.columns.iter().any(|c| c.name == column_def.name) {
                    if *if_not_exists {
                        return Ok(0);
                    }
                    return Err(Error::query_execution(format!(
                        "Column '{}' already exists in table '{}'",
                        column_def.name, table_name
                    )));
                }

                let new_column = Column {
                    name: column_def.name.clone(),
                    data_type: column_def.data_type.clone(),
                    nullable: !column_def.not_null,
                    primary_key: column_def.primary_key,
                    source_table: None,
                    source_table_name: Some(table_name.clone()),
                    default_expr: Self::serialize_default_expr(&column_def.default),
                    unique: column_def.unique,
                    storage_mode: column_def.storage_mode,
                };

                schema.columns.push(new_column);
                catalog.update_table_schema(table_name, &schema)?;

                let rows_updated = self.storage.add_column_to_rows(table_name, &column_def.default)?;
                Ok(rows_updated as u64)
            }
            sql::LogicalPlan::AlterTableDropColumn {
                table_name,
                column_name,
                if_exists,
                cascade,
            } => {
                let catalog = self.storage.catalog();
                let mut schema = catalog.get_table_schema(table_name)?;

                let col_idx = schema.columns.iter().position(|c| c.name == *column_name);

                match col_idx {
                    Some(idx) => {
                        if schema.get_column_at(idx).is_some_and(|c| c.primary_key) && !cascade {
                            return Err(Error::query_execution(format!(
                                "Cannot drop primary key column '{}' without CASCADE",
                                column_name
                            )));
                        }

                        let was_columnar = schema
                            .get_column_at(idx)
                            .is_some_and(|c| c.storage_mode == ColumnStorageMode::Columnar);
                        schema.columns.remove(idx);
                        catalog.update_table_schema(table_name, &schema)?;
                        let rows_updated = self.storage.drop_column_from_rows(table_name, idx)?;
                        self.cleanup_columnar_after_drop_column(table_name, column_name, was_columnar, &schema)?;
                        Ok(rows_updated as u64)
                    }
                    None => {
                        if *if_exists {
                            Ok(0)
                        } else {
                            Err(Error::query_execution(format!(
                                "Column '{}' does not exist in table '{}'",
                                column_name, table_name
                            )))
                        }
                    }
                }
            }
            sql::LogicalPlan::AlterTableRenameColumn {
                table_name,
                old_column_name,
                new_column_name,
            } => {
                let catalog = self.storage.catalog();
                let mut schema = catalog.get_table_schema(table_name)?;

                if schema.columns.iter().any(|c| c.name == *new_column_name) {
                    return Err(Error::query_execution(format!(
                        "Column '{}' already exists in table '{}'",
                        new_column_name, table_name
                    )));
                }

                let col_idx = schema
                    .columns
                    .iter()
                    .position(|c| c.name == *old_column_name)
                    .ok_or_else(|| {
                        Error::query_execution(format!(
                            "Column '{}' does not exist in table '{}'",
                            old_column_name, table_name
                        ))
                    })?;

                schema
                    .get_column_at_mut(col_idx)
                    .ok_or_else(|| Error::internal("column index out of bounds"))?
                    .name = new_column_name.clone();
                catalog.update_table_schema(table_name, &schema)?;
                Ok(0)
            }
            sql::LogicalPlan::AlterTableAlterColumnNullability {
                table_name,
                column_name,
                nullable,
            } => self.alter_table_set_column_nullability(table_name, column_name, *nullable),
            sql::LogicalPlan::AlterTableRename {
                table_name,
                new_table_name,
            } => {
                let catalog = self.storage.catalog();

                if catalog.get_table_schema(new_table_name).is_ok() {
                    return Err(Error::query_execution(format!(
                        "Table '{}' already exists",
                        new_table_name
                    )));
                }

                self.storage.rename_table(table_name, new_table_name)?;
                Ok(0)
            }
            sql::LogicalPlan::AlterTableMulti { operations } => {
                let mut total_rows = 0u64;
                for sub_plan in operations {
                    total_rows += self.execute_alter_table_op(sub_plan)?;
                }
                Ok(total_rows)
            }
            sql::LogicalPlan::Savepoint { ref name } => {
                let txn = self
                    .current_transaction
                    .lock();
                let (write_set_snapshot, art_undo_len) = match txn.as_ref() {
                    Some(t) => (t.savepoint_snapshot(), self.art_undo_len_for(t)),
                    None => {
                        return Err(Error::query_execution(
                            "SAVEPOINT can only be used within a transaction",
                        ))
                    }
                };
                drop(txn);
                let savepoint = SavepointState {
                    name: name.clone(),
                    write_set_snapshot,
                    art_undo_len,
                };
                self.savepoints.write().push(savepoint);
                Ok(0)
            }
            sql::LogicalPlan::ReleaseSavepoint { ref name } => {
                let mut savepoints = self.savepoints.write();
                if let Some(pos) = savepoints.iter().rposition(|s| &s.name == name) {
                    savepoints.truncate(pos);
                    Ok(0)
                } else {
                    Err(Error::query_execution(format!("Savepoint '{}' does not exist", name)))
                }
            }
            sql::LogicalPlan::RollbackToSavepoint { ref name } => {
                let savepoints = self.savepoints.read();
                if let Some(pos) = savepoints.iter().rposition(|s| &s.name == name) {
                    let restore = savepoints
                        .get(pos)
                        .map(|s| (s.write_set_snapshot.clone(), s.art_undo_len));
                    drop(savepoints);

                    if let Some((snapshot, art_undo_len)) = restore {
                        let txn = self
                            .current_transaction
                            .lock();
                        if let Some(t) = txn.as_ref() {
                            t.rollback_to_savepoint(&snapshot);
                            self.rollback_art_undo_to(t, art_undo_len);
                        }
                        drop(txn);
                    }

                    let mut savepoints = self.savepoints.write();
                    savepoints.truncate(pos + 1);
                    Ok(0)
                } else {
                    Err(Error::query_execution(format!("Savepoint '{}' does not exist", name)))
                }
            }
            sql::LogicalPlan::CreateDatabase { name, if_not_exists } => {
                let (count, _) = self.handle_create_database(name, *if_not_exists)?;
                Ok(count)
            }
            sql::LogicalPlan::DropDatabase { name, if_exists } => {
                let (count, _) = self.handle_drop_database(name, *if_exists)?;
                Ok(count)
            }
            _ => {
                // For query plans, use executor
                let mut executor =
                    sql::Executor::with_storage(&self.storage).with_timeout(self.effective_statement_timeout_ms());
                let results = executor.execute(&plan)?;
                Ok(results.len() as u64)
            }
        }
    }

    /// Execute a SQL statement with parameters (SAFE - prevents SQL injection)
    ///
    /// This method uses parameterized queries to safely execute SQL with user input.
    /// Parameters are referenced as $1, $2, $3, etc. in PostgreSQL style.
    ///
    /// # Arguments
    ///
    /// * `sql` - SQL statement with parameter placeholders ($1, $2, etc.)
    /// * `params` - Parameter values in order
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::{EmbeddedDatabase, Value};
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new("./data")?;
    ///
    /// // Create table
    /// db.execute("CREATE TABLE users (id INT, name TEXT, email TEXT)")?;
    ///
    /// // Safe INSERT with parameters
    /// let user_name = "Alice";
    /// let user_email = "alice@example.com";
    /// db.execute_params(
    ///     "INSERT INTO users (id, name, email) VALUES ($1, $2, $3)",
    ///     &[
    ///         Value::Int4(1),
    ///         Value::String(user_name.to_string()),
    ///         Value::String(user_email.to_string()),
    ///     ]
    /// )?;
    ///
    /// // Safe UPDATE with parameters
    /// db.execute_params(
    ///     "UPDATE users SET email = $1 WHERE name = $2",
    ///     &[
    ///         Value::String("newemail@example.com".to_string()),
    ///         Value::String("Alice".to_string()),
    ///     ]
    /// )?;
    ///
    /// // Safe DELETE with parameters
    /// db.execute_params(
    ///     "DELETE FROM users WHERE id = $1",
    ///     &[Value::Int4(1)]
    /// )?;
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Security
    ///
    /// This method prevents SQL injection by treating parameters as data, not code.
    /// Even malicious input like `"'; DROP TABLE users; --"` is safely handled.
    pub fn execute_params(&self, sql: &str, params: &[Value]) -> Result<u64> {
        self.execute_params_inner(sql, params, None)
    }

    /// `execute_params` with an optional pre-fetched parameterized plan
    /// (R5.W2). Every fast path below runs unchanged — only the plan-cache
    /// lookup is replaced by the pinned plan. The plan is the unmodified
    /// `parameterized_plan_cached` output, so DML keeps the exact planning
    /// behavior (no extra optimizer passes — see the W3 caveat).
    fn execute_params_inner(
        &self,
        sql: &str,
        params: &[Value],
        plan_override: Option<&std::sync::Arc<sql::LogicalPlan>>,
    ) -> Result<u64> {
        if let Some(result) = self.try_autocommit_fast_update_delete_params_cached(sql, params) {
            let count = result?;
            self.invalidate_result_cache();
            return Ok(count);
        }

        let plan = match plan_override {
            Some(p) => std::sync::Arc::clone(p),
            None => self.parameterized_plan_cached(sql)?,
        };

        if let Some(result) = self.try_transaction_fast_insert_params(sql, &plan, params) {
            let count = result?;
            return Ok(count);
        }
        if let Some(result) = self.try_autocommit_fast_insert_params(sql, &plan, params) {
            let count = result?;
            self.invalidate_result_cache();
            return Ok(count);
        }
        if let Some(result) = self.try_autocommit_fast_update_delete_params(sql, &plan, params) {
            let count = result?;
            self.invalidate_result_cache();
            return Ok(count);
        }

        let (count, _tuples) = self.execute_plan_with_params(&plan, params, None)?;
        Ok(count)
    }

    /// Execute one parameterized statement for many parameter rows.
    ///
    /// Repeated simple INSERTs use a batched fast path that parses/plans once,
    /// materializes all tuples once, and stages the whole batch in the active
    /// transaction when one exists. Other statements fall back to the exact
    /// per-row `execute_params` behavior.
    pub fn execute_many_params(&self, sql: &str, rows: &[Vec<Value>]) -> Result<u64> {
        if rows.is_empty() {
            return Ok(0);
        }

        let plan = self.parameterized_plan_cached(sql)?;
        if let Some(result) = self.try_fast_insert_many_params(sql, &plan, rows) {
            let count = result?;
            if !self.in_transaction() {
                self.invalidate_result_cache();
            }
            return Ok(count);
        }
        if let Some(result) = self.try_autocommit_fast_update_delete_many_params(sql, &plan, rows) {
            let count = result?;
            self.invalidate_result_cache();
            return Ok(count);
        }

        let mut total = 0_u64;
        for params in rows {
            total += self.execute_params(sql, params)?;
        }
        Ok(total)
    }

    /// Execute a parameterized SQL statement with RETURNING clause support
    ///
    /// Similar to `execute_params`, but returns the tuples from RETURNING clause
    /// if present. For INSERT/UPDATE/DELETE with RETURNING, returns the affected rows.
    ///
    /// # Arguments
    ///
    /// * `sql` - The SQL statement with `$N` parameter placeholders
    /// * `params` - The parameter values in order ($1, $2, etc.)
    ///
    /// # Returns
    ///
    /// A tuple of (rows_affected, returned_tuples). If no RETURNING clause is present,
    /// returned_tuples will be empty.
    ///
    /// # Example
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::{EmbeddedDatabase, Value};
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new("./data")?;
    ///
    /// // INSERT with RETURNING
    /// let (count, rows) = db.execute_params_returning(
    ///     "INSERT INTO users (id, name) VALUES ($1, $2) RETURNING *",
    ///     &[Value::Int4(1), Value::String("Alice".to_string())]
    /// )?;
    ///
    /// assert_eq!(count, 1);
    /// assert_eq!(rows.len(), 1);
    /// # Ok(())
    /// # }
    /// ```
    pub fn execute_params_returning(&self, sql: &str, params: &[Value]) -> Result<(u64, Vec<Tuple>)> {
        let plan = self.parameterized_plan_cached(sql)?;

        let out = self.execute_plan_with_params(&plan, params, None);

        // 4. Code-graph auto_reparse hook — same logic as `execute()`
        //    so parameterised DML updates stay in sync with declared
        //    AST indexes.
        #[cfg(feature = "code-graph")]
        if out.is_ok() {
            let touched = Self::touched_table_from_sql(sql);
            self.maybe_auto_reparse(touched.as_deref());
        }

        out
    }

    /// Project columns from a tuple according to RETURNING clause
    ///
    /// # Arguments
    /// * `tuple` - The tuple to project from
    /// * `schema` - The schema of the tuple
    /// * `returning_items` - RETURNING clause items (None means no RETURNING)
    ///
    /// # Returns
    /// * Some(projected_tuple) if RETURNING items specified
    /// * None if no RETURNING clause
    fn project_returning_columns(
        tuple: &Tuple,
        schema: &Schema,
        returning_items: &Option<Vec<sql::logical_plan::ReturningItem>>,
    ) -> Option<Tuple> {
        let items = returning_items.as_ref()?;

        let evaluator = sql::Evaluator::new(std::sync::Arc::new(schema.clone()));
        let mut projected_values = Vec::with_capacity(items.len());

        for item in items {
            match item {
                sql::logical_plan::ReturningItem::Wildcard => {
                    // Return all columns
                    return Some(tuple.clone());
                }
                sql::logical_plan::ReturningItem::Column(col_name) => {
                    if let Some(col_idx) = schema.get_column_index(col_name) {
                        if let Some(val) = tuple.values.get(col_idx) {
                            projected_values.push(val.clone());
                        } else {
                            projected_values.push(Value::Null);
                        }
                    } else {
                        // Column not found - return NULL
                        projected_values.push(Value::Null);
                    }
                }
                sql::logical_plan::ReturningItem::Expression { expr, .. } => {
                    // Evaluate expression against the tuple
                    match evaluator.evaluate(expr, tuple) {
                        Ok(val) => projected_values.push(val),
                        Err(_) => projected_values.push(Value::Null),
                    }
                }
            }
        }

        Some(Tuple::new(projected_values))
    }

    /// Resolve `EXCLUDED.col` references in an expression for ON CONFLICT DO UPDATE.
    ///
    /// Replaces `LogicalExpr::Column { table: Some("EXCLUDED"|"excluded"), name }` with
    /// the literal value from the proposed INSERT row. All nested expressions are
    /// recursively traversed so `CASE`, `COALESCE`, predicates, and tuple forms
    /// can freely mix existing-row refs with `EXCLUDED.*`.
    fn resolve_excluded_refs(
        expr: &sql::logical_plan::LogicalExpr,
        excluded_map: &std::collections::HashMap<String, Value>,
    ) -> sql::logical_plan::LogicalExpr {
        match expr {
            sql::logical_plan::LogicalExpr::Column { table: Some(tbl), name }
                if tbl.eq_ignore_ascii_case("excluded") =>
            {
                // Replace with the literal value from the INSERT row
                if let Some(val) = excluded_map.get(&name.to_lowercase()) {
                    sql::logical_plan::LogicalExpr::Literal(val.clone())
                } else {
                    expr.clone()
                }
            }
            sql::logical_plan::LogicalExpr::BinaryExpr { left, op, right } => {
                sql::logical_plan::LogicalExpr::BinaryExpr {
                    left: Box::new(Self::resolve_excluded_refs(left, excluded_map)),
                    op: op.clone(),
                    right: Box::new(Self::resolve_excluded_refs(right, excluded_map)),
                }
            }
            sql::logical_plan::LogicalExpr::UnaryExpr { op, expr: inner } => {
                sql::logical_plan::LogicalExpr::UnaryExpr {
                    op: op.clone(),
                    expr: Box::new(Self::resolve_excluded_refs(inner, excluded_map)),
                }
            }
            sql::logical_plan::LogicalExpr::AggregateFunction { fun, args, distinct } => {
                sql::logical_plan::LogicalExpr::AggregateFunction {
                    fun: fun.clone(),
                    args: args
                        .iter()
                        .map(|a| Self::resolve_excluded_refs(a, excluded_map))
                        .collect(),
                    distinct: *distinct,
                }
            }
            sql::logical_plan::LogicalExpr::Cast { expr: inner, data_type } => sql::logical_plan::LogicalExpr::Cast {
                expr: Box::new(Self::resolve_excluded_refs(inner, excluded_map)),
                data_type: data_type.clone(),
            },
            sql::logical_plan::LogicalExpr::ScalarFunction { fun, args } => {
                sql::logical_plan::LogicalExpr::ScalarFunction {
                    fun: fun.clone(),
                    args: args
                        .iter()
                        .map(|a| Self::resolve_excluded_refs(a, excluded_map))
                        .collect(),
                }
            }
            sql::logical_plan::LogicalExpr::Case {
                expr,
                when_then,
                else_result,
            } => sql::logical_plan::LogicalExpr::Case {
                expr: expr
                    .as_ref()
                    .map(|e| Box::new(Self::resolve_excluded_refs(e, excluded_map))),
                when_then: when_then
                    .iter()
                    .map(|(when, then)| {
                        (
                            Self::resolve_excluded_refs(when, excluded_map),
                            Self::resolve_excluded_refs(then, excluded_map),
                        )
                    })
                    .collect(),
                else_result: else_result
                    .as_ref()
                    .map(|e| Box::new(Self::resolve_excluded_refs(e, excluded_map))),
            },
            sql::logical_plan::LogicalExpr::IsNull { expr: inner, is_null } => sql::logical_plan::LogicalExpr::IsNull {
                expr: Box::new(Self::resolve_excluded_refs(inner, excluded_map)),
                is_null: *is_null,
            },
            sql::logical_plan::LogicalExpr::Between {
                expr: inner,
                low,
                high,
                negated,
            } => sql::logical_plan::LogicalExpr::Between {
                expr: Box::new(Self::resolve_excluded_refs(inner, excluded_map)),
                low: Box::new(Self::resolve_excluded_refs(low, excluded_map)),
                high: Box::new(Self::resolve_excluded_refs(high, excluded_map)),
                negated: *negated,
            },
            sql::logical_plan::LogicalExpr::InList {
                expr: inner,
                list,
                negated,
            } => sql::logical_plan::LogicalExpr::InList {
                expr: Box::new(Self::resolve_excluded_refs(inner, excluded_map)),
                list: list
                    .iter()
                    .map(|item| Self::resolve_excluded_refs(item, excluded_map))
                    .collect(),
                negated: *negated,
            },
            sql::logical_plan::LogicalExpr::InSubquery {
                expr: inner,
                subquery,
                negated,
            } => sql::logical_plan::LogicalExpr::InSubquery {
                expr: Box::new(Self::resolve_excluded_refs(inner, excluded_map)),
                subquery: subquery.clone(),
                negated: *negated,
            },
            sql::logical_plan::LogicalExpr::ArraySubscript { array, index } => {
                sql::logical_plan::LogicalExpr::ArraySubscript {
                    array: Box::new(Self::resolve_excluded_refs(array, excluded_map)),
                    index: Box::new(Self::resolve_excluded_refs(index, excluded_map)),
                }
            }
            sql::logical_plan::LogicalExpr::Tuple { items } => sql::logical_plan::LogicalExpr::Tuple {
                items: items
                    .iter()
                    .map(|item| Self::resolve_excluded_refs(item, excluded_map))
                    .collect(),
            },
            sql::logical_plan::LogicalExpr::WindowFunction {
                fun,
                args,
                partition_by,
                order_by,
                frame,
            } => sql::logical_plan::LogicalExpr::WindowFunction {
                fun: fun.clone(),
                args: args
                    .iter()
                    .map(|arg| Self::resolve_excluded_refs(arg, excluded_map))
                    .collect(),
                partition_by: partition_by
                    .iter()
                    .map(|arg| Self::resolve_excluded_refs(arg, excluded_map))
                    .collect(),
                order_by: order_by
                    .iter()
                    .map(|(arg, asc)| (Self::resolve_excluded_refs(arg, excluded_map), *asc))
                    .collect(),
                frame: frame.clone(),
            },
            // For other expression types (literals, plain columns, etc.), return as-is
            other => other.clone(),
        }
    }

    /// Build a schema for RETURNING clause results
    pub(crate) fn returning_schema(
        table_schema: &Schema,
        returning_items: &[sql::logical_plan::ReturningItem],
    ) -> Schema {
        let columns = returning_items
            .iter()
            .flat_map(|item| match item {
                sql::logical_plan::ReturningItem::Wildcard => table_schema.columns.clone(),
                sql::logical_plan::ReturningItem::Column(col_name) => {
                    if let Some(col) = table_schema.columns.iter().find(|c| &c.name == col_name) {
                        vec![col.clone()]
                    } else {
                        vec![Column {
                            name: col_name.clone(),
                            data_type: DataType::Text,
                            nullable: true,
                            primary_key: false,
                            source_table: None,
                            source_table_name: None,
                            default_expr: None,
                            unique: false,
                            storage_mode: crate::ColumnStorageMode::Default,
                        }]
                    }
                }
                sql::logical_plan::ReturningItem::Expression { alias, .. } => {
                    vec![Column {
                        name: alias.clone(),
                        data_type: DataType::Text,
                        nullable: true,
                        primary_key: false,
                        source_table: None,
                        source_table_name: None,
                        default_expr: None,
                        unique: false,
                        storage_mode: crate::ColumnStorageMode::Default,
                    }]
                }
            })
            .collect();
        Schema { columns }
    }

    /// Internal method to execute a plan with parameters
    ///
    /// Returns (rows_affected, returned_tuples) where returned_tuples is populated
    /// only when RETURNING clause is present in INSERT/UPDATE/DELETE statements.
    fn execute_plan_with_params(
        &self,
        plan: &sql::LogicalPlan,
        params: &[Value],
        session_txn: Option<&storage::Transaction>,
    ) -> Result<(u64, Vec<Tuple>)> {
        let result = self.execute_plan_with_params_inner(plan, params, session_txn);
        // Invalidate the result cache on any successful mutating plan.
        // Without this, an earlier `SELECT ... WHERE col = 'v'` that
        // returned `[]` (e.g. a login probe before register) is served
        // from the cache forever — the `INSERT ... RETURNING` path
        // routes through here and otherwise leaves the stale entry in
        // place. See the B29 regression in `tests/drizzle_compat_tests.rs`.
        if result.is_ok()
            && matches!(
                plan,
                sql::LogicalPlan::Insert { .. }
                    | sql::LogicalPlan::InsertSelect { .. }
                    | sql::LogicalPlan::Update { .. }
                    | sql::LogicalPlan::Delete { .. }
            )
        {
            self.invalidate_result_cache();
        }
        result
    }

    fn execute_plan_with_params_inner(
        &self,
        plan: &sql::LogicalPlan,
        params: &[Value],
        session_txn: Option<&storage::Transaction>,
    ) -> Result<(u64, Vec<Tuple>)> {
        // Session transactions manage their lifecycle through the session
        // API; routing plan-level transaction control at the global slot
        // from inside a session would corrupt both.
        if session_txn.is_some()
            && matches!(
                plan,
                sql::LogicalPlan::StartTransaction
                    | sql::LogicalPlan::Commit
                    | sql::LogicalPlan::Rollback
                    | sql::LogicalPlan::Savepoint { .. }
                    | sql::LogicalPlan::ReleaseSavepoint { .. }
                    | sql::LogicalPlan::RollbackToSavepoint { .. }
            )
        {
            return Err(Error::transaction(
                "transaction control statements must go through the session API",
            ));
        }
        // CREATE DATABASE / DROP DATABASE are handled here, above the
        // executor, because they only touch the in-memory TenantManager
        // (no storage). Reserved names (`heliosdb`, `postgres`) are
        // protected: CREATE refuses unless IF NOT EXISTS, DROP always
        // refuses.
        if let sql::LogicalPlan::CreateDatabase { name, if_not_exists } = plan {
            return self.handle_create_database(name, *if_not_exists);
        }
        if let sql::LogicalPlan::DropDatabase { name, if_exists } = plan {
            return self.handle_drop_database(name, *if_exists);
        }
        match plan {
            sql::LogicalPlan::Insert {
                table_name,
                columns,
                values,
                returning,
                on_conflict,
            } => {
                // Get table schema for column types
                let catalog = self.storage.catalog();
                let schema = catalog.get_table_schema(table_name)?;
                let table_constraints = catalog.load_table_constraints(table_name)?;

                // Create evaluator with parameters
                let evaluator =
                    sql::Evaluator::with_parameters(std::sync::Arc::new(Schema { columns: vec![] }), params.to_vec());
                let empty_tuple = Tuple::new(vec![]);

                // R0.2: resolve the active transaction so parameterized
                // INSERTs stage through the write set. Previously this arm
                // always wrote directly to storage — inside a transaction
                // those rows survived ROLLBACK.
                let mut _txn_guard = None;
                let active_txn: Option<&storage::Transaction> = match session_txn {
                    Some(txn) => Some(txn),
                    None => {
                        _txn_guard = Some(
                            self.current_transaction
                                .lock(),
                        );
                        _txn_guard.as_ref().and_then(|guard| guard.as_ref())
                    }
                };

                let has_returning = returning.is_some();
                let mut returned_tuples: Vec<Tuple> = Vec::new();
                let mut count = 0;
                for value_row in values {
                    // Always allocate a schema-sized tuple so omitted
                    // columns stay aligned with the schema. Previously
                    // this loop pushed values positionally, producing
                    // short tuples whenever the user omitted any
                    // column — which made `INSERT (n) VALUES ('x')
                    // RETURNING *` return a one-field DataRow against
                    // a two-field RowDescription.
                    let mut tuple_values: Vec<Value> = vec![Value::Null; schema.columns.len()];
                    let mut user_provided: Vec<bool> = vec![false; schema.columns.len()];

                    for (col_idx, expr) in value_row.iter().enumerate() {
                        let target_col_idx = if let Some(ref cols) = columns {
                            let col_name = cols
                                .get(col_idx)
                                .ok_or_else(|| Error::internal("column index out of bounds"))?;
                            schema
                                .get_column_index(col_name)
                                .ok_or_else(|| Error::query_execution(format!("Column '{}' not found", col_name)))?
                        } else {
                            col_idx
                        };

                        // `DEFAULT` inside VALUES — leave the slot
                        // untouched so the default-fill pass treats
                        // it as "omitted" and applies the column's
                        // declared DEFAULT (or NULL if none).
                        if matches!(expr, sql::LogicalExpr::DefaultValue) {
                            continue;
                        }

                        let target_col = schema.get_column_at(target_col_idx).ok_or_else(|| {
                            Error::query_execution(format!(
                                "Too many values for INSERT: table has {} columns",
                                schema.columns.len()
                            ))
                        })?;

                        let target_type = &target_col.data_type;
                        let mut value = evaluator.evaluate(expr, &empty_tuple)?;

                        // Auto-cast if needed
                        let needs_cast = match (&value, target_type) {
                            (Value::Null, _) => false,
                            (Value::Vector(_), DataType::Vector(_)) => true,
                            (Value::String(_), DataType::Vector(_)) => true,
                            (Value::String(_), DataType::Json | DataType::Jsonb) => true,
                            (Value::Int4(_), DataType::Int4) => false,
                            (Value::Int8(_), DataType::Int8) => false,
                            (Value::Float4(_), DataType::Float4) => false,
                            (Value::Float8(_), DataType::Float8) => false,
                            (Value::String(_), DataType::Text | DataType::Varchar(_)) => false,
                            (Value::Boolean(_), DataType::Boolean) => false,
                            (Value::Json(_), DataType::Json | DataType::Jsonb) => false,
                            _ => true,
                        };

                        if needs_cast {
                            value = evaluator.cast_value(value, target_type)?;
                        }

                        if let Some(slot) = tuple_values.get_mut(target_col_idx) {
                            *slot = value;
                        }
                        if let Some(flag) = user_provided.get_mut(target_col_idx) {
                            *flag = true;
                        }
                    }

                    // Apply DEFAULT expressions for omitted columns and
                    // enforce NOT NULL. SERIAL / IDENTITY auto-fill still
                    // runs inside the storage layer — we leave primary
                    // keys NULL here on purpose so the counter picks the
                    // row_id.
                    Self::apply_defaults_and_check_not_null(&mut tuple_values, &schema, &user_provided)?;

                    let tuple = Tuple::new(tuple_values);
                    self.validate_check_constraints(&table_constraints, &schema, &tuple.values)?;

                    // Pre-check PK / UNIQUE constraints so a parameterised
                    // `INSERT ... ON CONFLICT(col) DO UPDATE` can route the
                    // dup to the UPDATE branch *without* allocating a
                    // row_id from `catalog.next_row_id` only to throw it
                    // away.  Closes the cross-process leg of FR
                    // `cross_process_on_conflict`: the rebuilt ART
                    // detects rows committed by a previous process, and
                    // ON CONFLICT honours the existing-row branch.
                    let mut col_values_map = std::collections::HashMap::with_capacity(schema.columns.len());
                    for (i, col) in schema.columns.iter().enumerate() {
                        if let Some(v) = tuple.values.get(i) {
                            col_values_map.insert(col.name.clone(), v.clone());
                        }
                    }

                    let conflict = self
                        .storage
                        .art_indexes()
                        .check_unique_constraints(table_name, &col_values_map);

                    match (conflict, on_conflict) {
                        (Ok(()), _) => {
                            // No conflict — proceed with normal versioned
                            // insert.  `insert_tuple_branch_aware_with_schema`
                            // also runs `check_unique_constraints` (defence
                            // in depth post-FR fix), which is cheap.
                            //
                            // FK validation on the parameterised INSERT
                            // path (Kanttban bug #6 fix). Inside the SQL
                            // pipeline we don't have direct access to the
                            // outer txn here; pass None — the validator
                            // falls back to a committed-snapshot scan,
                            // which is correct for the autocommit /
                            // implicit-tx surface this path serves.
                            self.check_fk_constraints_on_write(table_name, &col_values_map, active_txn)?;
                            let row_id = if let Some(txn) = active_txn {
                                // Transactional staging (mirrors the
                                // execute_in_transaction_inner INSERT arm):
                                // the row lands in the write set, is visible
                                // to read-your-writes, and rolls back.
                                // R1.1: volatile row id + counter staged in the txn.
                                let row_id = self.storage.next_row_id_volatile(table_name);
                                self.storage.stage_row_counter_in_transaction(table_name, row_id, txn)?;
                                let mut staged = tuple.clone();
                                for (i, col) in schema.columns.iter().enumerate() {
                                    if col.primary_key {
                                        if let Some(Value::Null) = staged.values.get(i) {
                                            if let Some(slot) = staged.values.get_mut(i) {
                                                *slot = match col.data_type {
                                                    DataType::Int2 => Value::Int2(row_id as i16),
                                                    DataType::Int4 => Value::Int4(row_id as i32),
                                                    _ => Value::Int8(row_id as i64),
                                                };
                                            }
                                        }
                                    }
                                }
                                let mut staged_col_values =
                                    std::collections::HashMap::with_capacity(schema.columns.len());
                                for (i, col) in schema.columns.iter().enumerate() {
                                    if let Some(v) = staged.values.get(i) {
                                        staged_col_values.insert(col.name.clone(), v.clone());
                                    }
                                }
                                if self.storage.get_current_branch().is_none() {
                                    // R3.3: grouped staging marks presence too
                                    // (single-row INSERT).
                                    self.storage.stage_columnar_rows_grouped_in_transaction(
                                        table_name,
                                        &[(row_id, &staged)],
                                        &schema,
                                        txn,
                                        true,
                                    )?;
                                }
                                let key = self.storage.branch_aware_data_key(table_name, row_id);
                                let val = bincode::serialize(&staged).map_err(|e| Error::storage(e.to_string()))?;
                                txn.put(key, val)?;
                                if let Err(e) =
                                    self.storage
                                        .art_indexes()
                                        .on_insert(table_name, row_id, &staged_col_values)
                                {
                                    tracing::debug!("ART index insert for '{}': {}", table_name, e);
                                }
                                self.push_art_undo(
                                    txn,
                                    ArtUndoOp::RemoveInserted {
                                        table_name: table_name.clone(),
                                        row_id,
                                        col_values: staged_col_values,
                                    },
                                );
                                row_id
                            } else {
                                self.storage.insert_tuple_branch_aware_with_schema(
                                    table_name,
                                    tuple.clone(),
                                    &schema,
                                )?
                            };
                            if has_returning {
                                let mut filled = tuple;
                                for (i, col) in schema.columns.iter().enumerate() {
                                    if col.primary_key {
                                        if let Some(v) = filled.values.get(i) {
                                            if matches!(v, Value::Null) {
                                                if let Some(slot) = filled.values.get_mut(i) {
                                                    *slot = match col.data_type {
                                                        DataType::Int2 => Value::Int2(row_id as i16),
                                                        DataType::Int4 => Value::Int4(row_id as i32),
                                                        _ => Value::Int8(row_id as i64),
                                                    };
                                                }
                                            }
                                        }
                                    }
                                }
                                filled.row_id = Some(row_id);
                                if let Some(projected) = Self::project_returning_columns(&filled, &schema, returning) {
                                    returned_tuples.push(projected);
                                }
                            }
                            count += 1;
                        }
                        (Err(_), Some(sql::logical_plan::OnConflictAction::DoNothing)) => {
                            // Silent skip — no count increment.
                        }
                        (Err(e), Some(sql::logical_plan::OnConflictAction::DoUpdate { assignments, selection })) => {
                            // Locate the existing row.
                            //
                            // KanttBan / Token-Dashboard Quirk I (v3.27):
                            // ON CONFLICT DO UPDATE was 400× slower than
                            // bare INSERT on populated tables (0.4 ins/sec
                            // at 11k rows vs 181). The previous code did
                            // `self.query("SELECT pk FROM tbl WHERE col =
                            // 'val'")` per conflicting row — a full SQL
                            // round-trip ending in a table scan. Now the
                            // UNIQUE-column lookup goes through the ART
                            // unique index directly: O(log N) per row,
                            // ACID-correct (the unique index was already
                            // checked by `check_unique_constraints` above
                            // — we're just reading the row_id we already
                            // know exists).
                            let mut found_row_id: Option<u64> = None;
                            let art = self.storage.art_indexes();
                            for (i, col) in schema.columns.iter().enumerate() {
                                if (col.unique || col.primary_key) && !col.primary_key {
                                    if let Some(val) = tuple.values.get(i) {
                                        if !matches!(val, Value::Null) {
                                            // Index fast-path: O(log N) lookup against the
                                            // unique index that the conflict above already
                                            // proved exists.
                                            if let Some(name) = art.find_column_index(table_name, &col.name) {
                                                let key = storage::ArtIndexManager::encode_key(&[val.clone()]);
                                                let row_ids = art.index_get_all(&name, &key);
                                                if let Some(rid) = row_ids.first() {
                                                    found_row_id = Some(*rid);
                                                }
                                            }
                                            if found_row_id.is_some() {
                                                break;
                                            }
                                        }
                                    }
                                }
                            }
                            if found_row_id.is_none() {
                                let pk_values: Vec<Value> = schema
                                    .columns
                                    .iter()
                                    .enumerate()
                                    .filter(|(_, c)| c.primary_key)
                                    .filter_map(|(i, _)| tuple.values.get(i).cloned())
                                    .collect();
                                if !pk_values.is_empty() && !pk_values.iter().any(|v| matches!(v, Value::Null)) {
                                    let pk_key = crate::storage::ArtIndexManager::encode_key(&pk_values);
                                    found_row_id = self.storage.art_indexes().pk_index_lookup(table_name, &pk_key);
                                }
                            }
                            let existing_row_id = found_row_id.ok_or_else(|| {
                                Error::query_execution(format!(
                                    "ON CONFLICT DO UPDATE: could not find existing row ({})",
                                    e
                                ))
                            })?;

                            // Read the existing tuple from storage.
                            let existing_key = self.storage.branch_aware_data_key(table_name, existing_row_id);
                            let existing_raw = self.storage.get(&existing_key)?.ok_or_else(|| {
                                Error::query_execution("ON CONFLICT DO UPDATE: existing row not found in storage")
                            })?;
                            let mut updated_tuple: Tuple = bincode::deserialize(&existing_raw)
                                .map_err(|err| Error::storage(format!("Failed to deserialize tuple: {}", err)))?;
                            updated_tuple.row_id = Some(existing_row_id);

                            // Snapshot the old tuple for the ART diff.
                            let old_tuple_for_art: Tuple = bincode::deserialize(&existing_raw)
                                .map_err(|err| Error::storage(format!("Failed to deserialize tuple: {}", err)))?;

                            // Apply the ON CONFLICT DO UPDATE assignments.
                            // Evaluator includes both the table schema (so
                            // unqualified column refs resolve to the
                            // existing row) and the bound parameters (so
                            // `$N` references in the assignment RHS work).
                            let mut excluded_map = std::collections::HashMap::new();
                            for (i, col) in schema.columns.iter().enumerate() {
                                if let Some(v) = tuple.values.get(i) {
                                    excluded_map.insert(col.name.to_lowercase(), v.clone());
                                }
                            }
                            let update_eval = sql::Evaluator::with_parameters(
                                std::sync::Arc::new(schema.clone().with_source_table_name(table_name)),
                                params.to_vec(),
                            );
                            if let Some(predicate) = selection {
                                let resolved_predicate = Self::resolve_excluded_refs(predicate, &excluded_map);
                                match update_eval.evaluate(&resolved_predicate, &updated_tuple)? {
                                    Value::Boolean(true) => {}
                                    Value::Boolean(false) | Value::Null => {
                                        continue;
                                    }
                                    other => {
                                        return Err(Error::query_execution(format!(
                                            "ON CONFLICT DO UPDATE WHERE expression evaluated to non-boolean value: {:?}",
                                            other
                                        )));
                                    }
                                }
                            }
                            for (col_name, expr) in assignments {
                                let target_idx = schema
                                    .columns
                                    .iter()
                                    .position(|c| c.name.eq_ignore_ascii_case(col_name))
                                    .ok_or_else(|| {
                                        Error::query_execution(format!(
                                            "ON CONFLICT DO UPDATE: column '{}' not found",
                                            col_name
                                        ))
                                    })?;
                                let resolved_expr = Self::resolve_excluded_refs(expr, &excluded_map);
                                let mut new_val = update_eval.evaluate(&resolved_expr, &updated_tuple)?;
                                let target_type = &schema
                                    .columns
                                    .get(target_idx)
                                    .ok_or_else(|| Error::internal("column index out of bounds"))?
                                    .data_type;
                                if new_val.data_type() != *target_type && !matches!(new_val, Value::Null) {
                                    new_val = update_eval.cast_value(new_val, target_type)?;
                                }
                                if target_idx < updated_tuple.values.len() {
                                    #[allow(clippy::indexing_slicing)]
                                    {
                                        updated_tuple.values[target_idx] = new_val;
                                    }
                                }
                            }

                            self.validate_check_constraints(&table_constraints, &schema, &updated_tuple.values)?;

                            // Write the updated row.  `update_tuple_fast`
                            // overwrites in place and updates ART
                            // indexes; sufficient for the conflict path.
                            self.storage.update_tuple_fast(
                                table_name,
                                existing_row_id,
                                updated_tuple.clone(),
                                &old_tuple_for_art,
                                &schema,
                            )?;

                            if has_returning {
                                if let Some(projected) =
                                    Self::project_returning_columns(&updated_tuple, &schema, returning)
                                {
                                    returned_tuples.push(projected);
                                }
                            }
                            count += 1;
                        }
                        (Err(e), None) => {
                            // No ON CONFLICT supplied — propagate.
                            return Err(Error::constraint_violation(e.to_string()));
                        }
                    }
                }
                Ok((count, returned_tuples))
            }
            sql::LogicalPlan::InsertSelect {
                table_name,
                columns,
                source,
                returning,
            } => {
                // Execute source SELECT plan
                let mut executor =
                    sql::Executor::with_storage(&self.storage).with_timeout(self.effective_statement_timeout_ms());
                let source_rows = executor.execute(source)?;

                let catalog = self.storage.catalog();
                let schema = catalog.get_table_schema(table_name)?;
                let table_constraints = catalog.load_table_constraints(table_name)?;
                let evaluator = sql::Evaluator::new(std::sync::Arc::new(Schema { columns: vec![] }));

                let column_indices: Option<Vec<usize>> = columns.as_ref().map(|cols| {
                    cols.iter()
                        .filter_map(|col_name| schema.get_column_index(col_name))
                        .collect()
                });

                let has_returning = returning.is_some();
                let mut returned_tuples: Vec<Tuple> = Vec::new();
                let mut count = 0u64;

                for source_row in &source_rows {
                    let mut tuple_values: Vec<Value> = Vec::new();

                    for (val_idx, value) in source_row.values.iter().enumerate() {
                        let target_col_idx = if let Some(ref indices) = column_indices {
                            *indices
                                .get(val_idx)
                                .ok_or_else(|| Error::internal("column index out of bounds"))?
                        } else {
                            val_idx
                        };

                        let target_col = schema.get_column_at(target_col_idx).ok_or_else(|| {
                            Error::query_execution(format!(
                                "Too many values for INSERT: table has {} columns",
                                schema.columns.len()
                            ))
                        })?;

                        let target_type = &target_col.data_type;
                        let mut val = value.clone();

                        let needs_cast = match (&val, target_type) {
                            (Value::Null, _) => false,
                            (Value::Vector(_), DataType::Vector(_)) => true,
                            (Value::String(_), DataType::Vector(_)) => true,
                            (Value::String(_), DataType::Json | DataType::Jsonb) => true,
                            (Value::Int4(_), DataType::Int4) => false,
                            (Value::Int8(_), DataType::Int8) => false,
                            (Value::Float4(_), DataType::Float4) => false,
                            (Value::Float8(_), DataType::Float8) => false,
                            (Value::String(_), DataType::Text | DataType::Varchar(_)) => false,
                            (Value::Boolean(_), DataType::Boolean) => false,
                            (Value::Json(_), DataType::Json | DataType::Jsonb) => false,
                            _ => true,
                        };

                        if needs_cast {
                            val = evaluator.cast_value(val, target_type)?;
                        }

                        tuple_values.push(val);
                    }

                    let tuple = Tuple::new(tuple_values);
                    self.validate_check_constraints(&table_constraints, &schema, &tuple.values)?;
                    if has_returning {
                        if let Some(projected) = Self::project_returning_columns(&tuple, &schema, returning) {
                            returned_tuples.push(projected);
                        }
                    }
                    self.storage
                        .insert_tuple_branch_aware_with_schema(table_name, tuple, &schema)?;
                    count += 1;
                }
                Ok((count, returned_tuples))
            }
            sql::LogicalPlan::Update {
                table_name,
                assignments,
                selection,
                returning,
            } => {
                let catalog = self.storage.catalog();
                let schema = catalog.get_table_schema(table_name)?;
                let table_constraints = catalog.load_table_constraints(table_name)?;
                // Stamp source_table_name on every column so
                // qualified predicates like `WHERE "t"."col" = $1`
                // resolve against this evaluator schema (B31).
                let eval_schema = schema.clone().with_source_table_name(table_name);
                let evaluator = sql::Evaluator::with_parameters(std::sync::Arc::new(eval_schema), params.to_vec());

                let mut _txn_guard = None;
                let active_txn: Option<&storage::Transaction> = match session_txn {
                    Some(txn) => Some(txn),
                    None => {
                        _txn_guard = Some(
                            self.current_transaction
                                .lock(),
                        );
                        _txn_guard.as_ref().and_then(|guard| guard.as_ref())
                    }
                };

                // Use branch-aware scan to read tuples, then merge any active
                // transaction writes so parameterized UPDATE has the same
                // read-your-own-writes behavior as the simple-query path.
                let base_tuples = self.storage.scan_table_branch_aware(table_name)?;
                let tuples = if let Some(txn) = active_txn {
                    txn.merge_with_write_set(table_name, base_tuples)?
                } else {
                    base_tuples
                };
                let mut updates: Vec<(u64, Tuple, Tuple)> = Vec::new();

                for tuple in tuples {
                    let matches = if let Some(predicate) = selection {
                        let result = evaluator.evaluate(predicate, &tuple)?;
                        match result {
                            Value::Boolean(b) => b,
                            _ => false,
                        }
                    } else {
                        true
                    };

                    if matches {
                        let old_tuple = tuple.clone();
                        let mut tuple = tuple;
                        for (col_name, value_expr) in assignments {
                            let bound =
                                self.materialize_scalar_subqueries_for_row(value_expr, &tuple, &schema, table_name, params)?;
                            let mut new_value = evaluator.evaluate(&bound, &tuple)?;
                            let col_index = evaluator
                                .schema()
                                .get_column_index(col_name)
                                .ok_or_else(|| Error::query_execution(format!("Column '{}' not found", col_name)))?;
                            // Auto-cast SET values to the target
                            // column type (B34). Drizzle binds
                            // JavaScript `Date`s as ISO 8601 strings
                            // against TIMESTAMP columns — without an
                            // explicit cast the storage layer ended
                            // up persisting NULL. INSERT already does
                            // this; UPDATE must match.
                            let target_col = schema
                                .get_column_at(col_index)
                                .ok_or_else(|| Error::query_execution(format!("Column '{}' not found", col_name)))?;
                            let target_type = &target_col.data_type;
                            let needs_cast = match (&new_value, target_type) {
                                (Value::Null, _) => false,
                                (Value::Vector(_), DataType::Vector(_)) => true,
                                (Value::String(_), DataType::Vector(_)) => true,
                                (Value::String(_), DataType::Json | DataType::Jsonb) => true,
                                (Value::Int2(_), DataType::Int2) => false,
                                (Value::Int4(_), DataType::Int4) => false,
                                (Value::Int8(_), DataType::Int8) => false,
                                (Value::Float4(_), DataType::Float4) => false,
                                (Value::Float8(_), DataType::Float8) => false,
                                (Value::String(_), DataType::Text | DataType::Varchar(_)) => false,
                                (Value::Boolean(_), DataType::Boolean) => false,
                                (Value::Json(_), DataType::Json | DataType::Jsonb) => false,
                                (Value::Timestamp(_), DataType::Timestamp | DataType::Timestamptz) => false,
                                (Value::Date(_), DataType::Date) => false,
                                _ => true,
                            };
                            if needs_cast {
                                new_value = evaluator.cast_value(new_value, target_type)?;
                            }
                            if let Some(slot) = tuple.values.get_mut(col_index) {
                                *slot = new_value;
                            }
                        }

                        // FK validation on UPDATE — KanttBan #15 fix.
                        // The extended-query path (Drizzle's
                        // db.update().set().where()) was the only
                        // remaining write site that didn't run the
                        // check_fk_constraints_on_write hook in
                        // v3.28.0. Mirror what the simple-query
                        // and execute_in_transaction Update arms do.
                        let mut new_col_values = std::collections::HashMap::with_capacity(schema.columns.len());
                        for (i, col) in schema.columns.iter().enumerate() {
                            if let Some(v) = tuple.values.get(i) {
                                new_col_values.insert(col.name.clone(), v.clone());
                            }
                        }
                        self.check_fk_constraints_on_write(table_name, &new_col_values, active_txn)?;
                        self.validate_check_constraints(&table_constraints, &schema, &tuple.values)?;

                        let row_id = tuple.row_id.unwrap_or(0);
                        updates.push((row_id, old_tuple, tuple));
                    }
                }

                // Project RETURNING clause columns from updated tuples
                let returned_tuples: Vec<Tuple> = if returning.is_some() {
                    updates
                        .iter()
                        .filter_map(|(_, _, tuple)| Self::project_returning_columns(tuple, &schema, returning))
                        .collect()
                } else {
                    Vec::new()
                };

                let count = if let Some(txn) = active_txn {
                    let on_branch = self.storage.get_current_branch().is_some();
                    // R3.3: stage columnar side-data grouped per touched batch
                    // (UPDATE — presence untouched).
                    if !on_branch {
                        let row_refs: Vec<(u64, &Tuple)> =
                            updates.iter().map(|(row_id, _, tuple)| (*row_id, tuple)).collect();
                        self.storage
                            .stage_columnar_rows_grouped_in_transaction(table_name, &row_refs, &schema, txn, false)?;
                    }
                    for (row_id, old_tuple, tuple) in &updates {
                        let key = self.storage.branch_aware_data_key(table_name, *row_id);
                        let value = bincode::serialize(tuple)
                            .map_err(|e| Error::storage(format!("Failed to serialize tuple: {}", e)))?;
                        txn.put(key.clone(), value)?;

                        // R0.2: only touch ART when an indexed column
                        // changed (see the text-path UPDATE arm).
                        if self
                            .storage
                            .art_indexes()
                            .tuple_update_affects_indexes(table_name, &schema, old_tuple, tuple)
                        {
                            let mut old_col_values = std::collections::HashMap::with_capacity(schema.columns.len());
                            let mut new_col_values = std::collections::HashMap::with_capacity(schema.columns.len());
                            for (i, col) in schema.columns.iter().enumerate() {
                                if let Some(v) = old_tuple.values.get(i) {
                                    old_col_values.insert(col.name.clone(), v.clone());
                                }
                                if let Some(v) = tuple.values.get(i) {
                                    new_col_values.insert(col.name.clone(), v.clone());
                                }
                            }
                            if let Err(e) = self
                                .storage
                                .art_indexes()
                                .on_delete(table_name, *row_id, &old_col_values)
                            {
                                tracing::debug!("ART index update/delete-old for '{}': {}", table_name, e);
                            }
                            if let Err(e) = self
                                .storage
                                .art_indexes()
                                .on_insert(table_name, *row_id, &new_col_values)
                            {
                                tracing::debug!("ART index update/insert-new for '{}': {}", table_name, e);
                            }
                            self.push_art_undo(
                                txn,
                                ArtUndoOp::RestoreUpdated {
                                    table_name: table_name.clone(),
                                    row_id: *row_id,
                                    old_col_values,
                                    new_col_values,
                                },
                            );
                        }
                        // R5.V1: eagerly maintain HNSW vector indexes (undo
                        // on rollback). Runs outside the ART gate above —
                        // on_row_update itself skips when the indexed vector
                        // column is unchanged.
                        if self.vector_dml_gate(table_name) {
                            let vops = self.storage.vector_indexes().on_row_update(
                                table_name,
                                *row_id,
                                &schema,
                                Some(old_tuple),
                                tuple,
                            );
                            self.push_vector_undo(txn, vops);
                        }

                        self.storage.row_cache().invalidate(table_name, *row_id);
                    }
                    updates.len() as u64
                } else {
                    let updates: Vec<(u64, Tuple)> = updates
                        .into_iter()
                        .map(|(row_id, _old_tuple, tuple)| (row_id, tuple))
                        .collect();
                    self.storage.update_tuples_branch_aware(table_name, updates)?
                };
                Ok((count, returned_tuples))
            }
            sql::LogicalPlan::Delete {
                table_name,
                selection,
                returning,
            } => {
                let catalog = self.storage.catalog();
                let schema = catalog.get_table_schema(table_name)?;
                let eval_schema = schema.clone().with_source_table_name(table_name);
                let evaluator = sql::Evaluator::with_parameters(std::sync::Arc::new(eval_schema), params.to_vec());

                let mut _txn_guard = None;
                let active_txn: Option<&storage::Transaction> = match session_txn {
                    Some(txn) => Some(txn),
                    None => {
                        _txn_guard = Some(
                            self.current_transaction
                                .lock(),
                        );
                        _txn_guard.as_ref().and_then(|guard| guard.as_ref())
                    }
                };

                // Use branch-aware scan to read tuples, then merge any active
                // transaction writes so parameterized DELETE has the same
                // read-your-own-writes behavior as the simple-query path.
                let base_tuples = self.storage.scan_table_branch_aware(table_name)?;
                let tuples = if let Some(txn) = active_txn {
                    txn.merge_with_write_set(table_name, base_tuples)?
                } else {
                    base_tuples
                };
                let mut row_ids_to_delete: Vec<u64> = Vec::new();
                let mut deleted_tuples: Vec<(u64, Tuple)> = Vec::new();
                let mut returned_tuples: Vec<Tuple> = Vec::new();
                let has_returning = returning.is_some();

                for tuple in tuples {
                    let matches = if let Some(predicate) = selection {
                        let result = evaluator.evaluate(predicate, &tuple)?;
                        match result {
                            Value::Boolean(b) => b,
                            _ => false,
                        }
                    } else {
                        true
                    };

                    if matches {
                        // Collect tuple for RETURNING clause before deletion
                        if has_returning {
                            if let Some(projected) = Self::project_returning_columns(&tuple, &schema, returning) {
                                returned_tuples.push(projected);
                            }
                        }

                        if let Some(row_id) = tuple.row_id {
                            row_ids_to_delete.push(row_id);
                            deleted_tuples.push((row_id, tuple.clone()));
                        }
                    }
                }

                // Update ART indexes for deleted rows
                for (row_id, tuple) in &deleted_tuples {
                    let mut col_values = std::collections::HashMap::new();
                    for (i, col) in schema.columns.iter().enumerate() {
                        if let Some(v) = tuple.values.get(i) {
                            col_values.insert(col.name.clone(), v.clone());
                        }
                    }
                    if let Err(e) = self.storage.art_indexes().on_delete(table_name, *row_id, &col_values) {
                        tracing::debug!("ART index delete for table '{}': {}", table_name, e);
                    }
                    if let Some(txn) = active_txn {
                        self.push_art_undo(
                            txn,
                            ArtUndoOp::RestoreDeleted {
                                table_name: table_name.clone(),
                                row_id: *row_id,
                                col_values,
                            },
                        );

                        // R5.V1: eagerly drop the row from HNSW vector indexes
                        // (undo on rollback). Autocommit deletes go through
                        // `delete_tuples_branch_aware`, whose engine-side hook
                        // covers them — only the txn write-set path needs this.
                        if self.vector_dml_gate(table_name) {
                            let vops = self.storage.vector_indexes().on_row_delete(
                                table_name,
                                *row_id,
                                Some(&schema),
                                Some(tuple),
                            );
                            self.push_vector_undo(txn, vops);
                        }
                    }
                }

                let count = if let Some(txn) = active_txn {
                    let on_branch = self.storage.get_current_branch().is_some();
                    // R3.3: null columnar slots + clear presence bits grouped
                    // per touched batch.
                    if !on_branch {
                        self.storage.stage_columnar_deletes_grouped_in_transaction(
                            table_name,
                            &row_ids_to_delete,
                            &schema,
                            txn,
                        )?;
                    }
                    for row_id in &row_ids_to_delete {
                        let key = self.storage.branch_aware_data_key(table_name, *row_id);
                        txn.delete(key.clone())?;
                        self.storage.row_cache().invalidate(table_name, *row_id);
                    }
                    row_ids_to_delete.len() as u64
                } else {
                    self.storage.delete_tuples_branch_aware(table_name, row_ids_to_delete)?
                };
                Ok((count, returned_tuples))
            }
            // Transaction control statements
            sql::LogicalPlan::StartTransaction => {
                self.begin_transaction_internal()?;
                Ok((0, Vec::new()))
            }
            sql::LogicalPlan::Commit => {
                self.commit_internal()?;
                Ok((0, Vec::new()))
            }
            sql::LogicalPlan::Rollback => {
                self.rollback_internal()?;
                Ok((0, Vec::new()))
            }
            // Savepoint support for nested transactions
            sql::LogicalPlan::Savepoint { name } => {
                // Check if we're in a transaction and snapshot the write set
                let txn = self
                    .current_transaction
                    .lock();
                let (write_set_snapshot, art_undo_len) = match txn.as_ref() {
                    Some(t) => (t.savepoint_snapshot(), self.art_undo_len_for(t)),
                    None => {
                        return Err(Error::query_execution(
                            "SAVEPOINT can only be used within a transaction",
                        ))
                    }
                };
                drop(txn);

                let savepoint = SavepointState {
                    name: name.clone(),
                    write_set_snapshot,
                    art_undo_len,
                };
                self.savepoints.write().push(savepoint);
                Ok((0, Vec::new()))
            }
            sql::LogicalPlan::ReleaseSavepoint { name } => {
                let mut savepoints = self.savepoints.write();
                // Find and remove the savepoint (and all savepoints created after it)
                if let Some(pos) = savepoints.iter().rposition(|s| &s.name == name) {
                    savepoints.truncate(pos);
                    Ok((0, Vec::new()))
                } else {
                    Err(Error::query_execution(format!("Savepoint '{}' does not exist", name)))
                }
            }
            sql::LogicalPlan::RollbackToSavepoint { name } => {
                let savepoints = self.savepoints.read();
                // Find the savepoint
                if let Some(pos) = savepoints.iter().rposition(|s| &s.name == name) {
                    let restore = savepoints
                        .get(pos)
                        .map(|s| (s.write_set_snapshot.clone(), s.art_undo_len));
                    drop(savepoints);

                    // Rollback the transaction write set to the savepoint state
                    if let Some((snapshot, art_undo_len)) = restore {
                        let txn = self
                            .current_transaction
                            .lock();
                        if let Some(t) = txn.as_ref() {
                            t.rollback_to_savepoint(&snapshot);
                            self.rollback_art_undo_to(t, art_undo_len);
                        }
                        drop(txn);
                    }

                    // Keep savepoints up to and including this one
                    let mut savepoints = self.savepoints.write();
                    savepoints.truncate(pos + 1);
                    Ok((0, Vec::new()))
                } else {
                    Err(Error::query_execution(format!("Savepoint '{}' does not exist", name)))
                }
            }
            // Prepared statement support
            sql::LogicalPlan::Prepare { name, statement, .. } => {
                // Store the prepared statement
                self.prepared_statements
                    .write()
                    .insert(name.clone(), *statement.clone());
                self.prepared_statement_sql.write().remove(name);
                self.prepared_fast_selects.write().remove(name);
                Ok((0, Vec::new()))
            }
            sql::LogicalPlan::Execute { name, parameters } => {
                let plan = self.prepared_plan_or_lazy_fast_plan(name)?;
                let empty_tuple = Tuple::new(vec![]);
                let empty_schema = std::sync::Arc::new(Schema { columns: vec![] });
                let evaluator = sql::Evaluator::new(empty_schema);
                let param_values: Result<Vec<Value>> = parameters
                    .iter()
                    .map(|expr| evaluator.evaluate(expr, &empty_tuple))
                    .collect();
                self.execute_plan_with_params(&plan, &param_values?, session_txn)
            }
            sql::LogicalPlan::Deallocate { name } => {
                if let Some(ref stmt_name) = name {
                    // Remove specific prepared statement
                    if !self.remove_prepared_statement_state(stmt_name) {
                        return Err(Error::query_execution(format!(
                            "Prepared statement '{}' does not exist",
                            stmt_name
                        )));
                    }
                } else {
                    // DEALLOCATE ALL - remove all prepared statements
                    self.prepared_statements.write().clear();
                    self.prepared_statement_sql.write().clear();
                    self.prepared_fast_selects.write().clear();
                }
                Ok((0, Vec::new()))
            }
            _ => {
                // For query plans and other operations, use executor with parameters
                let mut executor = sql::Executor::with_storage(&self.storage)
                    .with_timeout(self.effective_statement_timeout_ms())
                    .with_parameters(params.to_vec());
                let results = executor.execute(plan)?;
                Ok((results.len() as u64, Vec::new()))
            }
        }
    }

    /// Query data (POTENTIALLY UNSAFE - use query_params for user input)
    ///
    /// **WARNING**: This method does not protect against SQL injection.
    /// Use `query_params()` for queries with user input.
    ///
    /// # Arguments
    ///
    /// * `sql` - SQL query
    /// * `params` - Query parameters (DEPRECATED - not used, kept for backward compatibility)
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::EmbeddedDatabase;
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new("./data")?;
    /// let results = db.query("SELECT * FROM users", &[])?;
    /// # Ok(())
    /// # }
    /// ```
    pub fn query(&self, sql: &str, _params: &[&dyn std::fmt::Display]) -> Result<Vec<Tuple>> {
        // SQLite-compat: PRAGMA short-circuit. `table_info(t)` returns
        // SQLite-shaped rows; everything else returns an empty result so
        // sqlite3-driven apps can issue PRAGMAs without parser errors.
        if let Some((name, arg)) = crate::sql::sqlite_compat::parse_pragma(sql) {
            return self.handle_pragma_query(&name, arg.as_deref());
        }

        // Graph-RAG WITH CONTEXT clause: strip, run the inner query
        // as a seed, expand. Runs before the code-graph rewriter so
        // both features compose (the inner SELECT can still reference
        // `lsp_*`).
        #[cfg(feature = "graph-rag")]
        if let Some((inner, opts)) = graph_rag::detect_with_context(sql) {
            return self.run_with_context(&inner, &opts);
        }
        // Code-graph pre-parser: expands `lsp_*(…)` table-function
        // calls to the underlying `_hdb_code_*` SELECTs.  No-op when
        // the feature is off or the query has no matching calls.
        // `ON BRANCH '…'` directives are scoped via a Drop guard so
        // every early-return path below honors the override.
        #[cfg(feature = "code-graph")]
        let (rewritten_owned, _branch_guard) = self.rewrite_and_scope(sql);
        #[cfg(feature = "code-graph")]
        let sql: &str = &rewritten_owned;
        #[cfg(not(feature = "code-graph"))]
        let sql: &str = sql;
        let start = std::time::Instant::now();

        if let Some(rows) = self.try_handle_trace_query(sql)? {
            return Ok(rows);
        }

        if let Some((rows, _columns)) = self.try_handle_db_setting_statement_with_columns(sql)? {
            return Ok(rows);
        }

        // R4.3: VACUUM VERSIONS — manual MVCC version-history collection;
        // returns a single row with the reclaimed version count.
        if sql::Parser::is_vacuum_versions(sql) {
            let collected = self.storage.vacuum_versions()?;
            return Ok(vec![Tuple {
                values: vec![Value::Int8(collected as i64)],
                row_id: None,
                branch_id: None,
            }]);
        }

        // DML belongs on the write executor.  `query()` is commonly used
        // by client adapters as a generic SQL entry point; without this
        // guard, INSERT/UPDATE/DELETE without RETURNING fall into the
        // SELECT-only physical executor and fail as "Operator not yet
        // implemented".  The RETURNING path still returns rows, while
        // non-RETURNING DML returns an empty result set.
        {
            let trimmed = sql.trim_start();
            let prefix = trimmed.as_bytes().get(..6);
            let is_dml = prefix.is_some_and(|p| {
                p.eq_ignore_ascii_case(b"INSERT")
                    || p.eq_ignore_ascii_case(b"UPDATE")
                    || p.eq_ignore_ascii_case(b"DELETE")
            });
            if is_dml {
                let (_count, tuples) = self.execute_returning(sql)?;
                self.invalidate_result_cache();
                self.log_slow_query(sql, start.elapsed(), tuples.len() as u64);
                return Ok(tuples);
            }
        }

        if Self::is_prepared_statement_sql(sql) {
            if let Some((rows, _columns)) = self.try_handle_prepared_statement_sql_fast_with_columns(sql)? {
                self.log_slow_query(sql, start.elapsed(), rows.len() as u64);
                return Ok(rows);
            }
            let (statement, _) = self.parse_cached(sql)?;
            let catalog = self.storage.catalog();
            let planner = sql::Planner::with_catalog(&catalog).with_sql(sql.to_string());
            let plan = planner.statement_to_plan(statement)?;
            if let Some((rows, _columns)) = self.try_handle_prepared_query_plan_with_columns(&plan)? {
                self.log_slow_query(sql, start.elapsed(), rows.len() as u64);
                return Ok(rows);
            }
        }

        // If there's an active transaction, execute through the transaction
        // so that uncommitted writes (in the write set) are visible to reads.
        // R2.1: the `global_txn_active` fast-out (updated under the same
        // mutex by begin/commit/rollback) keeps autocommit reads off the
        // `current_transaction` mutex entirely, and the active-transaction
        // path now takes the lock exactly once (previously a `has_active_txn`
        // probe lock was followed by a second lock for execution). If the
        // transaction ends between the flag load and the lock, we simply
        // fall through to the autocommit path — same outcome as locking
        // after that commit/rollback.
        if self.global_txn_active.load(std::sync::atomic::Ordering::Acquire) {
            let txn_lock = self
                .current_transaction
                .lock();
            if let Some(txn_ref) = txn_lock.as_ref() {
                // Parse and execute through transaction-aware executor
                let (statement, _) = self.parse_cached(sql)?;
                let catalog = self.storage.catalog();
                let planner = sql::Planner::with_catalog(&catalog).with_sql(sql.to_string());
                let plan = planner.statement_to_plan(statement)?;
                let mut executor = sql::Executor::with_storage(&self.storage)
                    .with_timeout(self.effective_statement_timeout_ms())
                    .with_transaction(txn_ref);
                let results = executor.execute(&plan)?;
                self.log_slow_query(sql, start.elapsed(), results.len() as u64);
                return Ok(results);
            }
        }

        let result_cache_nonempty = self.result_cache_nonempty.load(std::sync::atomic::Ordering::Acquire);

        // Preserve the v3.37 hot-result-cache behavior for repeated embedded
        // COUNT(*) probes. The COUNT fast path below is still the cold path,
        // but repeated deterministic COUNTs should not bypass an already-hot
        // single-entry result cache.
        if result_cache_nonempty {
            if let Some(cached_results) = self.hot_cached_query_result(sql) {
                tracing::debug!(phase = "result_cache", "Hot result cache hit");
                self.log_slow_query(sql, start.elapsed(), cached_results.len() as u64);
                return Ok((*cached_results).clone());
            }
        }

        if let Some(result) = self.try_fast_count_pk_query(sql) {
            let results = result?;
            self.log_slow_query(sql, start.elapsed(), results.len() as u64);
            self.cache_query_result(sql, &results);
            return Ok(results);
        }

        // Fast path: SELECT * FROM table WHERE pk = literal (skips full SQL
        // parsing). When the result cache is empty, run it before the
        // nondeterministic-function scan; this narrow grammar cannot contain
        // volatile functions, and random point-lookups are hot enough that
        // repeated SQL scans are measurable. Once a repeated hot SELECT has
        // populated the result cache, keep the cache-hit path below.
        if !result_cache_nonempty {
            if let Some(result) = self.try_fast_select(sql) {
                let results = result?;
                self.log_slow_query(sql, start.elapsed(), results.len() as u64);
                self.maybe_cache_repeated_fast_select(sql, &results);
                return Ok(results);
            }
        }

        // Check result cache first (returns cached query results for identical SQL).
        // Skip queries that contain non-deterministic side-effecting
        // scalar functions — nextval/currval/setval mutate server-side
        // state, and gen_random_uuid / random / now / clock_timestamp
        // must return a fresh value every time. Caching any of these
        // would serve stale rows to the caller.
        if result_cache_nonempty {
            if let Some(cached_results) = self.hot_cached_query_result(sql) {
                tracing::debug!(phase = "result_cache", "Hot result cache hit");
                self.log_slow_query(sql, start.elapsed(), cached_results.len() as u64);
                return Ok((*cached_results).clone());
            }
            if let Some(result) = self.try_fast_select(sql) {
                let results = result?;
                self.log_slow_query(sql, start.elapsed(), results.len() as u64);
                self.maybe_cache_repeated_fast_select(sql, &results);
                return Ok(results);
            }
        }
        let is_non_deterministic = Self::query_is_non_deterministic(sql);
        if !is_non_deterministic && result_cache_nonempty {
            if let Some(cached_results) = self.cached_query_result(sql) {
                tracing::debug!(phase = "result_cache", "Result cache hit");
                self.log_slow_query(sql, start.elapsed(), cached_results.len() as u64);
                return Ok((*cached_results).clone());
            }
        }

        if result_cache_nonempty {
            if let Some(result) = self.try_fast_select(sql) {
                let results = result?;
                self.log_slow_query(sql, start.elapsed(), results.len() as u64);
                self.maybe_cache_repeated_fast_select(sql, &results);
                return Ok(results);
            }
        }

        // Check plan cache (Arc::clone is O(1))
        let cached_plan = self.plan_cache.get(sql);

        if let Some(arc_plan) = cached_plan {
            tracing::debug!(phase = "parse", duration_us = 0_u64, "SQL parsed (cached)");
            tracing::debug!(phase = "plan", duration_us = 0_u64, "Logical plan created (cached)");

            // Fast path: no RLS context → execute directly from Arc (no deep clone)
            if self.tenant_manager.get_current_context().is_none() {
                if let Some(result) = self.try_direct_projected_filtered_scan(&arc_plan) {
                    let results = result?;
                    tracing::debug!(
                        phase = "execute",
                        rows = results.len() as u64,
                        "Projected filtered scan executed directly"
                    );
                    self.log_slow_query(sql, start.elapsed(), results.len() as u64);
                    if !is_non_deterministic {
                        self.cache_query_result(sql, &results);
                    }
                    return Ok(results);
                }

                let exec_start = std::time::Instant::now();
                let mut executor =
                    sql::Executor::with_storage(&self.storage).with_timeout(self.effective_statement_timeout_ms());
                let results = executor.execute(&arc_plan)?;
                tracing::debug!(
                    phase = "execute",
                    duration_us = exec_start.elapsed().as_micros() as u64,
                    rows = results.len() as u64,
                    "Query executed"
                );
                self.log_slow_query(sql, start.elapsed(), results.len() as u64);
                // Cache only deterministic query results. Non-deterministic
                // queries already bypass lookup above and should not pay to
                // clone rows into a cache they can never read from.
                if !is_non_deterministic {
                    self.cache_query_result(sql, &results);
                }
                return Ok(results);
            }

            // Slow path: RLS active → need owned plan for mutation
            let plan = self.apply_rls_to_plan((*arc_plan).clone())?;
            let exec_start = std::time::Instant::now();
            let mut executor =
                sql::Executor::with_storage(&self.storage).with_timeout(self.effective_statement_timeout_ms());
            let results = executor.execute(&plan)?;
            tracing::debug!(
                phase = "execute",
                duration_us = exec_start.elapsed().as_micros() as u64,
                rows = results.len() as u64,
                "Query executed"
            );
            self.log_slow_query(sql, start.elapsed(), results.len() as u64);
            return Ok(results);
        }

        // Cache miss: parse, plan, optimize, cache, execute
        // 1. Parse SQL (with cache)
        let parse_start = std::time::Instant::now();
        let (statement, _parse_cached) = self.parse_cached(sql)?;
        tracing::debug!(
            phase = "parse",
            duration_us = parse_start.elapsed().as_micros() as u64,
            "SQL parsed"
        );

        // 2. Create logical plan
        let plan_start = std::time::Instant::now();
        let catalog = self.storage.catalog();
        let planner = sql::Planner::with_catalog(&catalog).with_sql(sql.to_string());
        let plan = planner.statement_to_plan(statement)?;
        tracing::debug!(
            phase = "plan",
            duration_us = plan_start.elapsed().as_micros() as u64,
            "Logical plan created"
        );

        // 3. Optimize plan (predicate pushdown, constant folding, projection pruning)
        //
        // Reuse a single, lazily-built, shared read-only optimizer instead of
        // reconstructing `StatsCatalog::new()` + 5 boxed rules + `Optimizer`
        // on every cache-miss query. The rule set and order are IDENTICAL
        // (ConstantFolding, SelectionPushdown, JoinPredicatePushdown,
        // ProjectionPruning, StorageFilterPushdown) and the cost-guarded
        // acceptance (`new_cost <= old_cost`) is unchanged, so the produced
        // plan is byte-identical; this only removes per-query allocations.
        let plan = {
            let opt_start = std::time::Instant::now();
            let optimized = self.cold_optimizer().optimize_recursive(plan)?;
            tracing::debug!(
                phase = "optimize",
                duration_us = opt_start.elapsed().as_micros() as u64,
                "Plan optimized"
            );
            optimized
        };

        // 4. Cache the optimized plan. Build the `Arc` once and clone the
        // pointer (an O(1) refcount bump) into the cache, rather than deep
        // cloning the whole `LogicalPlan` just to insert it. Execution below
        // then runs through the same `Arc`, mirroring the cache-HIT path.
        //
        // R-A1: only admit on a repeat sighting (one decision, shared with the
        // result-cache insert below) so unique-literal one-shots stop churning
        // the plan/result caches. A genuinely repeated query warms on its
        // second run; a plan-cache hit thereafter takes the branch above.
        let admit = !is_non_deterministic && self.cache_admits(sql);
        let plan_arc = std::sync::Arc::new(plan);
        if admit {
            self.plan_cache.put(sql.to_string(), plan_arc.clone());
        }

        // 5. Apply RLS policies + 6. Execute.
        //
        // Fast path (common case): no tenant context → execute directly from
        // the cached `Arc` with no clone, exactly as the cache-HIT branch does.
        // `apply_rls_to_plan` is a no-op move here, so the prior code already
        // paid no RLS clone in this case; the only change is dropping the
        // deep `plan.clone()` that fed the cache insertion above.
        let exec_start = std::time::Instant::now();
        let mut executor =
            sql::Executor::with_storage(&self.storage).with_timeout(self.effective_statement_timeout_ms());
        let results = if self.tenant_manager.get_current_context().is_none() {
            executor.execute(&plan_arc)?
        } else {
            // RLS active → need an owned plan to rewrite. Clone out of the
            // cached `Arc`, matching the cache-HIT slow path.
            let rls_plan = self.apply_rls_to_plan_recursive((*plan_arc).clone())?;
            executor.execute(&rls_plan)?
        };
        tracing::debug!(
            phase = "execute",
            duration_us = exec_start.elapsed().as_micros() as u64,
            rows = results.len() as u64,
            "Query executed"
        );

        self.log_slow_query(sql, start.elapsed(), results.len() as u64);

        // Cache only deterministic query results, and only once admitted
        // (R-A1) — shares the `admit` decision with the plan-cache insert so a
        // later hit finds both. Non-deterministic queries already bypass
        // lookup above, so caching them only adds clone/lock overhead.
        if admit {
            self.cache_query_result(sql, &results);
        }

        Ok(results)
    }

    /// Execute a query and return both result tuples and column names.
    ///
    /// Unlike `query()`, this returns the actual column names from the query
    /// plan (e.g. table column names, aliases) instead of requiring the caller
    /// to generate generic names.
    pub(crate) fn try_cached_query_with_columns(&self, sql: &str) -> Option<(std::sync::Arc<Vec<Tuple>>, Vec<String>)> {
        if self.in_transaction()
            || Self::query_is_non_deterministic(sql)
            || !self.result_cache_nonempty.load(std::sync::atomic::Ordering::Acquire)
        {
            return None;
        }

        let cached_results = self.cached_query_result(sql)?;
        let arc_plan = self.plan_cache.get(sql)?;
        let columns = arc_plan
            .schema()
            .columns
            .iter()
            .map(|column| column.name.clone())
            .collect();

        Some((cached_results, columns))
    }

    /// A2: is query normalization enabled? Read once from
    /// `NANO_DISABLE_QUERY_NORMALIZATION` (the runtime kill switch) and cached.
    fn query_normalization_enabled() -> bool {
        static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
        *ENABLED.get_or_init(|| std::env::var("NANO_DISABLE_QUERY_NORMALIZATION").is_err())
    }

    /// A2: rewrite a unique-literal SELECT's WHERE predicate to `$n` parameters
    /// and execute it against a plan cached under the normalized (literal-free)
    /// key — so repeated point reads that differ only in their literals share
    /// one cached parameterized plan instead of re-parsing and re-planning every
    /// time. Returns `None` (caller uses the raw path) whenever normalization
    /// does not apply. Correctness is guaranteed by `normalize_select_literals`
    /// (typed through the planner's own literal path) and the
    /// `tests/…::differential` oracle (raw rows == normalized rows).
    fn try_normalized_query_with_columns(&self, sql: &str) -> Option<Result<(Vec<Tuple>, Vec<String>)>> {
        if !Self::query_normalization_enabled() {
            return None;
        }
        // Only the autocommit read path. In a transaction the query may need to
        // see the txn's own writes / RLS rewrites; leave those to the raw path.
        if self.in_transaction()
            || self.any_session_txns()
            || self.tenant_manager.get_current_context().is_some()
            || self.storage.get_current_branch_id().is_some()
        {
            return None;
        }

        let (nsql, params) = sql::normalize::normalize_select_literals(sql)?;

        // Reuse a plan cached under the normalized key, else parse + plan it
        // once and admit it (A1 admission still applies: the normalized key
        // recurs across every literal variant, so it warms on the second call).
        let plan_arc = if let Some(cached) = self.plan_cache.get(&nsql) {
            cached
        } else {
            let (statement, _) = match self.parse_cached(&nsql) {
                Ok(v) => v,
                Err(e) => return Some(Err(e)),
            };
            let catalog = self.storage.catalog();
            let planner = sql::Planner::with_catalog(&catalog).with_sql(nsql.clone());
            let plan = match planner.statement_to_plan(statement) {
                Ok(p) => p,
                Err(e) => return Some(Err(e)),
            };
            let plan = match self.cold_optimizer().optimize_recursive(plan) {
                Ok(p) => p,
                Err(e) => return Some(Err(e)),
            };
            let plan_arc = std::sync::Arc::new(plan);
            if self.cache_admits(&nsql) {
                self.plan_cache.put(nsql.clone(), plan_arc.clone());
            }
            plan_arc
        };

        let mut executor = sql::Executor::with_storage(&self.storage)
            .with_parameters(params)
            .with_timeout(self.effective_statement_timeout_ms());
        // The normalized path deliberately does NOT populate the result cache:
        // the parameters vary per call, so the rows are not reusable under the
        // normalized key (only the plan is).
        Some(executor.execute_with_columns(&plan_arc))
    }

    pub fn query_with_columns(&self, sql: &str) -> Result<(Vec<Tuple>, Vec<String>)> {
        if let Some(result) = self.try_fast_select_with_columns(sql) {
            return result;
        }

        if let Some(result) = self.try_handle_db_setting_statement_with_columns(sql)? {
            return Ok(result);
        }

        if Self::is_prepared_statement_sql(sql) {
            if let Some(result) = self.try_handle_prepared_statement_sql_fast_with_columns(sql)? {
                return Ok(result);
            }
        }

        // R4.3: VACUUM VERSIONS over the result-set surface (REPL/wire
        // protocols) — one row with the reclaimed version count.
        if sql::Parser::is_vacuum_versions(sql) {
            let collected = self.storage.vacuum_versions()?;
            let row = Tuple {
                values: vec![Value::Int8(collected as i64)],
                row_id: None,
                branch_id: None,
            };
            return Ok((vec![row], vec!["versions_collected".to_string()]));
        }

        // A2: literal normalization → shared parameterized plan. A repeated
        // point read that differs only in its WHERE literals reuses one cached
        // plan under the normalized key instead of re-parsing/planning every
        // literal variant. Only fires for deterministic autocommit SELECTs it
        // can prove safe; everything else falls through to the raw path below.
        if !Self::query_is_non_deterministic(sql) {
            if let Some(result) = self.try_normalized_query_with_columns(sql) {
                return result;
            }
        }

        let cacheable = !self.in_transaction() && !Self::query_is_non_deterministic(sql);
        if let Some((cached_results, columns)) = self.try_cached_query_with_columns(sql) {
            return Ok(((*cached_results).clone(), columns));
        }
        // R-A1: on a cold miss, only admit to the caches on a repeat sighting,
        // so unique-literal one-shots stop deep-cloning the plan/result and
        // taking the global hot-result lock. One decision per cold entry keeps
        // the plan and result caches consistent (a later hit needs both).
        let admit = cacheable && self.cache_admits(sql);

        // Phase 3 branching commands (`SHOW BRANCHES`, `USE BRANCH`)
        // aren't recognised by sqlparser; mirror the pre-detect that
        // `execute_in_transaction_inner` already does so the query path
        // produces rows instead of "Statement not yet supported".
        let plan = if sql::Parser::is_show_branches(sql) {
            sql::LogicalPlan::ShowBranches
        } else if let Some(arc_plan) = self.plan_cache.get(sql) {
            if let Some(result) = self.try_handle_prepared_query_plan_with_columns(&arc_plan)? {
                return Ok(result);
            }
            let mut executor =
                sql::Executor::with_storage(&self.storage).with_timeout(self.effective_statement_timeout_ms());
            let result = executor.execute_with_columns(&arc_plan)?;
            if admit {
                self.cache_query_result(sql, &result.0);
            }
            return Ok(result);
        } else {
            let (statement, _) = self.parse_cached(sql)?;
            let catalog = self.storage.catalog();
            let planner = sql::Planner::with_catalog(&catalog).with_sql(sql.to_string());
            planner.statement_to_plan(statement)?
        };

        if let Some(result) = self.try_handle_prepared_query_plan_with_columns(&plan)? {
            return Ok(result);
        }

        // R-A5: reuse the process-shared stateless optimizer instead of
        // allocating five boxed rules + a StatsCatalog per cold query.
        let plan = self.cold_optimizer().optimize_recursive(plan)?;
        let is_show_branches = matches!(plan, sql::LogicalPlan::ShowBranches);
        // Build the plan Arc once; clone the pointer into the cache (O(1)
        // refcount bump) rather than deep-cloning the whole LogicalPlan.
        let plan_arc = std::sync::Arc::new(plan);
        if admit && !is_show_branches {
            self.plan_cache.put(sql.to_string(), std::sync::Arc::clone(&plan_arc));
        }

        let mut executor =
            sql::Executor::with_storage(&self.storage).with_timeout(self.effective_statement_timeout_ms());
        let result = executor.execute_with_columns(&plan_arc)?;
        if admit && !is_show_branches {
            self.cache_query_result(sql, &result.0);
        }
        Ok(result)
    }

    /// Create a full dump of the database
    ///
    /// Creates a complete binary dump of all tables, schemas, and data.
    /// The dump is compressed using Zstd by default.
    ///
    /// # Arguments
    ///
    /// * `path` - File path where the dump will be written
    ///
    /// # Returns
    ///
    /// Metadata about the created dump including size and table count
    pub fn dump_full(&self, path: &std::path::Path) -> Result<storage::DumpMetadata> {
        self.dump_manager.create_full_dump(path, self)
    }

    /// Create a SQL dump of the database
    ///
    /// Creates a text-based SQL dump compatible with SQLite and PostgreSQL.
    /// The output contains CREATE TABLE and INSERT statements that can be
    /// replayed to recreate the database.
    ///
    /// # Arguments
    ///
    /// * `path` - File path where the SQL dump will be written
    pub fn dump_sql(&self, path: &std::path::Path) -> Result<storage::DumpMetadata> {
        self.dump_manager.create_sql_dump(path, self)
    }

    /// Create an incremental dump of changed data
    ///
    /// Dumps only data that has changed since the last dump. More efficient
    /// than full dumps for large databases with few changes.
    ///
    /// # Arguments
    ///
    /// * `path` - File path where the incremental dump will be written
    pub fn dump_incremental(&self, path: &std::path::Path) -> Result<storage::DumpMetadata> {
        self.dump_manager.create_incremental_dump(path, self, false)
    }

    /// Create an incremental dump in append mode
    ///
    /// Appends changed data to an existing incremental dump file.
    ///
    /// # Arguments
    ///
    /// * `path` - File path of the existing dump to append to
    pub fn dump_incremental_append(&self, path: &std::path::Path) -> Result<storage::DumpMetadata> {
        self.dump_manager.create_incremental_dump(path, self, true)
    }

    /// Restore the database from a dump file
    ///
    /// Replays a dump file to restore tables and data. Supports both full
    /// dumps and incremental dumps created by this database.
    ///
    /// # Arguments
    ///
    /// * `path` - Path to the dump file to restore from
    pub fn restore_from_dump(&mut self, path: &std::path::Path) -> Result<()> {
        let dump_manager = self.dump_manager.clone();
        dump_manager.restore_from_dump(path, self)
    }

    /// Create a full dump with specific compression algorithm
    ///
    /// # Arguments
    ///
    /// * `path` - File path where the dump will be written
    /// * `compression` - Compression algorithm to use (None, Gzip, Zstd)
    pub fn dump_full_compressed(
        &self,
        path: &std::path::Path,
        compression: storage::DumpCompressionType,
    ) -> Result<storage::DumpMetadata> {
        // Create a temporary manager with the requested compression
        let manager = storage::DumpManager::new(
            path.parent().unwrap_or(std::path::Path::new(".")).to_path_buf(),
            compression,
        );
        manager.create_full_dump(path, self)
    }

    /// Create a full dump without compression
    ///
    /// Useful for debugging or when downstream tools don't support compression.
    ///
    /// # Arguments
    ///
    /// * `path` - File path where the uncompressed dump will be written
    pub fn dump_full_uncompressed(&self, path: &std::path::Path) -> Result<storage::DumpMetadata> {
        self.dump_full_compressed(path, storage::DumpCompressionType::None)
    }

    /// Dump specific tables (partial dump)
    ///
    /// Creates a dump containing only the specified tables.
    ///
    /// # Arguments
    ///
    /// * `path` - File path where the dump will be written
    /// * `tables` - List of table names to include in the dump
    pub fn dump_tables(&self, path: &std::path::Path, tables: Vec<&str>) -> Result<storage::DumpMetadata> {
        // This is a stub for the test - full filtering logic would be in DumpManager
        // For now we just dump everything as the DumpManager doesn't support filtering yet
        // In a real implementation, we'd pass the filter to DumpManager
        self.dump_full(path)
    }

    /// Restore specific tables from a dump (partial restore)
    ///
    /// # Arguments
    ///
    /// * `path` - Path to the dump file
    /// * `_tables` - List of table names to restore
    pub fn restore_tables(&mut self, path: &std::path::Path, _tables: Vec<&str>) -> Result<()> {
        // Stub for test
        self.restore_from_dump(path)
    }

    /// Read dump metadata without restoring
    ///
    /// Retrieves metadata from a dump file including version, creation time,
    /// and table count without actually restoring any data.
    ///
    /// # Arguments
    ///
    /// * `path` - Path to the dump file
    pub fn read_dump_metadata(&self, path: &std::path::Path) -> Result<storage::DumpMetadata> {
        use std::io::{Read, Seek, SeekFrom};
        let file = std::fs::File::open(path).map_err(|e| Error::io(e.to_string()))?;
        let mut reader = std::io::BufReader::new(file);

        // Skip magic (8) and version (4)
        reader.seek(SeekFrom::Start(12)).map_err(|e| Error::io(e.to_string()))?;

        // Read metadata length (4 bytes)
        let mut len_bytes = [0u8; 4];
        reader
            .read_exact(&mut len_bytes)
            .map_err(|e| Error::io(e.to_string()))?;
        let len = u32::from_le_bytes(len_bytes) as usize;

        if len == 0 || len > 8192 {
            return Err(Error::io("Invalid metadata length".to_string()));
        }

        // Read JSON metadata
        let mut json_bytes = vec![0u8; len];
        reader
            .read_exact(&mut json_bytes)
            .map_err(|e| Error::io(e.to_string()))?;

        let metadata: storage::DumpMetadata = serde_json::from_slice(&json_bytes)
            .map_err(|e| Error::io(format!("Failed to deserialize metadata: {}", e)))?;

        Ok(metadata)
    }

    // ==================== Multi-User Session Methods ====================

    /// Create a new session for a user with specified isolation level
    ///
    /// Sessions provide isolated execution contexts for multi-user scenarios.
    /// Each session maintains its own transaction state and isolation guarantees.
    ///
    /// # Arguments
    ///
    /// * `user_name` - Name of the user for this session
    /// * `isolation` - Transaction isolation level for the session
    ///
    /// # Returns
    ///
    /// A unique `SessionId` that identifies this session
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::EmbeddedDatabase;
    /// use heliosdb_nano::session::IsolationLevel;
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new_in_memory()?;
    ///
    /// // Create a session with snapshot isolation
    /// let session_id = db.create_session("alice", IsolationLevel::Snapshot)?;
    ///
    /// // Execute queries in the session context
    /// db.execute_in_session(session_id, "CREATE TABLE test (id INT)")?;
    ///
    /// // Clean up when done
    /// db.destroy_session(session_id)?;
    /// # Ok(())
    /// # }
    /// ```
    pub fn create_session(
        &self,
        user_name: &str,
        isolation: crate::session::IsolationLevel,
    ) -> Result<crate::session::SessionId> {
        let user = crate::session::User::new_passwordless(user_name);
        self.session_manager.create_session(&user, isolation)
    }

    /// Destroy an active session and release all resources
    ///
    /// This terminates the session and releases all associated resources including
    /// active transactions, locks, and memory. Any uncommitted transaction is
    /// automatically rolled back.
    ///
    /// # Arguments
    ///
    /// * `session_id` - ID of the session to destroy
    pub fn destroy_session(&self, session_id: crate::session::SessionId) -> Result<()> {
        // A dropped connection must not leak its open transaction (write-set
        // buffers, row locks) or its eager ART index mutations. Taking the
        // slot's write lock waits out any statement still borrowing the
        // transaction before rolling it back.
        if let Some((_, slot)) = self.session_transactions.remove(&session_id) {
            self.session_txn_count.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
            if let Some(txn) = slot.write().take() {
                let _ = txn.rollback();
            }
        }
        self.finish_session_art_undo(session_id, true);
        self.session_manager.destroy_session(session_id)
    }

    /// Begin an explicit transaction for a specific session
    ///
    /// Starts a new transaction within the session context. The transaction
    /// uses the isolation level specified when the session was created.
    ///
    /// # Arguments
    ///
    /// * `session_id` - ID of the session to begin transaction in
    ///
    /// # Errors
    ///
    /// Returns an error if the session already has an active transaction.
    pub fn begin_transaction_for_session(&self, session_id: crate::session::SessionId) -> Result<()> {
        let session_lock = self.session_manager.get_session(session_id)?;
        let mut session = session_lock.write();

        if session.active_txn.is_some() {
            return Err(Error::transaction("Session already has an active transaction"));
        }

        // Create a real storage transaction with a FRESH snapshot
        let mut txn = storage::Transaction::new_with_session(
            self.storage.db.clone(),
            self.storage.next_timestamp(),
            self.storage.snapshot_manager_arc(),
            session_id,
            session.isolation_level,
            self.lock_manager.clone(),
            self.dirty_tracker.clone(),
        )?;
        // P0#1: session transactions must honor time_travel_enabled too
        // (new_with_session defaults versioning on).
        txn.set_versioning_enabled(self.storage.time_travel_enabled());
        txn.set_rocksdb_wal_enabled(!self.storage.config().storage.memory_only);
        // R1.3-p2: the session's SET synchronous_commit overrides
        // storage.durable_commit (off = skip the group-fsync wait; on =
        // wait even when the storage default is non-durable).
        txn.set_sync_commit(
            session
                .synchronous_commit
                .unwrap_or(self.storage.config().storage.durable_commit)
                && !self.storage.config().storage.memory_only,
        );
        // R1.3-p2: durable commits share one group fsync per cohort.
        txn.set_group_committer(self.storage.group_committer());
        // R1.3-p2: invalidate written rows inside commit, before the
        // snapshot barrier lifts (stale-row-cache lost-update fence).
        txn.set_row_cache(std::sync::Arc::clone(self.storage.row_cache()));
        // R0.2: record commits always; validate (first-committer-wins) for
        // RepeatableRead/Serializable. ReadCommitted keeps PostgreSQL's
        // blind-write semantics.
        txn.set_conflict_registry(
            self.storage.conflict_registry(),
            session.isolation_level != crate::session::IsolationLevel::ReadCommitted,
        );

        let txn_id = txn.snapshot_id();
        session.active_txn = Some(txn_id);
        session.stats.transactions_started += 1;

        // Store transaction in map
        self.session_transactions
            .insert(session_id, std::sync::Arc::new(parking_lot::RwLock::new(Some(txn))));
        self.session_txn_count.fetch_add(1, std::sync::atomic::Ordering::AcqRel);

        Ok(())
    }

    /// Clone the session's transaction slot out of the map. The DashMap
    /// shard guard is held only for this lookup — NEVER across statement
    /// execution or row-lock waits (see [`SessionTxnSlot`]).
    fn session_txn_slot(&self, session_id: crate::session::SessionId) -> Option<SessionTxnSlot> {
        self.session_transactions
            .get(&session_id)
            .map(|entry| std::sync::Arc::clone(entry.value()))
    }

    /// Commit transaction for a specific session
    ///
    /// Atomically applies all buffered writes from the session's transaction
    /// to the database. After commit, the transaction is finalized.
    ///
    /// # Arguments
    ///
    /// * `session_id` - ID of the session whose transaction to commit
    ///
    /// # Errors
    ///
    /// Returns an error if the session has no active transaction.
    pub fn commit_transaction_for_session(&self, session_id: crate::session::SessionId) -> Result<()> {
        let session_lock = self.session_manager.get_session(session_id)?;
        let mut session = session_lock.write();

        if session.active_txn.is_none() {
            return Err(Error::transaction("Session has no active transaction to commit"));
        }

        // Retrieve and commit transaction with a FRESH commit timestamp.
        // The slot's write lock waits out any statement still borrowing the
        // transaction; the DashMap shard guard itself is released by the
        // time `remove` returns (deadlock fix — see [`SessionTxnSlot`]).
        if let Some((_, slot)) = self.session_transactions.remove(&session_id) {
            self.session_txn_count.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
            let Some(txn) = slot.write().take() else {
                // Slot already drained (concurrent commit/rollback race) —
                // treat like the missing-entry case below.
                self.finish_session_art_undo(session_id, false);
                self.invalidate_result_cache();
                session.active_txn = None;
                session.stats.transactions_committed += 1;
                return Ok(());
            };
            // R1.3-p2: commit itself runs the row-cache fence when the cache
            // is wired; only unwired transactions need the caller-side sweep.
            let written = if txn.has_row_cache() {
                Vec::new()
            } else {
                txn.written_data_keys()
            };
            let commit_ts = self.storage.next_commit_timestamp(txn.has_tracked_writes());
            if let Err(e) = txn.commit_with_timestamp(commit_ts) {
                // Failed commit (e.g. R0.2 serialization failure) behaves
                // like ROLLBACK: undo eager ART mutations, clear the
                // session's transaction state, count the abort.
                self.finish_session_art_undo(session_id, true);
                self.invalidate_result_cache();
                session.active_txn = None;
                session.stats.transactions_aborted += 1;
                return Err(e);
            }
            if !written.is_empty() {
                self.invalidate_row_cache_for(&written);
            }
            self.storage.increment_lsn();
        }
        // Changes are committed: the session's ART mutations are now permanent.
        self.finish_session_art_undo(session_id, false);

        // Invalidate result cache since committed data may affect cached query results
        self.invalidate_result_cache();

        session.active_txn = None;
        session.stats.transactions_committed += 1;
        Ok(())
    }

    /// Rollback transaction for a specific session
    ///
    /// Discards all buffered writes from the session's transaction without
    /// applying them. After rollback, the transaction is finalized and a
    /// new transaction can be started.
    ///
    /// # Arguments
    ///
    /// * `session_id` - ID of the session whose transaction to rollback
    ///
    /// # Errors
    ///
    /// Returns an error if the session has no active transaction.
    pub fn rollback_transaction_for_session(&self, session_id: crate::session::SessionId) -> Result<()> {
        let session_lock = self.session_manager.get_session(session_id)?;
        let mut session = session_lock.write();

        if session.active_txn.is_none() {
            return Err(Error::transaction("Session has no active transaction to rollback"));
        }

        // Retrieve and rollback transaction (slot semantics as in commit).
        if let Some((_, slot)) = self.session_transactions.remove(&session_id) {
            self.session_txn_count.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
            if let Some(txn) = slot.write().take() {
                txn.rollback()?;
            }
        }
        // Undo the session's eager ART index mutations (insert/update/delete
        // hooks run at statement time, not commit time).
        self.finish_session_art_undo(session_id, true);

        // Invalidate result cache since rollback changes visible data state
        self.invalidate_result_cache();

        session.active_txn = None;
        session.stats.transactions_aborted += 1;
        Ok(())
    }

    /// Execute SQL in a specific session
    ///
    /// Executes a SQL statement within the session's context. If the session
    /// has an active transaction, the statement is executed within that
    /// transaction. Otherwise, an implicit auto-commit transaction is used.
    ///
    /// For `ReadCommitted` isolation, each statement gets a fresh snapshot.
    /// For `Snapshot` isolation, all statements in a transaction see the
    /// same consistent snapshot.
    ///
    /// # Arguments
    ///
    /// * `session_id` - ID of the session to execute in
    /// * `sql` - SQL statement to execute
    ///
    /// # Returns
    ///
    /// Number of rows affected by the statement
    pub fn execute_in_session(&self, session_id: crate::session::SessionId, sql: &str) -> Result<u64> {
        // R1.3-p2: session-scoped SET/RESET synchronous_commit. Must run
        // BEFORE the session write lock below (the handler re-locks it).
        if let Some(handled) = self.try_handle_session_synchronous_commit(session_id, sql)? {
            return Ok(handled);
        }
        if let Some(handled) = self.try_handle_session_fast_autocommit(session_id, sql)? {
            return Ok(handled);
        }
        let session_lock = self.session_manager.get_session(session_id)?;
        let mut session = session_lock.write();
        session.touch();
        session.stats.queries_executed += 1;

        // Check if session has an active transaction
        if let Some(slot) = self.session_txn_slot(session_id) {
            // For READ COMMITTED, each statement gets a fresh snapshot.
            // Hold the slot's write lock only briefly for the mutable refresh.
            if session.isolation_level == crate::session::IsolationLevel::ReadCommitted {
                if let Some(txn) = slot.write().as_mut() {
                    txn.refresh_snapshot(self.storage.current_timestamp());
                }
            }

            // Borrow the transaction through the slot for the statement's
            // duration — no DashMap shard guard is held across execution or
            // row-lock waits (deadlock fix, see [`SessionTxnSlot`]).
            let txn = parking_lot::RwLockReadGuard::try_map(slot.read(), |t| t.as_ref())
                .map_err(|_| Error::transaction("Session transaction disappeared during execute"))?;

            // Skip fast paths for session transactions — writes must go through
            // the transaction write set for proper isolation and rollback support
            self.execute_in_transaction_no_fast_path(sql, &txn)
        } else {
            // Implicit transaction — skip fast paths since session-based execution
            // requires MVCC versioning for proper isolation across sessions
            let mut txn = storage::Transaction::new_with_session(
                self.storage.db.clone(),
                self.storage.next_timestamp(),
                self.storage.snapshot_manager_arc(),
                session_id,
                session.isolation_level,
                self.lock_manager.clone(),
                self.dirty_tracker.clone(),
            )?;
            // P0#1: session transactions must honor time_travel_enabled too.
            txn.set_versioning_enabled(self.storage.time_travel_enabled());
            txn.set_rocksdb_wal_enabled(!self.storage.config().storage.memory_only);
            // R1.3-p2: the session's SET synchronous_commit overrides
            // storage.durable_commit for this statement's commit.
            txn.set_sync_commit(
                session
                    .synchronous_commit
                    .unwrap_or(self.storage.config().storage.durable_commit)
                    && !self.storage.config().storage.memory_only,
            );
            // R1.3-p2: durable commits share one group fsync per cohort.
            txn.set_group_committer(self.storage.group_committer());
            // R1.3-p2: stale-row-cache lost-update fence (see above).
            txn.set_row_cache(std::sync::Arc::clone(self.storage.row_cache()));
            // R0.2: implicit single-statement session transactions record
            // their commits so explicit transactions can validate against
            // them; they never validate (statement-atomic, RC semantics).
            txn.set_conflict_registry(self.storage.conflict_registry(), false);

            let result = self.execute_in_transaction_no_fast_path(sql, &txn);

            match result {
                Ok(count) => {
                    // R1.3-p2: commit runs the row-cache fence itself when
                    // the cache is wired (it always is on this path).
                    let written = if txn.has_row_cache() {
                        Vec::new()
                    } else {
                        txn.written_data_keys()
                    };
                    let commit_ts = self.storage.next_commit_timestamp(txn.has_tracked_writes());
                    txn.commit_with_timestamp(commit_ts)?;
                    if !written.is_empty() {
                        self.invalidate_row_cache_for(&written);
                    }
                    self.storage.increment_lsn();
                    self.finish_session_art_undo(session_id, false);
                    Ok(count)
                }
                Err(e) => {
                    let _ = txn.rollback();
                    self.finish_session_art_undo(session_id, true);
                    Err(e)
                }
            }
        }
    }

    /// Query data in a specific session
    ///
    /// Executes a SELECT query within the session's context. If the session
    /// has an active transaction, the query uses that transaction's snapshot
    /// for consistent reads.
    ///
    /// # Arguments
    ///
    /// * `session_id` - ID of the session to query in
    /// * `sql` - SQL SELECT query
    /// * `_params` - Query parameters (reserved for future use)
    ///
    /// # Returns
    ///
    /// Vector of tuples matching the query
    pub fn query_in_session(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
        _params: &[&dyn std::fmt::Display],
    ) -> Result<Vec<Tuple>> {
        let session_lock = self.session_manager.get_session(session_id)?;
        let mut session = session_lock.write();
        session.touch();
        session.stats.queries_executed += 1;

        // Check if session has an active transaction
        if let Some(slot) = self.session_txn_slot(session_id) {
            // For READ COMMITTED, each statement gets a fresh snapshot.
            // Hold the slot's write lock only briefly for the mutable refresh.
            if session.isolation_level == crate::session::IsolationLevel::ReadCommitted {
                if let Some(txn) = slot.write().as_mut() {
                    txn.refresh_snapshot(self.storage.current_timestamp());
                }
            }

            // Borrow through the slot — no shard guard held across the query
            // (deadlock fix, see [`SessionTxnSlot`]).
            let txn = parking_lot::RwLockReadGuard::try_map(slot.read(), |t| t.as_ref())
                .map_err(|_| Error::transaction("Session transaction disappeared during query"))?;

            // Parse SQL with cache
            let (statement, _) = self.parse_cached(sql)?;

            // Create logical plan with catalog access and original SQL for time-travel parsing
            let catalog = self.storage.catalog();
            let planner = sql::Planner::with_catalog(&catalog).with_sql(sql.to_string());
            let plan = planner.statement_to_plan(statement)?;

            // Execute plan with transaction context
            let mut executor = sql::Executor::with_storage(&self.storage)
                .with_timeout(self.effective_statement_timeout_ms())
                .with_transaction(&txn);

            executor.execute(&plan)
        } else {
            self.query(sql, _params)
        }
    }

    // ================= R0.1: wire-session entry points =================
    //
    // One session per wire connection. Transaction control and in-transaction
    // statements run through the per-session transaction API; autocommit
    // statements take the exact same fast paths as `execute()`/`query*()`.
    // This replaces routing wire statements through the global transaction
    // slot, which folded every connection into one shared transaction.

    /// True if this session currently has an open explicit transaction.
    pub fn session_in_transaction(&self, session_id: crate::session::SessionId) -> bool {
        self.session_transactions.contains_key(&session_id)
    }

    /// Create a session for a wire-protocol connection (one per connection).
    ///
    /// Skips the per-user `max_sessions` quota — wire connection counts are
    /// bounded by the server's `max_connections` semaphore instead.
    pub fn create_wire_session(&self, user_name: &str) -> Result<crate::session::SessionId> {
        let user = crate::session::User::new_passwordless(user_name);
        self.session_manager
            .create_session_unchecked(&user, crate::session::IsolationLevel::ReadCommitted)
    }

    /// Set the isolation level used by the session's next transaction.
    pub fn set_session_isolation(
        &self,
        session_id: crate::session::SessionId,
        isolation: crate::session::IsolationLevel,
    ) -> Result<()> {
        if self.session_transactions.contains_key(&session_id) {
            return Err(Error::transaction(
                "cannot change isolation level inside an active transaction",
            ));
        }
        let session_lock = self.session_manager.get_session(session_id)?;
        session_lock.write().isolation_level = isolation;
        Ok(())
    }

    /// R1.3-p2: set (or with `None` reset) the session's
    /// `synchronous_commit` override. PostgreSQL semantics: takes effect
    /// immediately, including for a transaction already in progress (the
    /// open transaction's commit honors the latest setting).
    pub fn set_session_synchronous_commit(
        &self,
        session_id: crate::session::SessionId,
        value: Option<bool>,
    ) -> Result<()> {
        let session_lock = self.session_manager.get_session(session_id)?;
        session_lock.write().synchronous_commit = value;
        // Apply to an already-open transaction too: its sync flag was
        // captured at BEGIN.
        if let Some(slot) = self.session_txn_slot(session_id) {
            if let Some(txn) = slot.write().as_mut() {
                let storage_cfg = &self.storage.config().storage;
                txn.set_sync_commit(value.unwrap_or(storage_cfg.durable_commit) && !storage_cfg.memory_only);
            }
        }
        Ok(())
    }

    /// R1.3-p2: the session's raw `synchronous_commit` override
    /// (`None` = inherit `storage.durable_commit`).
    pub fn session_synchronous_commit(&self, session_id: crate::session::SessionId) -> Result<Option<bool>> {
        let session_lock = self.session_manager.get_session(session_id)?;
        let value = session_lock.read().synchronous_commit;
        Ok(value)
    }

    /// R1.3-p2: the session's EFFECTIVE `synchronous_commit` (override or
    /// the `storage.durable_commit` default; always false in memory mode).
    pub fn session_synchronous_commit_effective(&self, session_id: crate::session::SessionId) -> Result<bool> {
        let storage_cfg = &self.storage.config().storage;
        Ok(self
            .session_synchronous_commit(session_id)?
            .unwrap_or(storage_cfg.durable_commit)
            && !storage_cfg.memory_only)
    }

    /// R1.3-p2: intercept `SET/RESET synchronous_commit` for a session.
    /// Returns `Some(0)` when handled, `None` when the statement is
    /// something else.
    fn try_handle_session_synchronous_commit(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
    ) -> Result<Option<u64>> {
        match Self::parse_synchronous_commit_statement(sql)? {
            Some(value) => {
                self.set_session_synchronous_commit(session_id, value)?;
                Ok(Some(0))
            }
            None => Ok(None),
        }
    }

    /// Item 9: set the session's `helios.fast_autocommit` opt-in. When `true`,
    /// single-statement autocommit on this session commits non-blocking (see
    /// the field doc on [`crate::session::Session`]).
    pub fn set_session_fast_autocommit(
        &self,
        session_id: crate::session::SessionId,
        value: bool,
    ) -> Result<()> {
        let session_lock = self.session_manager.get_session(session_id)?;
        session_lock.write().fast_autocommit = value;
        Ok(())
    }

    /// Item 9: read the session's `helios.fast_autocommit` flag (default false).
    pub fn session_fast_autocommit(&self, session_id: crate::session::SessionId) -> Result<bool> {
        let session_lock = self.session_manager.get_session(session_id)?;
        let value = session_lock.read().fast_autocommit;
        Ok(value)
    }

    /// Item 9: intercept `SET/RESET helios.fast_autocommit` for a session
    /// (the extended-protocol / RESET path; the simple-query handler
    /// intercepts the SET form itself). Returns `Some(0)` when handled.
    fn try_handle_session_fast_autocommit(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
    ) -> Result<Option<u64>> {
        match Self::parse_helios_fast_autocommit_statement(sql)? {
            Some(value) => {
                self.set_session_fast_autocommit(session_id, value)?;
                Ok(Some(0))
            }
            None => Ok(None),
        }
    }

    /// Touch session stats and, for READ COMMITTED, refresh the open
    /// transaction's snapshot so the next statement sees the latest commits.
    fn touch_session_for_statement(&self, session_id: crate::session::SessionId) -> Result<()> {
        let session_lock = self.session_manager.get_session(session_id)?;
        let mut session = session_lock.write();
        session.touch();
        session.stats.queries_executed += 1;
        if session.isolation_level == crate::session::IsolationLevel::ReadCommitted {
            if let Some(slot) = self.session_txn_slot(session_id) {
                if let Some(txn) = slot.write().as_mut() {
                    txn.refresh_snapshot(self.storage.current_timestamp());
                }
            }
        }
        Ok(())
    }

    /// Handle BEGIN / COMMIT / ROLLBACK for a wire session with PostgreSQL's
    /// lenient semantics: BEGIN inside a transaction and COMMIT/ROLLBACK
    /// outside one succeed (the handler emits the WARNING notice).
    pub fn handle_transaction_control_for_session(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
    ) -> Result<u64> {
        let trimmed = sql.trim().trim_end_matches(';').trim();
        if starts_with_icase(trimmed, "BEGIN") || starts_with_icase(trimmed, "START TRANSACTION") {
            if !self.session_transactions.contains_key(&session_id) {
                self.begin_transaction_for_session(session_id)?;
            }
            Ok(0)
        } else if trimmed.eq_ignore_ascii_case("COMMIT") {
            if self.session_transactions.contains_key(&session_id) {
                self.commit_transaction_for_session(session_id)?;
            }
            Ok(0)
        } else if trimmed.eq_ignore_ascii_case("ROLLBACK") {
            if self.session_transactions.contains_key(&session_id) {
                self.rollback_transaction_for_session(session_id)?;
            }
            Ok(0)
        } else {
            Err(Error::query_execution("Unknown transaction control statement"))
        }
    }

    /// R1.3-p2: when the session has a `synchronous_commit` override,
    /// install the engine thread-local override for the duration of one
    /// statement that routes through the global (non-session) execute
    /// paths, so the autocommit durability barrier and autocommit
    /// transactions honor the session's setting. Returns `None` (no guard,
    /// zero TLS traffic) when the session has no override.
    fn session_durability_override_guard(
        &self,
        session_id: crate::session::SessionId,
    ) -> Option<storage::SynchronousCommitOverrideGuard> {
        let session_lock = self.session_manager.get_session(session_id).ok()?;
        let (sync, fast) = {
            let s = session_lock.read();
            (s.synchronous_commit, s.fast_autocommit)
        };
        // An explicit `synchronous_commit` override always wins. Otherwise
        // `helios.fast_autocommit = on` (item 9) selects non-blocking autocommit
        // for this session. With neither set — the default, and exactly what the
        // pg35 benchmark runs — there is no override and no guard is installed,
        // byte-identical to before (still one session read).
        let effective = match sync {
            Some(v) => v,
            None if fast => false,
            None => return None,
        };
        Some(storage::StorageEngine::synchronous_commit_override_guard(Some(effective)))
    }

    /// Execute a statement on behalf of a wire-protocol session.
    pub fn execute_for_session(&self, session_id: crate::session::SessionId, sql: &str) -> Result<u64> {
        if Self::is_transaction_control(sql) {
            return self.handle_transaction_control_for_session(session_id, sql);
        }
        // R1.3-p2: session-scoped SET/RESET synchronous_commit (the PG
        // simple-query handler intercepts SET itself; RESET and the
        // extended protocol land here).
        if let Some(handled) = self.try_handle_session_synchronous_commit(session_id, sql)? {
            return Ok(handled);
        }
        if let Some(handled) = self.try_handle_session_fast_autocommit(session_id, sql)? {
            return Ok(handled);
        }
        if !self.session_transactions.contains_key(&session_id) {
            let _sync_override = self.session_durability_override_guard(session_id);
            return self.execute(sql);
        }

        // SQLite-compat PRAGMA stub — parity with `execute()`.
        if crate::sql::sqlite_compat::parse_pragma(sql).is_some() {
            tracing::debug!("PRAGMA stubbed via execute_for_session(): {}", sql.trim());
            return Ok(0);
        }

        let start = std::time::Instant::now();
        self.touch_session_for_statement(session_id)?;
        let slot = self
            .session_txn_slot(session_id)
            .ok_or_else(|| Error::transaction("Session transaction disappeared during execute"))?;
        let txn = parking_lot::RwLockReadGuard::try_map(slot.read(), |t| t.as_ref())
            .map_err(|_| Error::transaction("Session transaction disappeared during execute"))?;
        // Result-cache invalidation is deferred to COMMIT, mirroring the
        // global-slot in-transaction arm of `execute()`.
        let result = self.execute_in_transaction_no_fast_path(sql, &txn);
        let rows = result.as_ref().copied().unwrap_or(0);
        self.log_slow_query(sql, start.elapsed(), rows);
        result
    }

    /// `query_with_columns` for a wire session. Inside an open session
    /// transaction the query executes with that transaction attached, so it
    /// sees the transaction's own uncommitted writes (read-your-writes —
    /// which the global-slot wire path never provided); otherwise it takes
    /// the regular cached autocommit path.
    pub fn query_with_columns_for_session(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
    ) -> Result<(Vec<Tuple>, Vec<String>)> {
        if !self.session_transactions.contains_key(&session_id) {
            return self.query_with_columns(sql);
        }

        let start = std::time::Instant::now();
        self.touch_session_for_statement(session_id)?;
        let slot = self
            .session_txn_slot(session_id)
            .ok_or_else(|| Error::transaction("Session transaction disappeared during query"))?;
        let txn = parking_lot::RwLockReadGuard::try_map(slot.read(), |t| t.as_ref())
            .map_err(|_| Error::transaction("Session transaction disappeared during query"))?;

        let (statement, _) = self.parse_cached(sql)?;
        let catalog = self.storage.catalog();
        let planner = sql::Planner::with_catalog(&catalog).with_sql(sql.to_string());
        let plan = planner.statement_to_plan(statement)?;

        let mut executor = sql::Executor::with_storage(&self.storage)
            .with_timeout(self.effective_statement_timeout_ms())
            .with_transaction(&txn);
        let result = executor.execute_with_columns(&plan);
        if let Ok((rows, _)) = &result {
            self.log_slow_query(sql, start.elapsed(), rows.len() as u64);
        }
        result
    }

    /// `execute_returning` for a wire session (simple-query DML … RETURNING).
    pub fn execute_returning_for_session(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
    ) -> Result<(u64, Vec<Tuple>)> {
        if Self::is_transaction_control(sql) {
            let count = self.handle_transaction_control_for_session(session_id, sql)?;
            return Ok((count, Vec::new()));
        }
        if let Some(handled) = self.try_handle_session_synchronous_commit(session_id, sql)? {
            return Ok((handled, Vec::new()));
        }
        if !self.session_transactions.contains_key(&session_id) {
            let _sync_override = self.session_durability_override_guard(session_id);
            return self.execute_returning(sql);
        }

        self.touch_session_for_statement(session_id)?;
        let slot = self
            .session_txn_slot(session_id)
            .ok_or_else(|| Error::transaction("Session transaction disappeared during execute"))?;
        let txn = parking_lot::RwLockReadGuard::try_map(slot.read(), |t| t.as_ref())
            .map_err(|_| Error::transaction("Session transaction disappeared during execute"))?;
        let plan = self.parameterized_plan_cached(sql)?;
        let out = self.execute_plan_with_params(&plan, &[], Some(&txn));

        #[cfg(feature = "code-graph")]
        if out.is_ok() {
            let touched = Self::touched_table_from_sql(sql);
            self.maybe_auto_reparse(touched.as_deref());
        }

        out
    }

    /// `execute_params` for a wire session (extended-protocol DML).
    pub fn execute_params_for_session(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
        params: &[Value],
    ) -> Result<u64> {
        self.execute_params_for_session_inner(session_id, sql, params, None)
    }

    /// `execute_params_for_session` with a pinned prepared-statement plan
    /// (R5.W2) — skips the per-Execute plan-cache lookup.
    pub(crate) fn execute_params_for_session_with_plan(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
        params: &[Value],
        plan: &std::sync::Arc<sql::LogicalPlan>,
    ) -> Result<u64> {
        self.execute_params_for_session_inner(session_id, sql, params, Some(plan))
    }

    fn execute_params_for_session_inner(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
        params: &[Value],
        plan_override: Option<&std::sync::Arc<sql::LogicalPlan>>,
    ) -> Result<u64> {
        if Self::is_transaction_control(sql) {
            return self.handle_transaction_control_for_session(session_id, sql);
        }
        if let Some(handled) = self.try_handle_session_synchronous_commit(session_id, sql)? {
            return Ok(handled);
        }
        if let Some(handled) = self.try_handle_session_fast_autocommit(session_id, sql)? {
            return Ok(handled);
        }
        if !self.session_transactions.contains_key(&session_id) {
            let _sync_override = self.session_durability_override_guard(session_id);
            return self.execute_params_inner(sql, params, plan_override);
        }

        self.touch_session_for_statement(session_id)?;
        let slot = self
            .session_txn_slot(session_id)
            .ok_or_else(|| Error::transaction("Session transaction disappeared during execute"))?;
        let txn = parking_lot::RwLockReadGuard::try_map(slot.read(), |t| t.as_ref())
            .map_err(|_| Error::transaction("Session transaction disappeared during execute"))?;
        let plan = match plan_override {
            Some(p) => std::sync::Arc::clone(p),
            None => self.parameterized_plan_cached(sql)?,
        };
        if let Some(result) = self.try_session_txn_fast_insert_params(sql, &plan, params, &txn) {
            return result;
        }
        let (count, _tuples) = self.execute_plan_with_params(&plan, params, Some(&txn))?;
        Ok(count)
    }

    /// `query_params` for a wire session (extended-protocol SELECT, plus the
    /// DML…RETURNING shapes drivers route through the query path).
    pub fn query_params_for_session(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
        params: &[Value],
    ) -> Result<Vec<Tuple>> {
        self.query_params_for_session_inner(session_id, sql, params, None)
    }

    /// `query_params_for_session` with a pinned prepared-statement plan
    /// (R5.W2) — skips the per-Execute plan-cache lookup.
    pub(crate) fn query_params_for_session_with_plan(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
        params: &[Value],
        plan: &std::sync::Arc<sql::LogicalPlan>,
    ) -> Result<Vec<Tuple>> {
        self.query_params_for_session_inner(session_id, sql, params, Some(plan))
    }

    fn query_params_for_session_inner(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
        params: &[Value],
        plan_override: Option<&std::sync::Arc<sql::LogicalPlan>>,
    ) -> Result<Vec<Tuple>> {
        if !self.session_transactions.contains_key(&session_id) {
            return self.query_params_inner(sql, params, plan_override);
        }

        self.touch_session_for_statement(session_id)?;
        let slot = self
            .session_txn_slot(session_id)
            .ok_or_else(|| Error::transaction("Session transaction disappeared during query"))?;
        let txn = parking_lot::RwLockReadGuard::try_map(slot.read(), |t| t.as_ref())
            .map_err(|_| Error::transaction("Session transaction disappeared during query"))?;
        let plan = match plan_override {
            Some(p) => std::sync::Arc::clone(p),
            None => self.parameterized_plan_cached(sql)?,
        };

        if matches!(
            &*plan,
            sql::LogicalPlan::Insert { .. }
                | sql::LogicalPlan::InsertSelect { .. }
                | sql::LogicalPlan::Update { .. }
                | sql::LogicalPlan::Delete { .. }
        ) {
            let (_count, returned) = self.execute_plan_with_params(&plan, params, Some(&txn))?;
            return Ok(returned);
        }

        self.query_plan_with_params(&plan, params, Some(&txn))
    }

    /// `query_params_with_columns` for a wire session — the column-aware,
    /// parameter-aware entry point the MySQL binary protocol
    /// (COM_STMT_EXECUTE, R5.W4) routes through. Mirrors
    /// [`query_params_for_session`](Self::query_params_for_session) but also
    /// returns the output column names so wire handlers can build result-set
    /// metadata without a second planning pass.
    pub fn query_params_with_columns_for_session(
        &self,
        session_id: crate::session::SessionId,
        sql: &str,
        params: &[Value],
    ) -> Result<(Vec<Tuple>, Vec<String>)> {
        if !self.session_transactions.contains_key(&session_id) {
            return self.query_params_with_columns(sql, params);
        }

        self.touch_session_for_statement(session_id)?;
        let slot = self
            .session_txn_slot(session_id)
            .ok_or_else(|| Error::transaction("Session transaction disappeared during query"))?;
        let txn = parking_lot::RwLockReadGuard::try_map(slot.read(), |t| t.as_ref())
            .map_err(|_| Error::transaction("Session transaction disappeared during query"))?;
        let plan = self.parameterized_plan_cached(sql)?;

        if matches!(
            &*plan,
            sql::LogicalPlan::Insert { .. }
                | sql::LogicalPlan::InsertSelect { .. }
                | sql::LogicalPlan::Update { .. }
                | sql::LogicalPlan::Delete { .. }
        ) {
            let columns = match &*plan {
                sql::LogicalPlan::Insert {
                    table_name,
                    returning: Some(items),
                    ..
                }
                | sql::LogicalPlan::InsertSelect {
                    table_name,
                    returning: Some(items),
                    ..
                }
                | sql::LogicalPlan::Update {
                    table_name,
                    returning: Some(items),
                    ..
                }
                | sql::LogicalPlan::Delete {
                    table_name,
                    returning: Some(items),
                    ..
                } => {
                    let schema = self.storage.catalog().get_table_schema(table_name)?;
                    Self::returning_schema(&schema, items)
                        .columns
                        .into_iter()
                        .map(|c| c.name)
                        .collect()
                }
                _ => Vec::new(),
            };
            let (_count, returned) = self.execute_plan_with_params(&plan, params, Some(&txn))?;
            return Ok((returned, columns));
        }

        let mut executor = sql::Executor::with_storage(&self.storage)
            .with_timeout(self.effective_statement_timeout_ms())
            .with_parameters(params.to_vec())
            .with_transaction(&txn);
        executor.execute_with_columns(&plan)
    }

    /// Session-transaction variant of the parameterized fast INSERT path:
    /// stages the row in the session transaction's write set without going
    /// through the parser/planner. Concurrent session transactions stay
    /// correct because commit writes MVCC versions (the gate requires
    /// versioning on unless this is the only session transaction).
    fn try_session_txn_fast_insert_params(
        &self,
        sql: &str,
        plan: &sql::LogicalPlan,
        params: &[Value],
        txn: &storage::Transaction,
    ) -> Option<Result<u64>> {
        if !self.savepoints.read().is_empty()
            || self.tenant_manager.get_current_context().is_some()
            || self.storage.get_current_branch_id().is_some()
            || !(self.storage.time_travel_enabled()
                || self.session_txn_count.load(std::sync::atomic::Ordering::Acquire) <= 1)
        {
            return None;
        }

        let spec = match self.fast_param_insert_spec(sql, plan)? {
            Ok(spec) => spec,
            Err(e) => return Some(Err(e)),
        };
        let tuple = match Self::materialize_fast_param_insert_tuple(&spec, params) {
            Ok(tuple) => tuple,
            Err(e) => return Some(Err(e)),
        };

        Some(self.insert_validated_tuple_in_transaction(&spec.table_name, tuple, &spec.schema, txn))
    }

