    /// Query data with parameters (SAFE - prevents SQL injection)
    ///
    /// This method uses parameterized queries to safely execute SELECT queries with user input.
    /// Parameters are referenced as $1, $2, $3, etc. in PostgreSQL style.
    ///
    /// # Arguments
    ///
    /// * `sql` - SQL query with parameter placeholders ($1, $2, etc.)
    /// * `params` - Parameter values in order
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::{EmbeddedDatabase, Value};
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new("./data")?;
    ///
    /// // Create and populate table
    /// db.execute("CREATE TABLE users (id INT, name TEXT, age INT)")?;
    /// db.execute("INSERT INTO users VALUES (1, 'Alice', 30)")?;
    /// db.execute("INSERT INTO users VALUES (2, 'Bob', 25)")?;
    ///
    /// // Safe SELECT with single parameter
    /// let results = db.query_params(
    ///     "SELECT * FROM users WHERE name = $1",
    ///     &[Value::String("Alice".to_string())]
    /// )?;
    /// println!("Found {} users named Alice", results.len());
    ///
    /// // Safe SELECT with multiple parameters
    /// let results = db.query_params(
    ///     "SELECT * FROM users WHERE age > $1 AND name LIKE $2",
    ///     &[
    ///         Value::Int4(20),
    ///         Value::String("%li%".to_string()),
    ///     ]
    /// )?;
    /// println!("Found {} matching users", results.len());
    ///
    /// // SQL injection attempt is safely handled
    /// let malicious_input = "'; DROP TABLE users; --";
    /// let results = db.query_params(
    ///     "SELECT * FROM users WHERE name = $1",
    ///     &[Value::String(malicious_input.to_string())]
    /// )?;
    /// // No users found, but table is safe!
    /// println!("Found {} users (table still exists!)", results.len());
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Security
    ///
    /// This method prevents SQL injection by treating parameters as data, not code.
    /// Even malicious input is safely handled as a literal value.
    pub fn query_params(&self, sql: &str, params: &[Value]) -> Result<Vec<Tuple>> {
        self.query_params_inner(sql, params, None)
    }

    /// `query_params` with an optional pre-fetched parameterized plan
    /// (R5.W2 — prepared statements pin the `parameterized_plan_cached`
    /// output and skip the per-Execute cache lookup). The override is the
    /// *pre-RLS* plan; RLS is still applied per execution below, exactly
    /// as on the no-override path.
    fn query_params_inner(
        &self,
        sql: &str,
        params: &[Value],
        plan_override: Option<&std::sync::Arc<sql::LogicalPlan>>,
    ) -> Result<Vec<Tuple>> {
        // Code-graph pre-parser: see `maybe_rewrite_code_graph`.
        // `ON BRANCH '…'` directives swap the active branch via a
        // Drop guard for the duration of this query.
        #[cfg(feature = "code-graph")]
        let (rewritten_owned, _branch_guard) = self.rewrite_and_scope(sql);
        // A code-graph rewrite changes the SQL the plan must come from —
        // a pinned plan for the unrewritten text would be wrong.
        #[cfg(feature = "code-graph")]
        let plan_override = if rewritten_owned == sql { plan_override } else { None };
        #[cfg(feature = "code-graph")]
        let sql: &str = &rewritten_owned;
        #[cfg(not(feature = "code-graph"))]
        let sql: &str = sql;
        let start = std::time::Instant::now();

        if let Some(result) = self.try_fast_select_params(sql, params) {
            let rows = result?;
            self.log_slow_query(sql, start.elapsed(), rows.len() as u64);
            return Ok(rows);
        }

        let plan_start = std::time::Instant::now();
        let mut plan = match plan_override {
            Some(p) => (**p).clone(),
            None => (*self.parameterized_plan_cached(sql)?).clone(),
        };
        tracing::debug!(
            phase = "plan",
            duration_us = plan_start.elapsed().as_micros() as u64,
            "Parameterized logical plan ready"
        );

        plan = self.apply_rls_to_plan(plan)?;

        if matches!(
            &plan,
            sql::LogicalPlan::Insert { .. }
                | sql::LogicalPlan::InsertSelect { .. }
                | sql::LogicalPlan::Update { .. }
                | sql::LogicalPlan::Delete { .. }
        ) {
            let (_count, returned) = self.execute_plan_with_params(&plan, params, None)?;
            self.log_slow_query(sql, start.elapsed(), returned.len() as u64);
            return Ok(returned);
        }

        // 4. Execute plan with parameters and return results
        let exec_start = std::time::Instant::now();
        let results = self.query_plan_with_params(&plan, params, None)?;
        tracing::debug!(
            phase = "execute",
            duration_us = exec_start.elapsed().as_micros() as u64,
            rows = results.len() as u64,
            "Query executed"
        );

        self.log_slow_query(sql, start.elapsed(), results.len() as u64);
        Ok(results)
    }

    /// Internal method to execute a query plan with parameters
    fn query_plan_with_params(
        &self,
        plan: &sql::LogicalPlan,
        params: &[Value],
        session_txn: Option<&storage::Transaction>,
    ) -> Result<Vec<Tuple>> {
        // Keep parameterized SELECT consistent with `query()`: explicit
        // transactions must see rows staged in the transaction write set.
        let mut _txn_guard = None;
        let active_txn: Option<&storage::Transaction> = match session_txn {
            Some(txn) => Some(txn),
            None => {
                _txn_guard = Some(
                    self.current_transaction
                        .lock(),
                );
                _txn_guard.as_ref().and_then(|guard| guard.as_ref())
            }
        };

        let mut executor = sql::Executor::with_storage(&self.storage)
            .with_timeout(self.effective_statement_timeout_ms())
            .with_parameters(params.to_vec());
        if let Some(txn_ref) = active_txn {
            executor = executor.with_transaction(txn_ref);
        }

        executor.execute(plan)
    }

    /// Run a query with `$1..$n` parameter binding and return the result rows
    /// **alongside their output column names** — the column-aware counterpart to
    /// [`query_params`](Self::query_params), and the param-aware counterpart to
    /// [`query_with_columns`](Self::query_with_columns).
    ///
    /// This is the shape language bindings need to build named/dict rows while
    /// still binding parameters safely (e.g. the PyO3 binding routes every Python
    /// `query()` call here, with an empty `params` slice when there are none).
    /// `params` substitute positionally for `$1..$n`; an empty slice behaves like
    /// `query_with_columns`. Row-level security policies are applied, as in
    /// `query_params`.
    pub fn query_params_with_columns(&self, sql: &str, params: &[Value]) -> Result<(Vec<Tuple>, Vec<String>)> {
        #[cfg(feature = "code-graph")]
        let (rewritten_owned, _branch_guard) = self.rewrite_and_scope(sql);
        #[cfg(feature = "code-graph")]
        let sql: &str = &rewritten_owned;
        #[cfg(not(feature = "code-graph"))]
        let sql: &str = sql;

        // Plan (mirroring query_with_columns' ShowBranches pre-detect), then apply
        // RLS for the planned path exactly as query_params does.
        let plan = if sql::Parser::is_show_branches(sql) {
            sql::LogicalPlan::ShowBranches
        } else {
            let (statement, _) = self.parse_cached(sql)?;
            let catalog = self.storage.catalog();
            let planner = sql::Planner::with_catalog(&catalog).with_sql(sql.to_string());
            let plan = planner.statement_to_plan(statement)?;
            self.apply_rls_to_plan(plan)?
        };

        if matches!(
            &plan,
            sql::LogicalPlan::Insert { .. }
                | sql::LogicalPlan::InsertSelect { .. }
                | sql::LogicalPlan::Update { .. }
                | sql::LogicalPlan::Delete { .. }
        ) {
            let columns = match &plan {
                sql::LogicalPlan::Insert {
                    table_name,
                    returning: Some(items),
                    ..
                }
                | sql::LogicalPlan::InsertSelect {
                    table_name,
                    returning: Some(items),
                    ..
                }
                | sql::LogicalPlan::Update {
                    table_name,
                    returning: Some(items),
                    ..
                }
                | sql::LogicalPlan::Delete {
                    table_name,
                    returning: Some(items),
                    ..
                } => {
                    let schema = self.storage.catalog().get_table_schema(table_name)?;
                    Self::returning_schema(&schema, items)
                        .columns
                        .into_iter()
                        .map(|c| c.name)
                        .collect()
                }
                _ => Vec::new(),
            };
            let (_count, rows) = self.execute_plan_with_params(&plan, params, None)?;
            return Ok((rows, columns));
        }

        // Same optimization pipeline as query_with_columns.
        let plan = {
            let stats = optimizer::cost::StatsCatalog::new();
            let rules: Vec<Box<dyn optimizer::rules::OptimizationRule>> = vec![
                Box::new(optimizer::rules::ConstantFoldingRule::new()),
                Box::new(optimizer::rules::SelectionPushdownRule::new()),
                Box::new(optimizer::rules::JoinPredicatePushdownRule::new()),
                Box::new(optimizer::rules::ProjectionPruningRule::new()),
                Box::new(optimizer::rules::StorageFilterPushdownRule::new()),
            ];
            let opt = optimizer::Optimizer::with_rules(stats, rules, optimizer::OptimizerConfig::default());
            opt.optimize_recursive(plan)?
        };

        let txn_lock = self
            .current_transaction
            .lock();
        let mut executor = sql::Executor::with_storage(&self.storage)
            .with_timeout(self.effective_statement_timeout_ms())
            .with_parameters(params.to_vec());
        if let Some(txn_ref) = txn_lock.as_ref() {
            executor = executor.with_transaction(txn_ref);
        }
        executor.execute_with_columns(&plan)
    }

    /// Begin an explicit transaction
    ///
    /// This method starts a new transaction. All subsequent SQL operations
    /// will be part of this transaction until `commit()` or `rollback()` is called.
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::EmbeddedDatabase;
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new("./data")?;
    ///
    /// // Begin transaction
    /// db.begin()?;
    ///
    /// // Execute queries in transaction
    /// db.execute("INSERT INTO users VALUES (1, 'Alice')")?;
    /// db.execute("INSERT INTO users VALUES (2, 'Bob')")?;
    ///
    /// // Commit changes
    /// db.commit()?;
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns an error if a transaction is already active.
    pub fn begin(&self) -> Result<()> {
        self.begin_transaction_internal()
    }

    /// Commit the current transaction
    ///
    /// Permanently applies all changes made during the transaction.
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::EmbeddedDatabase;
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new("./data")?;
    ///
    /// db.begin()?;
    /// db.execute("DELETE FROM users WHERE id = 1")?;
    /// db.commit()?; // Changes are now permanent
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns an error if no transaction is active.
    pub fn commit(&self) -> Result<()> {
        self.commit_internal()
    }

    /// Rollback the current transaction
    ///
    /// Discards all changes made during the transaction.
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::EmbeddedDatabase;
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new("./data")?;
    ///
    /// db.begin()?;
    /// db.execute("DELETE FROM users")?;
    /// // Oops, didn't mean to do that!
    /// db.rollback()?; // Changes are discarded
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns an error if no transaction is active.
    pub fn rollback(&self) -> Result<()> {
        self.rollback_internal()
    }

    /// Check if a transaction is currently active
    ///
    /// Returns `true` if `begin()` has been called without a matching
    /// `commit()` or `rollback()`.
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::EmbeddedDatabase;
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new("./data")?;
    ///
    /// assert!(!db.in_transaction());
    ///
    /// db.begin()?;
    /// assert!(db.in_transaction());
    ///
    /// db.commit()?;
    /// assert!(!db.in_transaction());
    /// # Ok(())
    /// # }
    /// ```
    pub fn in_transaction(&self) -> bool {
        // R2.1: lock-free — the flag mirrors `current_transaction.is_some()`
        // and is only flipped while that mutex is held.
        self.global_txn_active.load(std::sync::atomic::Ordering::Acquire)
    }

    /// Bulk-insert pre-built `Tuple` rows into a table, bypassing the
    /// SQL parser/planner/executor. Writes go directly to RocksDB
    /// (matching the convention of parameterised
    /// `INSERT … RETURNING` via `execute_plan_with_params` →
    /// `insert_tuple_versioned_with_schema`) so subsequent SQL
    /// statements within the same outer transaction see the rows
    /// without paying `merge_with_write_set` cost on a bloated DashMap.
    ///
    /// Engine-internal fast path for bulk-load callers (e.g. the
    /// code-graph indexer's symbol/ref ingestion). Skips:
    /// - SQL string allocation / sqlparser invocation / planning
    /// - FK validation (caller is responsible for parent-child order)
    /// - CHECK constraints
    /// - BEFORE/AFTER triggers
    /// - RLS enforcement
    /// - Per-row WAL log entries (RocksDB's internal WAL handles
    ///   crash recovery; we lose engine-WAL-level replication for
    ///   these rows, which is acceptable for engine-owned tables)
    ///
    /// Still performs:
    /// - PK auto-fill (NULL → row_id) for SERIAL/BIGSERIAL columns
    /// - PK / UNIQUE constraint checks via ART
    /// - ART index update
    /// - Branch-aware key encoding
    ///
    /// **Transactional caveat**: rows committed via this path are
    /// NOT rolled back if the active transaction aborts. Use only
    /// for engine-owned tables (e.g. `_hdb_code_*`, `_hdb_graph_*`)
    /// where the caller's failure recovery either TRUNCATEs and
    /// rebuilds (code_index force_reparse) or otherwise tolerates
    /// orphan rows. User-facing tables should keep going through
    /// `execute()` so triggers / RLS / FKs / rollback are honoured.
    ///
    /// Returns the allocated `row_id`s in input order.
    #[allow(dead_code)]
    pub(crate) fn bulk_insert_tuples(&self, table_name: &str, tuples: Vec<Tuple>) -> Result<Vec<u64>> {
        let catalog = self.storage.catalog();
        let schema = catalog.get_table_schema(table_name)?;

        // Candidate (c) fix: under bulk_load_mode, allocate row ids from the
        // in-memory VOLATILE counter (no per-row RocksDB counter PUT + WAL
        // UpdateCounter append) and persist the final value once after the
        // batch via flush_row_counter — the fast-INSERT path's pattern. Removes
        // ~one counter PUT + one WAL append per row on a bulk load. Non-bulk
        // callers keep the per-row persisting next_row_id() so default crash
        // semantics — and pg35 — are byte-unchanged.
        let bulk = self.storage.is_bulk_load_mode();

        let mut row_ids: Vec<u64> = Vec::with_capacity(tuples.len());
        let mut art_updates: Vec<(u64, std::collections::HashMap<String, Value>)> = Vec::with_capacity(tuples.len());

        for mut tuple in tuples {
            let row_id = if bulk {
                self.storage.next_row_id_volatile(table_name)
            } else {
                catalog.next_row_id(table_name)?
            };

            // Fill BIGSERIAL / SERIAL PK columns with the auto-allocated
            // row_id when the caller left them NULL.
            for (i, col) in schema.columns.iter().enumerate() {
                if col.primary_key {
                    if let Some(v) = tuple.values.get(i) {
                        if matches!(v, Value::Null) && i < tuple.values.len() {
                            #[allow(clippy::indexing_slicing)]
                            match col.data_type {
                                DataType::Int2 => {
                                    tuple.values[i] = Value::Int2(row_id as i16);
                                }
                                DataType::Int4 => {
                                    tuple.values[i] = Value::Int4(row_id as i32);
                                }
                                _ => {
                                    tuple.values[i] = Value::Int8(row_id as i64);
                                }
                            }
                        }
                    }
                }
            }

            // Build column-value map once — reused for both ART check
            // and on_insert.
            let mut col_values = std::collections::HashMap::with_capacity(schema.columns.len());
            for (i, col) in schema.columns.iter().enumerate() {
                if let Some(v) = tuple.values.get(i) {
                    col_values.insert(col.name.clone(), v.clone());
                }
            }

            // PK / UNIQUE check before committing the write.
            if let Err(e) = self
                .storage
                .art_indexes()
                .check_unique_constraints(table_name, &col_values)
            {
                return Err(Error::constraint_violation(e.to_string()));
            }

            // Direct RocksDB write — bypasses txn.write_set so
            // subsequent SQL statements in the outer txn don't pay
            // O(N) merge_with_write_set cost.
            let val =
                bincode::serialize(&tuple).map_err(|e| Error::storage(format!("Failed to serialize tuple: {}", e)))?;
            let key = self.storage.branch_aware_data_key(table_name, row_id);
            self.storage.put(&key, &val)?;

            // R5.V1: maintain HNSW vector indexes. Like the ART update below,
            // this direct-write bulk path is not transactional (no undo).
            if self.vector_dml_gate(table_name) {
                let _ = self
                    .storage
                    .vector_indexes()
                    .on_row_insert(table_name, row_id, &schema, &tuple);
            }

            art_updates.push((row_id, col_values));
            row_ids.push(row_id);
        }

        for (row_id, col_values) in art_updates {
            if let Err(e) = self.storage.art_indexes().on_insert(table_name, row_id, &col_values) {
                tracing::debug!("ART on_insert {}: {}", table_name, e);
            }
        }

        // Bulk path bypasses the SQL execute pipeline, so the
        // engine-managed result cache doesn't see this DML. Result rows ARE
        // stale after an insert, so always invalidate them (cheap — gated by
        // result_cache_nonempty).
        self.invalidate_result_cache();
        // Item 1b (3.57.0 write-path regression): a LogicalPlan is query
        // STRUCTURE and is NOT invalidated by data inserts (only schema
        // changes invalidate plans). Clearing the entire plan cache on every
        // bulk_insert_tuples call was therefore unnecessary for correctness and
        // was the dominant ingest write-path regression — one full
        // ShardedLruCache clear per chunk, which also forced every interleaved
        // DELETE/UPDATE in a bulk load to re-parse + re-plan from cold. Skip it
        // under bulk_load_mode (the opt-in bulk path). Non-bulk callers keep the
        // prior clear, so default behavior — and pg35 — is byte-unchanged.
        if !self.storage.is_bulk_load_mode() {
            self.plan_cache.clear();
        }

        // Candidate (c): persist the row-id counter ONCE after the bulk batch
        // (it was bumped in-memory only above under bulk_load_mode). Outside
        // bulk_load_mode the per-row next_row_id() already persisted it.
        if bulk {
            self.storage.flush_row_counter(table_name)?;
        }

        Ok(row_ids)
    }

    /// Begin a transaction (DEPRECATED - use `begin()` instead)
    ///
    /// This method is deprecated and will be removed in a future version.
    /// Use `begin()`, `commit()`, and `rollback()` instead for better
    /// transaction control.
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// use heliosdb_nano::EmbeddedDatabase;
    ///
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let db = EmbeddedDatabase::new("./data")?;
    /// let tx = db.begin_transaction()?;
    /// // ... perform operations
    /// tx.commit()?;
    /// # Ok(())
    /// # }
    /// ```
    #[deprecated(since = "2.1.0", note = "Use `begin()`, `commit()`, and `rollback()` instead")]
    pub fn begin_transaction(&self) -> Result<Transaction<'_>> {
        let tx = self.storage.begin_transaction()?;
        Ok(Transaction { tx, db: self })
    }

    /// Get the current WAL LSN (Log Sequence Number)
    ///
    /// Returns the current position in the Write-Ahead Log.
    /// Useful for debugging and transaction tracking.
    pub fn current_lsn(&self) -> Option<u64> {
        // Return the last snapshot transaction ID for time-travel queries
        // This is the ID users should use with AS OF TRANSACTION
        let txn_id = self.storage.snapshot_manager().current_transaction_id();
        // Return the last registered ID (current - 1, since current is the next to be assigned)
        if txn_id > 1 {
            Some(txn_id - 1)
        } else {
            // No transactions yet, but show 0 to indicate starting point
            Some(0)
        }
    }

    /// Close the database
    ///
    /// Flushes pending data and releases resources. The database will also
    /// be cleaned up automatically when dropped.
    pub fn close(self) -> Result<()> {
        // Storage engine cleanup happens via Drop
        // If we're the sole Arc owner, RocksDB will flush on drop
        Ok(())
    }

    // Vector store operations - backed by VectorIndexManager

    /// List all vector stores
    pub fn list_vector_stores(&self) -> Result<Vec<VectorStoreInfo>> {
        use crate::vector::DistanceMetric;

        let vector_mgr = self.storage.vector_indexes();
        let metadata_list = vector_mgr.list_all_metadata();

        Ok(metadata_list
            .iter()
            .map(|meta| {
                // Get vector count if possible
                let (vector_count, metric, index_type) = match vector_mgr.get_index_stats(&meta.name) {
                    Ok(stats) => (
                        stats.num_vectors as u64,
                        match &meta.index_type {
                            storage::VectorIndexType::Standard(cfg) => match cfg.distance_metric {
                                DistanceMetric::L2 => "l2".to_string(),
                                DistanceMetric::Cosine => "cosine".to_string(),
                                DistanceMetric::InnerProduct => "inner_product".to_string(),
                            },
                            storage::VectorIndexType::Quantized(cfg) => match cfg.distance_metric {
                                DistanceMetric::L2 => "l2".to_string(),
                                DistanceMetric::Cosine => "cosine".to_string(),
                                DistanceMetric::InnerProduct => "inner_product".to_string(),
                            },
                            storage::VectorIndexType::Persistent(cfg) => match cfg.distance_metric {
                                DistanceMetric::L2 => "l2".to_string(),
                                DistanceMetric::Cosine => "cosine".to_string(),
                                DistanceMetric::InnerProduct => "inner_product".to_string(),
                            },
                        },
                        match &meta.index_type {
                            storage::VectorIndexType::Standard(_) => "hnsw".to_string(),
                            storage::VectorIndexType::Quantized(_) => "hnsw_pq".to_string(),
                            storage::VectorIndexType::Persistent(cfg) => if cfg.pq_enabled {
                                "persistent_pq_hnsw"
                            } else {
                                "persistent_hnsw"
                            }
                            .to_string(),
                        },
                    ),
                    Err(_) => (0, "cosine".to_string(), "hnsw".to_string()),
                };

                let dimensions = meta.dimension() as u32;

                VectorStoreInfo {
                    name: meta.name.clone(),
                    dimensions,
                    vector_count,
                    created_at: "N/A".to_string(),
                    metric,
                    index_type,
                }
            })
            .collect())
    }

    /// Create a new vector store
    pub fn create_vector_store(&self, name: &str, dimensions: u32) -> Result<VectorStoreInfo> {
        self.create_vector_store_with_options(name, dimensions, "cosine", "hnsw")
    }

    pub fn create_vector_store_with_options(
        &self,
        name: &str,
        dimensions: u32,
        metric: &str,
        index_type: &str,
    ) -> Result<VectorStoreInfo> {
        let vector_mgr = self.storage.vector_indexes();
        let distance_metric = parse_vector_metric(metric)?;
        let normalized_index_type = index_type.to_ascii_lowercase();

        match normalized_index_type.as_str() {
            "persistent_hnsw" | "persistent" => vector_mgr.create_persistent_index(
                name.to_string(),
                name.to_string(),
                "embedding".to_string(),
                dimensions as usize,
                distance_metric,
                None,
                None,
                &[],
                self.storage.db(),
            )?,
            // R5.V6: construction parameters come from the `[vector]`
            // config section instead of being hardcoded to 16/200.
            "hnsw" => vector_mgr.create_index_with_params(
                name.to_string(),
                name.to_string(),
                "embedding".to_string(),
                dimensions as usize,
                distance_metric,
                self.storage.config().vector.hnsw_m,
                self.storage.config().vector.hnsw_ef_construction,
            )?,
            other => {
                return Err(Error::query_execution(format!(
                    "Unsupported vector store index_type '{}'; supported values are hnsw and persistent_hnsw",
                    other
                )));
            }
        }

        Ok(VectorStoreInfo {
            name: name.to_string(),
            dimensions,
            vector_count: 0,
            created_at: chrono::Utc::now().to_rfc3339(),
            metric: metric.to_string(),
            index_type: normalized_index_type,
        })
    }

    /// Get vector store info
    pub fn get_vector_store(&self, name: &str) -> Result<VectorStoreInfo> {
        use crate::vector::DistanceMetric;

        let vector_mgr = self.storage.vector_indexes();

        let meta = vector_mgr.get_metadata(name)?;
        let stats = vector_mgr.get_index_stats(name)?;

        let metric = match &meta.index_type {
            storage::VectorIndexType::Standard(cfg) => match cfg.distance_metric {
                DistanceMetric::L2 => "l2".to_string(),
                DistanceMetric::Cosine => "cosine".to_string(),
                DistanceMetric::InnerProduct => "inner_product".to_string(),
            },
            storage::VectorIndexType::Quantized(cfg) => match cfg.distance_metric {
                DistanceMetric::L2 => "l2".to_string(),
                DistanceMetric::Cosine => "cosine".to_string(),
                DistanceMetric::InnerProduct => "inner_product".to_string(),
            },
            storage::VectorIndexType::Persistent(cfg) => match cfg.distance_metric {
                DistanceMetric::L2 => "l2".to_string(),
                DistanceMetric::Cosine => "cosine".to_string(),
                DistanceMetric::InnerProduct => "inner_product".to_string(),
            },
        };

        let index_type = match &meta.index_type {
            storage::VectorIndexType::Standard(_) => "hnsw".to_string(),
            storage::VectorIndexType::Quantized(_) => "hnsw_pq".to_string(),
            storage::VectorIndexType::Persistent(cfg) => if cfg.pq_enabled {
                "persistent_pq_hnsw"
            } else {
                "persistent_hnsw"
            }
            .to_string(),
        };

        Ok(VectorStoreInfo {
            name: name.to_string(),
            dimensions: stats.dimensions as u32,
            vector_count: stats.num_vectors as u64,
            created_at: "N/A".to_string(),
            metric,
            index_type,
        })
    }

    /// Delete a vector store
    pub fn delete_vector_store(&self, name: &str) -> Result<()> {
        let vector_mgr = self.storage.vector_indexes();
        vector_mgr.drop_index(name)
    }

    /// Insert vectors into a store
    ///
    /// Returns a list of generated vector IDs
    pub fn insert_vectors(&self, store: &str, vectors: Vec<Vec<f32>>) -> Result<Vec<String>> {
        self.insert_vectors_with_options(store, None, vectors, None, None)
    }

    pub fn insert_vectors_with_options(
        &self,
        store: &str,
        ids: Option<Vec<String>>,
        vectors: Vec<Vec<f32>>,
        metadata: Option<Vec<std::collections::HashMap<String, serde_json::Value>>>,
        namespace: Option<String>,
    ) -> Result<Vec<String>> {
        let vector_mgr = self.storage.vector_indexes();

        // Verify store exists
        let _ = vector_mgr.get_metadata(store)?;

        if let Some(ref requested_ids) = ids {
            if requested_ids.len() != vectors.len() {
                return Err(Error::query_execution(
                    "Number of vector IDs must match number of vectors".to_string(),
                ));
            }
        }
        if let Some(ref metadata_items) = metadata {
            if metadata_items.len() != vectors.len() {
                return Err(Error::query_execution(
                    "Number of metadata entries must match number of vectors".to_string(),
                ));
            }
        }

        let mut inserted_ids = Vec::with_capacity(vectors.len());

        for (idx, vector) in vectors.into_iter().enumerate() {
            let row_id = self.storage.next_timestamp();
            let id_str = ids
                .as_ref()
                .and_then(|requested_ids| requested_ids.get(idx).cloned())
                .unwrap_or_else(|| format!("vec_{}", row_id));
            let meta = metadata.as_ref().and_then(|items| items.get(idx).cloned());
            vector_mgr.insert_vector_record(store, row_id, id_str.clone(), &vector, meta, namespace.clone())?;

            inserted_ids.push(id_str);
        }

        Ok(inserted_ids)
    }

    /// Upsert vectors (insert or update)
    pub fn upsert_vectors(&self, store: &str, vectors: Vec<(String, Vec<f32>)>) -> Result<()> {
        let ids: Vec<String> = vectors.iter().map(|(id, _)| id.clone()).collect();
        let values: Vec<Vec<f32>> = vectors.into_iter().map(|(_, vector)| vector).collect();
        let _ = self.delete_vectors(store, ids.clone());
        self.insert_vectors_with_options(store, Some(ids), values, None, None)?;
        Ok(())
    }

    pub fn upsert_vectors_with_options(
        &self,
        store: &str,
        ids: Vec<String>,
        vectors: Vec<Vec<f32>>,
        metadata: Option<Vec<std::collections::HashMap<String, serde_json::Value>>>,
        namespace: Option<String>,
    ) -> Result<()> {
        let _ = self.delete_vectors(store, ids.clone());
        self.insert_vectors_with_options(store, Some(ids), vectors, metadata, namespace)?;
        Ok(())
    }

    fn upsert_vectors_legacy(&self, store: &str, vectors: Vec<(String, Vec<f32>)>) -> Result<()> {
        let vector_mgr = self.storage.vector_indexes();

        // Verify store exists
        let _ = vector_mgr.get_metadata(store)?;

        for (id_str, vector) in vectors {
            // Parse ID from string (format: vec_123)
            let id = id_str
                .strip_prefix("vec_")
                .and_then(|s| s.parse::<u64>().ok())
                .unwrap_or_else(|| {
                    // Generate new ID for non-standard IDs
                    self.storage.next_timestamp()
                });

            let _ = vector_mgr.delete_vector(store, id);
            vector_mgr.insert_vector_record(store, id, id_str, &vector, None, None)?;
        }

        Ok(())
    }

    /// Search for similar vectors
    ///
    /// Returns (vector_id, distance) pairs sorted by similarity
    pub fn search_vectors(&self, store: &str, query: Vec<f32>, k: usize) -> Result<Vec<(String, f32)>> {
        let vector_mgr = self.storage.vector_indexes();

        // Verify store exists
        let _ = vector_mgr.get_metadata(store)?;

        let results = vector_mgr.search_with_filters(store, &query, k, None, None)?;

        // Convert row_ids to string IDs
        Ok(results.into_iter().map(|result| (result.id, result.score)).collect())
    }

    pub fn search_vectors_with_options(
        &self,
        store: &str,
        query: Vec<f32>,
        k: usize,
        filter: Option<&std::collections::HashMap<String, serde_json::Value>>,
        namespace: Option<&str>,
    ) -> Result<Vec<storage::StoredVectorSearchResult>> {
        let vector_mgr = self.storage.vector_indexes();
        let _ = vector_mgr.get_metadata(store)?;
        vector_mgr.search_with_filters(store, &query, k, filter, namespace)
    }

